{display_name:`Load Image (as Mask)`,inputs:{image:{name:`image`},channel:{name:`channel`},upload:{name:`choose file to upload`}}},xCn={display_name:`Load Image (from Outputs)`,description:`Load an image from the output folder. When the refresh button is clicked, the node will update the image list and automatically select the first image, allowing for easy iteration.`,inputs:{image:{name:`image`},"Auto-refresh after generation":{},refresh:{},upload:{name:`choose file to upload`}}},SCn={display_name:`Load Image-Text (from Folder)`,description:`Load a dataset of pairs of images and text captions from a specified folder and return them as a list. Supported formats: PNG, JPG, JPEG, WEBP.`,inputs:{folder:{name:`folder`,tooltip:`The folder to load images and text captions from.`}},outputs:{0:{name:`images`,tooltip:`List of loaded images`},1:{name:`texts`,tooltip:`List of text captions`}}},CCn={display_name:`Load Latent`,inputs:{latent:{name:`latent`}}},wCn={display_name:`Load Face Detection Model (MediaPipe)`,inputs:{model_name:{name:`model_name`,tooltip:`Face detection model from models/detection/.`}},outputs:{0:{tooltip:null}}},TCn={display_name:`Load MoGe Model`,inputs:{model_name:{name:`model_name`}},outputs:{0:{tooltip:null}}},ECn={display_name:`Load Training Dataset`,description:`Load encoded training dataset (latents + conditioning) from disk for use in training.`,inputs:{folder_name:{name:`folder_name`,tooltip:`Saved dataset to load, from the datasets directory.`}},outputs:{0:{name:`latents`,tooltip:`List of latent dicts`},1:{name:`conditioning`,tooltip:`List of conditioning lists`}}},DCn={display_name:`Load Video`,inputs:{file:{name:`file`},upload:{name:`choose file to upload`}},outputs:{0:{tooltip:null}}},OCn={display_name:`Load Video (from Folder)`,description:`Load a dataset of videos from a specified folder and return a list of videos. Supported formats: MP4, AVI, MOV, WEBM, MKV, FLV.`,inputs:{folder:{name:`folder`,tooltip:`The folder containing video files.`}},outputs:{0:{name:`videos`,tooltip:`Lazy video references; frames are decoded only when needed downstream.`}}},kCn={display_name:`Load Video-Text (from Folder)`,description:`Load a dataset of pairs of videos and text captions from a specified folder and return them as a list. Supported formats: MP4, AVI, MOV, WEBM, MKV, FLV.`,inputs:{folder:{name:`folder`,tooltip:`The folder containing video files and .txt captions.`}},outputs:{0:{name:`videos`,tooltip:`Lazy video references; frames are decoded only when needed downstream.`},1:{name:`texts`,tooltip:`List of text captions.`}}},ACn={display_name:`LoopIteration`,inputs:{iteration_index:{name:`iteration_index`},is_first:{name:`is_first`},is_last:{name:`is_last`},reuse_cache:{name:`reuse_cache`},list_item:{name:`list_item`},current_iteration_value:{name:`current_iteration_value`}},outputs:{0:{tooltip:null},1:{tooltip:null},2:{tooltip:null},3:{tooltip:null},4:{tooltip:null}}},jCn={display_name:`LoopProgress`,inputs:{start_id:{name:`start_id`},position:{name:`position`},total:{name:`total`}},outputs:{0:{tooltip:null}}},MCn={display_name:`LoopResult`,inputs:{close_id:{name:`close_id`}}},NCn={display_name:`Load LoRA (Model and CLIP)`,description:`This LoRA loader is used to modify both diffusion and CLIP models, altering the way in which latents are denoised such as applying styles. Multiple LoRA nodes can be linked together.`,inputs:{model:{name:`model`,tooltip:`The diffusion model the LoRA will be applied to.`},clip:{name:`clip`,tooltip:`The CLIP model the LoRA will be applied to.`},lora_name:{name:`lora_name`,tooltip:`The name of the LoRA.`},strength_model:{name:`strength_model`,tooltip:`How strongly to modify the diffusion model. This value can be negative.`},strength_clip:{name:`strength_clip`,tooltip:`How strongly to modify the CLIP model. This value can be negative.`}},outputs:{0:{tooltip:`The modified diffusion model.`},1:{tooltip:`The modified CLIP model.`}}},PCn={display_name:`Load LoRA (Bypass) (For debugging)`,description:`Apply LoRA in bypass mode. Unlike regular LoRA, this doesn't modify model weights - instead it injects the LoRA computation during forward pass. Useful for training scenarios.`,inputs:{model:{name:`model`,tooltip:`The diffusion model the LoRA will be applied to.`},clip:{name:`clip`,tooltip:`The CLIP model the LoRA will be applied to.`},lora_name:{name:`lora_name`,tooltip:`The name of the LoRA.`},strength_model:{name:`strength_model`,tooltip:`How strongly to modify the diffusion model. This value can be negative.`},strength_clip:{name:`strength_clip`,tooltip:`How strongly to modify the CLIP model. This value can be negative.`}},outputs:{0:{tooltip:`The modified diffusion model.`},1:{tooltip:`The modified CLIP model.`}}},FCn={display_name:`Load LoRA (Bypass, Model Only) (for debugging)`,description:`Apply LoRA in bypass mode. Unlike regular LoRA, this doesn't modify model weights - instead it injects the LoRA computation during forward pass. Useful for training scenarios.`,inputs:{model:{name:`model`},lora_name:{name:`lora_name`},strength_model:{name:`strength_model`}},outputs:{0:{tooltip:`The modified diffusion model.`}}},ICn={display_name:`Load LoRA`,description:`This LoRAs loader is used to modify the diffusion model, altering the way in which latents are denoised such as applying styles. Multiple LoRA nodes can be linked together.`,inputs:{model:{name:`model`},lora_name:{name:`lora_name`},strength_model:{name:`strength_model`}},outputs:{0:{tooltip:`The modified diffusion model.`}}},LCn={display_name:`Load LoRA Model`,inputs:{model:{name:`model`,tooltip:`The diffusion model the LoRA will be applied to.`},lora:{name:`lora`,tooltip:`The LoRA model to apply to the diffusion model.`},strength_model:{name:`strength_model`,tooltip:`How strongly to modify the diffusion model. This value can be negative.`},bypass:{name:`bypass`,tooltip:`When enabled, applies LoRA in bypass mode without modifying base model weights. Useful for training and when model weights are offloaded.`}},outputs:{0:{name:`model`,tooltip:`The modified diffusion model.`}}},RCn={display_name:`Extract and Save Lora`,inputs:{filename_prefix:{name:`filename_prefix`},rank:{name:`rank`},lora_type:{name:`lora_type`},bias_diff:{name:`bias_diff`},model_diff:{name:`model_diff`,tooltip:`The ModelSubtract output to be converted to a lora.`},text_encoder_diff:{name:`text_encoder_diff`,tooltip:`The CLIPSubtract output to be converted to a lora.`}}},zCn={display_name:`Plot Loss Graph`,inputs:{loss:{name:`loss`,tooltip:`Loss map from training node.`},filename_prefix:{name:`filename_prefix`,tooltip:`Prefix for the saved loss graph image.`}}},BCn={display_name:`LotusConditioning`,outputs:{0:{name:`conditioning`,tooltip:null}}},VCn={display_name:`LTX 2.5 Audio To Video`,description:`Generate a video driven by an audio track, with an optional first frame image.`,inputs:{audio:{name:`audio`,tooltip:`Audio track driving the video. Its length (2-20 seconds) sets the video duration.`},model:{name:`model`},prompt:{name:`prompt`},seed:{name:`seed`,tooltip:`Seed to determine if node should re-run; actual results are nondeterministic regardless of seed.`},image:{name:`image`,tooltip:`Optional first frame to be used for the video.`},control_after_generate:{name:`control after generate`},model_resolution:{name:`resolution`}},outputs:{0:{tooltip:null}}},HCn={display_name:`LTX 2.5 Image To Video`,description:`Professional-quality videos with customizable duration and resolution based on start image.`,inputs:{image:{name:`image`,tooltip:`First frame to be used for the video.`},model:{name:`model`},prompt:{name:`prompt`},seed:{name:`seed`,tooltip:`Seed to determine if node should re-run; actual results are nondeterministic regardless of seed.`},last_frame:{name:`last_frame`,tooltip:`Last frame to be used for the video.`},control_after_generate:{name:`control after generate`},model_duration:{name:`duration`},model_fps:{name:`fps`},model_generate_audio:{name:`generate_audio`},model_resolution:{name:`resolution`}},outputs:{0:{tooltip:null}}},UCn={display_name:`LTX 2.5 Text To Video`,description:`Professional-quality videos with customizable duration and resolution.`,inputs:{model:{name:`model`},prompt:{name:`prompt`},seed:{name:`seed`,tooltip:`Seed to determine if node should re-run; actual results are nondeterministic regardless of seed.`},control_after_generate:{name:`control after generate`},model_duration:{name:`duration`},model_fps:{name:`fps`},model_generate_audio:{name:`generate_audio`},model_resolution:{name:`resolution`}},outputs:{0:{tooltip:null}}},WCn={display_name:`Load LTXV Audio Text Encoder`,description:`Recipes:
ltxav: gemma 3 12B or matching gemma 4 model`,inputs:{text_encoder:{name:`text_encoder`},ckpt_name:{name:`ckpt_name`},device:{name:`device`}},outputs:{0:{tooltip:null}}},GCn={display_name:`LTXV Add Generated Keyframes`,description:`Append detailing keyframes to a video latent. Each keyframe is one latent frame of tokens whose RoPE position spans a single pixel frame; they are denoised with the video and are not part of the decoded output. Placement is one slot every interval_frames pixels, skipping I2V frames, existing guides, and detailing keyframes already on the cond. Connected keyframes are content only and are re-placed on this canvas unless frame_indices is set. Pull them back out with LTXV Separate Generated Keyframes. Requires a checkpoint trained for generated keyframes (one carrying keyframes_abs_pos_embedding).`,inputs:{positive:{name:`positive`,tooltip:`Positive conditioning the keyframes are attached to.`},negative:{name:`negative`,tooltip:`Negative conditioning the keyframes are attached to.`},vae:{name:`vae`,tooltip:`Only used to read the latent scale factors.`},latent:{name:`latent`,tooltip:`Plain 5D video latent to generate keyframes alongside. Add them before Concat AV Latent.`},interval_frames:{name:`interval_frames`,tooltip:`Pixel-frame stride for auto placement. Default 24 is about one keyframe per second at 24 fps. Occupied pixels are skipped. Ignored when frame_indices is set.`},keyframes:{name:`keyframes`,tooltip:`Optional content to initialize the new keyframes with. Connect keyframes from an earlier Separate (same spatial size), or a plain video latent to copy the nearest frame at each new slot (e.g. after temporal upscale). These are still denoised, not pinned as guides. Recorded indices on a keyframes latent are ignored unless frame_indices is set. Only has an effect when sampling starts below sigma 1.`},frame_indices:{name:`frame_indices`,tooltip:`Optional pixel-frame indices. Leave empty to place from interval_frames on the current canvas. When set, this list is the placement (connected keyframes are matched in order). The last frame is allowed; frame 0 is not (it is already a standalone token).`}},outputs:{0:{name:`positive`,tooltip:`Positive conditioning with generated-keyframe attention attached.`},1:{name:`negative`,tooltip:`Negative conditioning with generated-keyframe attention attached.`},2:{name:`latent`,tooltip:`Video latent with generated keyframes appended on T.`}}},KCn={display_name:`LTXVAddGuide`,inputs:{positive:{name:`positive`},negative:{name:`negative`},vae:{name:`vae`},latent:{name:`latent`},image:{name:`image`,tooltip:`Image or video to condition the latent video on. Must be 8*n + 1 frames. If the video is not 8*n + 1 frames, it will be cropped to the nearest 8*n + 1 frames.`},frame_idx:{name:`frame_idx`,tooltip:`Frame index to start the conditioning at. For single-frame images or videos with 1-8 frames, any frame_idx value is acceptable. For videos with 9+ frames, frame_idx must be divisible by 8, otherwise it will be rounded down to the nearest multiple of 8. Negative values are counted from the end of the video.`},strength:{name:`strength`},attention_mask:{name:`attention_mask`,tooltip:`Optional pixel-space spatial mask. Controls per-region conditioning influence via self-attention, multiplied by strength.`},iclora_parameters:{name:`iclora_parameters`,tooltip:`Optional IC-LoRA parameters from a Get IC-LoRA Parameters node. Used for adjusting guide processing as required by certain IC-LoRAs (eg. those with a reference_downscale_factor > 1). When chained, each LTXVAddGuide uses only the parameters connected to it.`}},outputs:{0:{name:`positive`,tooltip:null},1:{name:`negative`,tooltip:null},2:{name:`latent`,tooltip:null}}},qCn={display_name:`LTXV Add Latent Guide`,description:`Pins an already-encoded latent as a guide, for when the guide comes out of an earlier stage rather than an image. Same effect as LTXV Add Guide without the VAE decode/encode round trip. A guide that is spatially smaller than the target (an IC-LoRA or detailing reference) is dilated onto a sparse grid, and its RoPE end positions are expanded by the same ratio so it covers the target canvas instead of addressing only the top-left corner of it.`,inputs:{positive:{name:`positive`},negative:{name:`negative`},vae:{name:`vae`},latent:{name:`latent`,tooltip:`Target video latent the guide is pinned onto.`},guiding_latent:{name:`guiding_latent`,tooltip:`Guide latent. Its spatial size must divide the target's by the same whole number on both axes; equal size pins it as-is, half size is treated as an x2 IC-LoRA reference.`},latent_idx:{name:`latent_idx`,tooltip:`Latent frame index to start the guide at, counted in latent frames rather than pixel frames. Negative values place the guide on frames before the start of the latent, not counted back from its end.`},strength:{name:`strength`,tooltip:`Capped at 1.0. A dilated guide marks its padding positions with a negative denoise mask so the model drops them; above 1.0 the kept positions would go negative too and the whole guide would be dropped. Amplify beyond 1.0 with attention_mask instead.`},attention_mask:{name:`attention_mask`,tooltip:`Optional pixel-space spatial mask. Controls per-region conditioning influence via self-attention, multiplied by strength.`}},outputs:{0:{name:`positive`,tooltip:null},1:{name:`negative`,tooltip:null},2:{name:`latent`,tooltip:null}}},JCn={display_name:`LTXV Audio VAE Decode`,inputs:{samples:{name:`samples`,tooltip:`The latent to be decoded.`},audio_vae:{name:`audio_vae`,tooltip:`The Audio VAE model used for decoding the latent.`}},outputs:{0:{name:`Audio`,tooltip:null}}},YCn={display_name:`LTXV Audio VAE Encode`,inputs:{audio:{name:`audio`,tooltip:`The audio to be encoded.`},audio_vae:{name:`audio_vae`,tooltip:`The Audio VAE model to use for encoding.`}},outputs:{0:{name:`Audio Latent`,tooltip:null}}},XCn={display_name:`Load LTXV Audio VAE`,inputs:{ckpt_name:{name:`ckpt_name`,tooltip:`Audio VAE checkpoint to load.`}},outputs:{0:{name:`Audio VAE`,tooltip:null}}},ZCn={display_name:`Concat AV Latent`,description:`Merge a video latent and an audio latent into a joint AV latent (any AV model, e.g. LTXV or MiniMax H3).`,inputs:{video_latent:{name:`video_latent`},audio_latent:{name:`audio_latent`}},outputs:{0:{name:`latent`,tooltip:null}}},QCn={display_name:`LTXVConditioning`,inputs:{positive:{name:`positive`},negative:{name:`negative`},frame_rate:{name:`frame_rate`}},outputs:{0:{name:`positive`,tooltip:null},1:{name:`negative`,tooltip:null}}},$Cn={display_name:`LTXV Context Windows`,description:`Set context windows for LTXV-like models.`,inputs:{model:{name:`model`,tooltip:`The model to apply context windows to during sampling.`},context_length:{name:`context_length`,tooltip:`The length of the context window in real frames. Must be 8*n + 1.`},context_overlap:{name:`context_overlap`,tooltip:`The overlap of the context window in real frames.`},context_schedule:{name:`context_schedule`,tooltip:`Step-dependent scheduling algorithm for context windows.`},context_stride:{name:`context_stride`,tooltip:`The stride of the context window; only applicable to uniform schedules.`},closed_loop:{name:`closed_loop`,tooltip:`Whether to close the context window loop; only applicable to looped schedules.`},fuse_method:{name:`fuse_method`,tooltip:`The method to use to fuse the context windows.`},freenoise:{name:`freenoise`,tooltip:`Whether to apply FreeNoise noise shuffling, improves window blending.`},retain_first_frame:{name:`retain_first_frame`,tooltip:`Retain the first latent frame in every context window (may help retain initial reference).`},split_conds_to_windows:{name:`split_conds_to_windows`,tooltip:`Whether to split multiple conditionings (created by ConditionCombine) to each window based on region index.`}},outputs:{0:{tooltip:`The model with context windows applied during sampling.`}}},ewn={display_name:`LTXVCropGuides`,inputs:{positive:{name:`positive`},negative:{name:`negative`},latent:{name:`latent`}},outputs:{0:{name:`positive`,tooltip:null},1:{name:`negative`,tooltip:null},2:{name:`latent`,tooltip:null}}},twn={display_name:`LTXV Dual CFG Guider`,description:`Separate CFG scales for the video and audio modalities of a packed LTXV-AV latent.`,inputs:{model:{name:`model`},positive:{name:`positive`},negative:{name:`negative`},video_cfg:{name:`video_cfg`},audio_cfg:{name:`audio_cfg`}},outputs:{0:{tooltip:null}}},nwn={display_name:`LTXV Duration Predictor`,description:`Predicts the natural shot duration for a prompt using the LTX 2.4 duration head (loaded with ModelPatchLoader), and snaps it to the VAE's 8k+1 frame grid.`,inputs:{model:{name:`model`},positive:{name:`positive`},duration_head:{name:`duration_head`,tooltip:`LTX 2.4 duration head loaded with ModelPatchLoader.`},frame_rate:{name:`frame_rate`},min_seconds:{name:`min_seconds`},max_seconds:{name:`max_seconds`}},outputs:{0:{name:`num_frames`,tooltip:null},1:{name:`seconds`,tooltip:`Raw (unclamped) predicted duration.`}}},rwn={display_name:`Empty LTXV Latent Audio`,inputs:{frames_number:{name:`frames_number`,tooltip:`Number of frames.`},frame_rate:{name:`frame_rate`,tooltip:`Number of frames per second.`},batch_size:{name:`batch_size`,tooltip:`The number of latent audio samples in the batch.`},audio_vae:{name:`audio_vae`,tooltip:`The Audio VAE model to get configuration from.`}},outputs:{0:{name:`Latent`,tooltip:null}}},iwn={display_name:`LTXV Freeze Latent`,description:`Set noise_mask to 0 so this latent is kept clean during sampling. Works on video or audio. Typical uses: freeze audio before Concat AV so it only provides cross-attention, or freeze any latent that should not be denoised.`,inputs:{latent:{name:`latent`,tooltip:`Video or audio latent to freeze. Audio is 4D; video is 5D.`}},outputs:{0:{name:`latent`,tooltip:null}}},awn={display_name:`LTXV Generated Keyframes to Guides`,description:`Pin generated keyframes from an earlier stage as frozen image guides on a later canvas. They are decoded as standalone frames, resized if needed, and written with noise_mask=0 so they are not denoised again. After a temporal upscale, recorded indices are scaled from the canvas they were generated on onto this one (same moments). Use override_frame_indices to set positions explicitly. To keep generating (and denoising) keyframes at new positions, use Add Generated Keyframes instead.`,inputs:{positive:{name:`positive`},negative:{name:`negative`},vae:{name:`vae`},latent:{name:`latent`,tooltip:`The target video latent to add the guides to, e.g. the temporally upscaled one.`},keyframes:{name:`keyframes`,tooltip:`The keyframes output of LTXV Separate Generated Keyframes, which carries the pixel frame index each keyframe was generated at.`},strength:{name:`strength`,tooltip:`Guide strength. 1.0 is a hard pin; lower values relax it.`},override_frame_indices:{name:`override_frame_indices`,tooltip:`Optional — pin at these pixel frames instead of the recorded (or auto-scaled) positions. Provide one index per keyframe. Leave empty to reuse recorded positions, or to scale them when the target canvas is a different length (e.g. after temporal x2).`}},outputs:{0:{name:`positive`,tooltip:`Positive conditioning with the keyframes pinned as image guides.`},1:{name:`negative`,tooltip:`Negative conditioning with the keyframes pinned as image guides.`},2:{name:`latent`,tooltip:`Target video latent with the keyframes added as frozen guides.`}}},own={display_name:`LTXVImgToVideo`,inputs:{positive:{name:`positive`},negative:{name:`negative`},vae:{name:`vae`},image:{name:`image`},width:{name:`width`},height:{name:`height`},length:{name:`length`},batch_size:{name:`batch_size`},strength:{name:`strength`}},outputs:{0:{name:`positive`,tooltip:null},1:{name:`negative`,tooltip:null},2:{name:`latent`,tooltip:null}}},swn={display_name:`LTXVImgToVideoInplace`,inputs:{vae:{name:`vae`},image:{name:`image`},latent:{name:`latent`},strength:{name:`strength`},bypass:{name:`bypass`,tooltip:`Bypass the conditioning.`}},outputs:{0:{name:`latent`,tooltip:null}}},cwn={display_name:`LTXVLatentUpsampler`,inputs:{samples:{name:`samples`},upscale_model:{name:`upscale_model`},vae:{name:`vae`}},outputs:{0:{tooltip:null}}},lwn={display_name:`LTXV Modality Guidance (A/V coupling)`,description:`Cross-modal (audio-video) guidance for LTXV-AV. Runs one extra forward pass per step with the a2v/v2a cross-attention severed, then pushes the result toward the coupled prediction - strengthening audio-visual sync (e.g. lip-sync). Reference default modality_scale is 3.0. Stacks with the dual-CFG guider and STG. Set to 1.0 to disable (no extra pass).`,inputs:{model:{name:`model`},modality_scale:{name:`modality_scale`},start_percent:{name:`start_percent`},end_percent:{name:`end_percent`}},outputs:{0:{tooltip:null}}},uwn={display_name:`LTXV Preprocess`,inputs:{image:{name:`image`},img_compression:{name:`img_compression`,tooltip:`Amount of compression to apply on image.`}},outputs:{0:{name:`output_image`,tooltip:null}}},dwn={display_name:`LTXV Reference Audio (ID-LoRA)`,description:`Set reference audio for ID-LoRA speaker identity transfer. Encodes a reference audio clip into the conditioning and optionally patches the model with identity guidance (extra forward pass without reference, amplifying the speaker identity effect).`,inputs:{model:{name:`model`},positive:{name:`positive`},negative:{name:`negative`},reference_audio:{name:`reference_audio`,tooltip:`Reference audio clip whose speaker identity to transfer. ~5 seconds recommended (training duration). Shorter or longer clips may degrade voice identity transfer.`},audio_vae:{name:`audio_vae`,tooltip:`LTXV Audio VAE for encoding.`},identity_guidance_scale:{name:`identity_guidance_scale`,tooltip:`Strength of identity guidance. Runs an extra forward pass without reference each step to amplify speaker identity. Set to 0 to disable (no extra pass).`},start_percent:{name:`start_percent`,tooltip:`Start of the sigma range where identity guidance is active.`},end_percent:{name:`end_percent`,tooltip:`End of the sigma range where identity guidance is active.`}},outputs:{0:{tooltip:null},1:{name:`positive`,tooltip:null},2:{name:`negative`,tooltip:null}}},fwn={display_name:`LTXVScheduler`,inputs:{steps:{name:`steps`},max_shift:{name:`max_shift`},base_shift:{name:`base_shift`},stretch:{name:`stretch`,tooltip:`Stretch the sigmas to be in the range [terminal, 1].`},terminal:{name:`terminal`,tooltip:`The terminal value of the sigmas after stretching.`},latent:{name:`latent`}},outputs:{0:{tooltip:null}}},pwn={display_name:`Separate AV Latent`,description:`Split a joint AV latent into its video and audio latents (any AV model, e.g. LTXV or MiniMax H3).`,inputs:{av_latent:{name:`av_latent`}},outputs:{0:{name:`video_latent`,tooltip:null},1:{name:`audio_latent`,tooltip:null}}},mwn={display_name:`LTXV Separate Generated Keyframes`,description:`Split the generated keyframes added by LTXV Add Generated Keyframes back out of a sampled latent, and remove them from the conditioning. Separate them before spatially upscaling the video latent. Do not run LTXV Crop Guides first — it treats generated keyframes as disposable guides and drops them.`,inputs:{positive:{name:`positive`},negative:{name:`negative`},latent:{name:`latent`},keyframes_to_batch:{name:`keyframes_to_batch`,tooltip:`Return the keyframes as a batch of single-frame latents. Leave off to get them as one multi-frame latent, which is what the latent upsampler and a later Add Generated Keyframes expect.`}},outputs:{0:{name:`positive`,tooltip:`Positive conditioning with generated-keyframe metadata removed.`},1:{name:`negative`,tooltip:`Negative conditioning with generated-keyframe metadata removed.`},2:{name:`latent`,tooltip:`Video latent with the generated keyframes stripped.`},3:{name:`keyframes`,tooltip:`The peeled keyframes, labeled with generated_keyframe_indices and generated_keyframe_num_frames. Feed these to a later Add Generated Keyframes to initialize new slots, or to Generated Keyframes To Guides to pin them as frozen image guides (indices are remapped if the canvas length changed).`}}},hwn={display_name:`LTXV Spatio-Temporal Guidance (STG)`,description:`Runs one extra pass per step with the self-attention of the selected blocks degraded to a value-passthrough, then guides away from it - improving spatial detail and motion coherence.`,inputs:{model:{name:`model`},scale:{name:`scale`},blocks:{name:`blocks`,tooltip:`Comma-separated transformer block indices to perturb.`},start_percent:{name:`start_percent`},end_percent:{name:`end_percent`}},outputs:{0:{tooltip:null}}},gwn={display_name:`Luma Concepts`,description:`Camera Concepts for use with Luma Text to Video and Luma Image to Video nodes.`,inputs:{concept1:{name:`concept1`},concept2:{name:`concept2`},concept3:{name:`concept3`},concept4:{name:`concept4`},luma_concepts:{name:`luma_concepts`,tooltip:`Optional Camera Concepts to add to the ones chosen here.`}},outputs:{0:{name:`luma_concepts`,tooltip:null}}},_wn={display_name:`Luma UNI-1 Image Edit`,description:`Edit an existing image with a text prompt using the Luma UNI-1 model.`,inputs:{source:{name:`source`,tooltip:`Source image to edit.`},prompt:{name:`prompt`,tooltip:`Description of the desired edit. 1–6000 characters.`},model:{name:`model`,tooltip:`Model to use for editing.`},seed:{name:`seed`,tooltip:`Seed controls whether the node should re-run; results are non-deterministic regardless of seed.`},control_after_generate:{name:`control after generate`},model_style:{name:`style`},model_web_search:{name:`web_search`}},outputs:{0:{tooltip:null}}},vwn={display_name:`Luma Image to Image`,description:`Modifies images synchronously based on prompt and aspect ratio.`,inputs:{image:{name:`image`},prompt:{name:`prompt`,tooltip:`Prompt for the image generation`},image_weight:{name:`image_weight`,tooltip:`Weight of the image; the closer to 1.0, the less the image will be modified.`},model:{name:`model`},seed: