on`},duration:{name:`duration`},loop:{name:`loop`},seed:{name:`seed`,tooltip:`Seed to determine if node should re-run; actual results are nondeterministic regardless of seed.`},first_image:{name:`first_image`,tooltip:`First frame of generated video.`},last_image:{name:`last_image`,tooltip:`Last frame of generated video.`},luma_concepts:{name:`luma_concepts`,tooltip:`Optional Camera Concepts to dictate camera motion via the Luma Concepts node.`},control_after_generate:{name:`control after generate`}},outputs:{0:{tooltip:null}}},Swn={display_name:`Luma Ray 3.2 Extend Video`,description:`Extend a previous Ray 3.2 generation forward (continue after it) or backward (lead-in before it). Connect the generation_id output of a prior Luma Ray 3.2 node. Extensions are always 5 seconds.`,inputs:{source_generation_id:{name:`source_generation_id`,tooltip:`generation_id of the prior Ray 3.2 video to extend. Connect the generation_id output of another Luma Ray 3.2 node.`},direction:{name:`direction`,tooltip:`Forward continues after the prior clip; backward is prepended before it.`},prompt:{name:`prompt`,tooltip:`Text prompt for the new content.`},resolution:{name:`resolution`},seed:{name:`seed`,tooltip:`Seed to determine if node should re-run; results are nondeterministic regardless of seed.`},control_after_generate:{name:`control after generate`},direction_loop:{name:`loop`}},outputs:{0:{tooltip:null},1:{name:`generation_id`,tooltip:null}}},Cwn={display_name:`Luma Ray 3.2 Image to Video`,description:`Generate a video from a start and/or end frame using Luma's Ray 3.2 model. Image-anchored generations are always 5 seconds.`,inputs:{prompt:{name:`prompt`,tooltip:`Text prompt for the video generation.`},resolution:{name:`resolution`},loop:{name:`loop`,tooltip:`Make the video loop seamlessly. Not available when an end_frame is set.`},seed:{name:`seed`,tooltip:`Seed to determine if node should re-run; results are nondeterministic regardless of seed.`},start_frame:{name:`start_frame`,to