{name:`metallic`},normal_map:{name:`normal_map`},occlusion:{name:`occlusion`},roughness:{name:`roughness`}},outputs:{0:{name:`mesh`,tooltip:null}}},Ytr={description:`Passen Sie die Lautstärke des Audiosignals um einen angegebenen Betrag in Dezibel (dB) an.`,display_name:`Audiolautstärke anpassen`,inputs:{audio:{name:`audio`},volume:{name:`volume`,tooltip:`Lautstärkeanpassung in Dezibel (dB). 0 = keine Änderung, +6 = doppelt, -6 = halb usw.`}},outputs:{0:{tooltip:null}}},Xtr={description:`Fügt audio1 in der angegebenen Richtung an audio2 an.`,display_name:`Audio zusammenführen`,inputs:{audio1:{name:`audio1`},audio2:{name:`audio2`},direction:{name:`direction`,tooltip:`Ob audio2 nach oder vor audio1 angefügt werden soll.`}},outputs:{0:{tooltip:null}}},Ztr={display_name:`AudioEncoderEncode`,inputs:{audio:{name:`audio`},audio_encoder:{name:`audio_encoder`}},outputs:{0:{tooltip:null}}},Qtr={display_name:`Audio-Encoder laden`,inputs:{audio_encoder_name:{name:`audio_encoder_name`}},outputs:{0:{tooltip:null}}},$tr={display_name:`Audio-Equalizer (3-Band)`,inputs:{audio:{name:`audio`},high_freq:{name:`high_freq`,tooltip:`Grenzfrequenz für High-Shelf`},high_gain_dB:{name:`high_gain_dB`,tooltip:`Verstärkung für hohe Frequenzen (Höhen)`},low_freq:{name:`low_freq`,tooltip:`Grenzfrequenz für Low-Shelf`},low_gain_dB:{name:`low_gain_dB`,tooltip:`Verstärkung für tiefe Frequenzen (Bass)`},mid_freq:{name:`mid_freq`,tooltip:`Mittenfrequenz`},mid_gain_dB:{name:`mid_gain_dB`,tooltip:`Verstärkung für mittlere Frequenzen`},mid_q:{name:`mid_q`,tooltip:`Q-Faktor (Bandbreite) für Mitten`}},outputs:{0:{tooltip:null}}},enr={description:`Kombiniert zwei Audiospuren durch Überlagern ihrer Wellenformen.`,display_name:`Audio zusammenführen`,inputs:{audio1:{name:`audio1`},audio2:{name:`audio2`},merge_method:{name:`merge_method`,tooltip:`Die Methode zum Kombinieren der Audio-Wellenformen.`}},outputs:{0:{tooltip:null}}},tnr={description:`Backt eine Ambient-Occlusion-Map aus einem High-Poly-Mesh in das UV-Layout eines Low-Poly-Meshes (weiß = offen, dunkel = Vertiefungen). Geben Sie das UV-entfaltete low_poly und das high_poly ein, aus dem es dezimiert wurde. Gibt ein Graustufenbild für den occlusion-Eingang von Apply Texture To Mesh aus (in die ORM-Map / occlusionTexture gepackt).`,display_name:`Ambient Occlusion backen`,inputs:{bias:{name:`bias`,tooltip:`Anhebung des Strahlenursprungs über der Oberfläche als Anteil der Bounding-Box-Diagonale. Erhöhen, wenn selbst ebene Oberflächen dunkle Flecken/Löcher zeigen.`},high_poly:{name:`high_poly`},low_poly:{name:`low_poly`},max_distance:{name:`max_distance`,tooltip:`Strahllänge als Anteil der Bounding-Box-Diagonale. Kleiner = engere, lokalere Okklusion.`},resolution:{name:`resolution`},samples:{name:`samples`,tooltip:`Strahlen pro Texel. Mehr = glatter, langsamer. Erhöhen, wenn körnig.`},strength:{name:`strength`,tooltip:`Skaliert die Okklusion. >1 verdunkelt, <1 hellt auf.`}},outputs:{0:{name:`occlusion`,tooltip:null}}},nnr={description:`Backt eine Tangentenraum-Normal-Map (glTF/OpenGL +Y) aus einem High-Poly-Mesh in das UV-Layout eines Low-Poly-Meshes und erfasst dabei Details, die bei der Dezimierung verloren gingen. Geben Sie das UV-entfaltete low_poly und das high_poly ein, aus dem es dezimiert wurde. Gibt ein Bild für den normal_map-Eingang von Apply Texture To Mesh aus.`,display_name:`Normal Map aus Mesh backen`,inputs:{cage_distance:{name:`cage_distance`,tooltip:`Oberflächen-Suchbereich als Anteil der Bounding-Box-Diagonale. Bei fehlerhaften oder fehlenden Bereichen nach starker Dezimierung erhöhen; verringern, wenn über Lücken hinweg erfasst wird.`},high_poly:{name:`high_poly`},ignore_backfaces:{name:`ignore_backfaces`,tooltip:`Überspringt High-Poly-Oberflächen, die vom Texel weg zeigen, damit Vertiefungen und abgeschlossene Bereiche nicht die gegenüberliegende Wand erfassen. Deaktivieren Sie dies nur, wenn das High-Poly-Winding inkonsistent ist.`},low_poly:{name:`low_poly`},resolution:{name:`resolution`}},outputs:{0:{name:`normal_map`,tooltip:null}}},rnr={description:`Bäckt PBR-Texturen in das vorhandene UV-Layout des Meshes ein (trilineare Stichproben aus dem sparsamen Voxel-Volumen). Führt KEIN Unwrapping durch – verbinden Sie vorgelagert einen UV-Unwrap-Node. Gibt Graustufen-IMAGEs für base_color sowie metallic/roughness aus (schwarz, wenn kein PBR vorhanden ist); leiten Sie sie für SaveGLB an ApplyTextureToMesh (DASSELBE Mesh) weiter.`,display_name:`Textur aus Voxel backen`,inputs:{mesh:{name:`mesh`},reference_mesh:{name:`reference_mesh`,tooltip:`Optionales dichtes Mesh vor der Dezimierung; projiziert jedes Texel vor dem Sampling zurück auf seine tatsächliche Oberfläche und entfernt dadurch facettiertes Baking bei groben Meshes.`},texture_size:{name:`texture_size`,tooltip:`Quadratische UV-Atlasauflösung.`},voxel_colors:{name:`voxel_colors`}},outputs:{0:{name:`base_color`,tooltip:null},1:{name:`metallic`,tooltip:null},2:{name:`roughness`,tooltip:null}}},inr={display_name:`Einfacher Guider`,inputs:{conditioning:{name:`conditioning`},model:{name:`model`}},outputs:{0:{tooltip:null}}},anr={display_name:`BasicScheduler`,inputs:{denoise:{name:`denoise`},model:{name:`model`},scheduler:{name:`scheduler`},steps:{name:`steps`}},outputs:{0:{tooltip:null}}},onr={display_name:`Bilder bündeln`,inputs:{images:{name:`images`}},outputs:{0:{tooltip:null}}},snr={display_name:`Latents bündeln`,inputs:{latents:{name:`latents`}},outputs:{0:{tooltip:null}}},cnr={display_name:`Masken bündeln`,inputs:{masks:{name:`masks`}},outputs:{0:{tooltip:null}}},lnr={description:`Bearbeiten Sie ein einzelnes Bild mit Beeble SwitchX. Ändert alles in der Szene (Hintergrund, Beleuchtung, Kostüm), während die Pixel des ursprünglichen Subjekts erhalten bleiben. Geben Sie ein Referenzbild und/oder einen Text-Prompt an, um den neuen Look zu beschreiben. Max. ~2,77 MP.`,display_name:`Beeble SwitchX-Bildbearbeitung`,inputs:{alpha_mode:{name:`alpha_mode`,tooltip:`Steuert, wie SwitchX entscheidet, was beibehalten oder neu generiert wird. 'auto' isoliert automatisch das Hauptsubjekt. 'fill' generiert den gesamten Frame neu und bewahrt dabei die Geometrie. 'select' überträgt ein Keyframe des ersten Frames auf den gesamten Clip. 'custom' verwendet eine von Ihnen bereitgestellte Alpha-Matte pro Frame.`},control_after_generate:{name:`Steuerung nach Generierung`},image:{name:`image`},max_resolution:{name:`max_resolution`,tooltip:`Maximale Ausgabeauflösung.`},prompt:{name:`prompt`,tooltip:`Textbeschreibung der gewünschten Ausgabe (max. 2000 Zeichen). Mindestens eines von 'prompt' oder 'reference_image' ist erforderlich.`},reference_image:{name:`reference_image`,tooltip:`Referenzbild, dessen Erscheinungsbild (Hintergrund, Beleuchtung, Kostüm) das Ergebnis übernehmen soll. Mindestens eines von „reference_image“ oder „prompt“ ist erforderlich.`},seed:{name:`Seed`,tooltip:`Der Seed steuert, ob der Node erneut ausgeführt werden soll; die Ergebnisse sind unabhängig vom Seed nicht deterministisch.`}},outputs:{0:{name:`Bild`,tooltip:null},1:{name:`Alpha`,tooltip:`Die von Beeble verwendete Alpha-Matte. Leer im Modus „fill“, der keine separate Matte besitzt.`}}},unr={description:`Bearbeiten Sie ein Video mit Beeble SwitchX. Tauscht alles in der Szene (Hintergrund, Beleuchtung, Kostüm) aus, während die Pixel und die Bewegung des ursprünglichen Motivs erhalten bleiben. Geben Sie ein Referenzbild und/oder einen Text-Prompt an, um den neuen Look zu beschreiben. Maximal 240 Frames, maximal ca. 2,77 MP pro Frame.`,display_name:`Beeble SwitchX Video Edit`,inputs:{alpha_mode:{name:`alpha_mode`,tooltip:`Steuert, wie SwitchX entscheidet, was beibehalten bzw. neu generiert wird. „auto“ isoliert das Hauptmotiv automatisch. „fill“ generiert den gesamten Frame unter Beibehaltung der Geometrie neu. „select“ überträgt einen Keyframe des ersten Frames auf den gesamten Clip. „custom“ verwendet eine von Ihnen bereitgestellte Alpha-Matte pro Frame.`},control_after_generate:{name:`Steuerung nach Generierung`},max_resolution:{name:`max_resolution`,tooltip:`Maximale Ausgabeauflösung.`},prompt:{name:`Prompt`,tooltip:`Textbeschreibung der gewünschten Ausgabe (max. 2000 Zeichen). Mindestens eines von „prompt“ oder „reference_image“ ist erforderlich.`},reference_image:{name:`reference_image`,tooltip:`Referenzbild, dessen Erscheinungsbild (Hintergrund, Beleuchtung, Kostüm) das Ergebnis übernehmen soll. Mindestens eines von „reference_image“ oder „prompt“ ist erforderlich.`},seed:{name:`Seed`,tooltip:`Der Seed steuert, ob der Node erneut ausgeführt werden soll; die Ergebnisse sind unabhängig vom Seed nicht deterministisch.`},video:{name:`Video`}},outputs:{0:{name:`Video`,tooltip:null},1:{name:`Alpha`,tooltip:`Die von Beeble verwendete Alpha-Matte. Leer im Modus „fill“, der keine separate Matte besitzt.`}}},dnr={description:`Conditioning-Node für das In-Context-Conditioning von Bernini für Videos/Bilder. Er kann für folgende Aufgaben verwendet werden: t2v (Text-zu-Video), v2v (Video-zu-Video), rv2v (referenzgestützte Videobearbeitung), r2v (Referenz-zu-Video), ads2v (Bild/Video in Video einfügen). Als In-Context-Tokens eingefügte Referenzbilder (r2v, rv2v) werden unabhängig in ihrem nativen Seitenverhältnis kodiert (lange Kante auf ref_max_size begrenzt).`,display_name:`Bernini Conditioning`,inputs:{batch_size:{name:`batch_size`},height:{name:`height`},length:{name:`length`},negative:{name:`negative`},positive:{name:`positive`},ref_max_size:{name:`ref_max_size`,tooltip:`Maximale Größe für die lange Kante von reference_video und reference_images. Die Größe wird unter Beibehaltung des Seitenverhältnisses angepasst und auf 16px gerundet.`},reference_images:{name:`reference_images`},reference_video:{name:`reference_video`,tooltip:`Video, das in das Quellvideo eingefügt werden soll (ads2v).`},source_video:{name:`source_video`,tooltip:`Zu bearbeitendes oder umzustilisierendes Quellvideo (v2v, rv2v). Wird auf width/height skaliert und auf length gekürzt.`},vae:{name:`vae`},width:{name:`width`}},outputs:{0:{name:`positive`,tooltip:null},1:{name:`negative`,tooltip:null},2:{name:`latent`,tooltip:null}}},fnr={display_name:`BetaSamplingScheduler`,inputs:{alpha:{name:`alpha`},beta:{name:`beta`},model:{name:`model`},steps:{name:`steps`}},outputs:{0:{tooltip:null}}},pnr={description:`Wendet Block-Sparse-Attention auf geeignete Attention-Layer des Modells an und reduziert so den Rechenaufwand bei langen Sequenzen. Der Geschwindigkeitsgewinn steigt mit der Sequenzlänge, da kurze Sequenzen mit dichter Attention in der Regel schneller sind. Außerhalb von start/end_percent, bei dense_blocks und unter min_tokens verwendet das Modell das dichte Attention-Backend des Modells. Verwenden Sie den Node Modell-Attention-Backend, um diesen Fallback auszuwählen.`,display_name:`Modell-Sparse-Attention`,inputs:{dense_blocks:{name:`dense_blocks`,tooltip:`Transformer-Blöcke, die immer dicht ausgeführt werden, z. B. '0, 1, 47-49'.`},end_percent:{name:`end_percent`,tooltip:`Prozentwert, ab dem Sparse-Attention endet. Danach wird die Attention wieder dicht.`},extra_tokens:{name:`extra_tokens`,tooltip:`Zusätzliche Tokens mit den höchsten Scores, die jeder Query-Block über seine ausgewählten Blöcke hinaus berücksichtigt. Für mehr Attention-Zeit näher an dicht; 256 empfohlen, 0 deaktiviert. Für VSA ignoriert.`},min_tokens:{name:`min_tokens`,tooltip:`Kürzere Sequenzen bleiben dicht.`},model:{name:`model`,tooltip:`Das zu patchende Modell.`},selection:{name:`selection`,tooltip:`Methode zur Auswahl von Key-Blöcken für vollständige Attention auf Token-Ebene. sol-attn: Sparsifying Online Attention verwendet für jeden Attention-Head und Query-Block einen trainingsfreien adaptiven Schwellenwert. sla: Sparse-Linear Attention behält einen festen Prozentsatz der Key-Blöcke mit der höchsten Bewertung bei; nur mit Modellgewichten verwenden, die für dieses Muster trainiert wurden. vsa: Video Sparse Attention (FastVideo) verwendet 3D-Videowürfel-Tiling und einen gelernten groben Attention-Zweig; erfordert FastH3-Modellgewichte.`},selection_tau:{name:`tau`},sink_conditioning:{name:`sink_conditioning`,tooltip:`Nur MiniMax-H3. exact_kv: Jede Query berücksichtigt die gepackten Text-/Audio-/Referenzzeilen exakt (~3 % Kosten). exact_kv_and_rows: Führt zusätzlich die Target-Audio-Query-Zeilen dicht aus (hält generiertes Audio intakt).`},start_percent:{name:`start_percent`,tooltip:`Prozentwert, ab dem Sparse-Attention beginnt. Davor bleibt die Attention dicht.`},verbose:{name:`verbose`,tooltip:`Protokolliert, ob für jede Attention-Form Sparse-Attention verwendet wurde oder warum sie dicht blieb.`}},outputs:{0:{name:`model`,tooltip:`Das Modell mit angewendeter Block-Sparse-Attention.`}}},mnr={description:`Fügen Sie mit Bria ein in Klartext beschriebenes Objekt in ein Bild ein. Bria rendert das gesamte Bild mit etwa 1 Megapixel neu, daher ist das Ergebnis nicht pixelgenau zum Eingabebild ausgerichtet.`,display_name:`Bria Objekt hinzufügen`,inputs:{control_after_generate:{name:`Steuerung nach Generierung`},image:{name:`Bild`},instruction:{name:`Anweisung`,tooltip:`Was und wo hinzugefügt werden soll, z. B. „Stellen Sie eine rote Vase mit Blumen auf den Tisch“.`},moderation:{name:`Moderation`,tooltip:`Moderationseinstellungen`},seed:{name:`Seed`,tooltip:`Bria verwendet hier keinen Seed und interpretiert die Bearbeitung bei jedem Aufruf neu, daher können wiederholte Ausführungen abweichen. Der Wert wird nie gesendet: Er ändert nur den Cache-Schlüssel dieses Nodes, sodass ein ansonsten identischer Graph die Bearbeitung erneut ausführt, statt das zwischengespeicherte Ergebnis zurückzugeben.`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`Strukturierte Beschreibung des bearbeiteten Bildes für eine anschließende Bearbeitung mit Bria FIBO Image Edit.`}}},hnr={description:`Entfernen Sie mit Bria ein in Klartext benanntes Objekt aus einem Bild. Bria rendert das gesamte Bild mit etwa 1 Megapixel neu, daher ist das Ergebnis nicht pixelgenau zum Eingabebild ausgerichtet.`,display_name:`Bria Per Text löschen`,inputs:{image:{name:`Bild`},moderation:{name:`Moderation`,tooltip:`Moderationseinstellungen`},object_name:{name:`object_name`,tooltip:`Name des zu entfernenden Objekts, z. B. „die Lampe“. Es können mehrere Objekte gleichzeitig benannt werden, z. B. „das Telefon und die Bleistifte“. Wenn etwas benannt wird, das nicht im Bild ist, wird dennoch ein neu gerendertes Bild zurückgegeben und berechnet.`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`Strukturierte Beschreibung des bearbeiteten Bildes für eine anschließende Bearbeitung mit Bria FIBO Image Edit.`}}},gnr={description:`Entfernen Sie mit Bria den Vordergrund eines Bildes und generieren Sie an seiner Stelle einen Hintergrund. Alles, was Bria als Vordergrund erkennt, wird entfernt, nicht nur Personen. Die unveränderten Pixel bleiben erhalten, aber die Ausgabe wird in einer Standardgröße von etwa 1 Megapixel neu gerendert.`,display_name:`Bria Vordergrund entfernen`,inputs:{image:{name:`Bild`},moderation:{name:`Moderation`,tooltip:`Moderationseinstellungen`}},outputs:{0:{tooltip:null}}},_nr={description:`Entfernt mit Bria Objekte oder Bereiche, die durch eine mask markiert sind, aus einem Bild.`,display_name:`Bria-Radierer`,inputs:{image:{name:`image`},mask:{name:`mask`,tooltip:`Weiße Bereiche werden gelöscht, schwarze Bereiche bleiben erhalten. Die mask wird vor dem Senden binarisiert, daher gelten teilweise bemalte Bereiche als weiß. Sie muss dasselbe Seitenverhältnis wie das Bild haben.`},mask_type:{name:`mask_type`,tooltip:`manual für handgezeichnete oder Pinsel-mask, automatic für mask, die von Segmentierungsmodellen wie SAM erzeugt wurden.`},moderation:{name:`moderation`,tooltip:`Moderationseinstellungen`}},outputs:{0:{tooltip:null}}},vnr={description:`Erweitert ein Bild mit generierten Inhalten über seine Ränder hinaus mithilfe von Bria.`,display_name:`Bria Bild erweitern`,inputs:{control_after_generate:{name:`control after generate`},expand_mode:{name:`expand_mode`,tooltip:`Zielformat des erweiterten Bildes: ein voreingestelltes Seitenverhältnis, ein benutzerdefiniertes Verhältnis oder die manuelle Platzierung des Originalbilds auf einem Canvas. Nur im manuellen Modus kann ein Canvas höher als 1:2 sein.`},image:{name:`image`},moderation:{name:`moderation`,tooltip:`Moderationseinstellungen`},negative_prompt:{name:`negative_prompt`},prompt:{name:`prompt`,tooltip:`Optionale Beschreibung der erweiterten Szene; wenn leer, generiert Bria eine aus dem Bild.`},seed:{name:`seed`}},outputs:{0:{tooltip:null},1:{name:`prompt`,tooltip:`Der für die Erweiterung verwendete Prompt; wird von Bria automatisch generiert, wenn die Prompt-Eingabe leer ist.`}}},ynr={description:`Generiert mit Bria Objekte oder Landschaften innerhalb eines maskierten Bereichs eines Bildes.`,display_name:`Bria Generatives Füllen`,inputs:{control_after_generate:{name:`Steuerung nach Generierung`},image:{name:`image`},mask:{name:`mask`,tooltip:`Weiße Bereiche werden mit generierten Inhalten gefüllt, schwarze Bereiche bleiben erhalten. Die mask wird vor dem Senden binarisiert, daher gelten teilweise bemalte Bereiche als weiß. Sie muss dasselbe Seitenverhältnis wie das Bild haben.`},moderation:{name:`Moderation`,tooltip:`Moderationseinstellungen`},negative_prompt:{name:`negative_prompt`},prompt:{name:`prompt`,tooltip:`Beschreibung dessen, was innerhalb des maskierten Bereichs generiert werden soll.`},refine_prompt:{name:`Prompt verfeinern`,tooltip:`Passt den Prompt automatisch für bessere Ergebnisse an; deaktivieren Sie dies, um den Prompt genau wie eingegeben zu verwenden.`},seed:{name:`Seed`}},outputs:{0:{tooltip:null}}},bnr={description:`Bearbeiten Sie Bilder mit dem neuesten Bria-Modell`,display_name:`Bria FIBO-Bildbearbeitung`,inputs:{control_after_generate:{name:`Steuerung nach Generierung`},guidance_scale:{name:`Guidance-Skala`,tooltip:`Ein höherer Wert sorgt dafür, dass das Bild dem Prompt genauer folgt.`},image:{name:`Bild`},mask:{name:`Maske`,tooltip:`Wenn nicht angegeben, wird die Bearbeitung auf das gesamte Bild angewendet.`},model:{name:`Modell`},moderation:{name:`Moderation`,tooltip:`Moderationseinstellungen`},negative_prompt:{name:`Negativer Prompt`},prompt:{name:`Prompt`,tooltip:`Anweisung zum Bearbeiten des Bildes`},seed:{name:`Seed`},steps:{name:`Schritte`},structured_prompt:{name:`Strukturierter Prompt`,tooltip:`Eine Zeichenfolge mit dem strukturierten Bearbeitungs-Prompt im JSON-Format. Verwenden Sie diese statt des üblichen Prompts für präzise, programmatische Steuerung.`}},outputs:{0:{tooltip:null},1:{name:`Strukturierter Prompt`,tooltip:null}}},xnr={description:`Skalieren Sie ein Bild mit Bria auf das 2- oder 4-Fache hoch, wobei der ursprüngliche Inhalt erhalten bleibt.`,display_name:`Bria Auflösung erhöhen`,inputs:{auto_downscale:{name:`Automatisch herunterskalieren`,tooltip:`Verringert den Faktor automatisch und skaliert das Eingabebild herunter, falls dies weiterhin nicht ausreicht und die Ausgabe das Limit überschreiten würde.`},desired_increase:{name:`Gewünschte Vergrößerung`,tooltip:`Auflösungsfaktor. Die Ausgabe muss auf jeder Seite innerhalb von 8192 Pixeln liegen.`},image:{name:`Bild`},moderation:{name:`Moderation`,tooltip:`Moderationseinstellungen`}},outputs:{0:{tooltip:null}}},Snr={description:`Ändern Sie mit Bria die Lichtstimmung und -richtung eines Bildes. Bria rendert das gesamte Bild mit etwa 1 Megapixel neu, daher ist das Ergebnis nicht pixelgenau zum Eingabebild ausgerichtet.`,display_name:`Bria Beleuchtung ändern`,inputs:{image:{name:`Bild`},light_direction:{name:`light_direction`,tooltip:`Woher das Licht kommt. Hartlichtstimmungen wie Mittag, Spot auf das Motiv und hartes Studiolicht reagieren am stärksten darauf.`},light_type:{name:`light_type`,tooltip:`Anzuwendende Lichtstimmung.`},moderation:{name:`Moderation`,tooltip:`Moderationseinstellungen`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`Strukturierte Beschreibung des bearbeiteten Bildes für eine anschließende Bearbeitung mit Bria FIBO Image Edit.`}}},Cnr={description:`Entfernen Sie den Hintergrund eines Bildes mit Bria RMBG 2.0.`,display_name:`Bria Bildhintergrund entfernen`,inputs:{control_after_generate:{name:`Steuerung nach Generierung`},image:{name:`Bild`},moderation:{name:`Moderation`,tooltip:`Moderationseinstellungen`},seed:{name:`Seed`,tooltip:`Der Seed steuert, ob der Node erneut ausgeführt werden soll; die Ergebnisse sind unabhängig vom Seed nicht deterministisch.`}},outputs:{0:{tooltip:null}}},wnr={description:`Entfernt mit Bria den Hintergrund aus einem Video. `,display_name:`Bria Videohintergrund entfernen`,inputs:{background_color:{name:`background_color`,tooltip:`Hintergrundfarbe für das Ausgabevideo.`},control_after_generate:{name:`Steuerung nach Generierung`},seed:{name:`Seed`,tooltip:`Der Seed steuert, ob der Node erneut ausgeführt werden soll; die Ergebnisse sind unabhängig vom Seed nicht deterministisch.`},video:{name:`Video`}},outputs:{0:{tooltip:null}}},Tnr={description:`Ersetzen Sie mit Bria den Hintergrund eines Bildes, beschrieben durch einen Prompt oder gesteuert durch Referenzbilder. Die Pixel des Motivs bleiben erhalten; der Hintergrund wird darum herum generiert.`,display_name:`Bria Bildhintergrund ersetzen`,inputs:{background:{name:`Hintergrund`,tooltip:`Beschreiben Sie den neuen Hintergrund mit einem Prompt oder steuern Sie ihn mit Referenzbildern.`},background_mode:{name:`Modus`},background_prompt:{name:`Prompt`},background_refine_prompt:{name:`refine_prompt`},control_after_generate:{name:`Steuerung nach Generierung`},image:{name:`Bild`},moderation:{name:`Moderation`,tooltip:`Moderationseinstellungen`},original_quality:{name:`original_quality`,tooltip:`Gibt die exakte Pixelgröße der Eingabe zurück, anstatt das Ergebnis auf etwa 1 Megapixel zu skalieren. Eine große Eingabe liefert dann ein großes Bild.`},seed:{name:`Seed`,tooltip:`Derselbe Seed liefert in der Regel denselben Hintergrund; die automatische Prompt-Verfeinerung kann ihn jedoch weiterhin variieren.`}},outputs:{0:{tooltip:null},1:{name:`refined_prompt`,tooltip:`Der Prompt, den Bria generiert hat; beim Pfad mit Referenzbild leer.`}}},Enr={description:`Ersetzen Sie mit Bria ein Objekt in einem Bild durch ein anderes, das in Klartext beschrieben wird. Bria rendert das gesamte Bild mit etwa 1 Megapixel neu, daher ist das Ergebnis nicht pixelgenau zur Eingabe ausgerichtet.`,display_name:`Bria Objekt ersetzen`,inputs:{control_after_generate:{name:`Steuerung nach Generierung`},image:{name:`Bild`},instruction:{name:`Anweisung`,tooltip:`Was durch was ersetzt werden soll, z. B. „Ersetzen Sie den roten Apfel durch eine grüne Birne“.`},moderation:{name:`Moderation`,tooltip:`Moderationseinstellungen`},seed:{name:`Seed`,tooltip:`Bria verwendet hier keinen Seed und interpretiert die Bearbeitung bei jedem Aufruf neu, daher können wiederholte Ausführungen unterschiedlich ausfallen. Der Wert wird nie gesendet: Er ändert nur den Cache-Schlüssel dieses Nodes, damit ein ansonsten identischer Graph die Bearbeitung erneut ausführt, statt das zwischengespeicherte Ergebnis zurückzugeben.`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`Strukturierte Beschreibung des bearbeiteten Bildes für eine nachfolgende Bearbeitung mit Bria FIBO Image Edit.`}}},Dnr={description:`Versetzen Sie mit Bria ein Bild in eine andere Jahreszeit. Die gesamte Szene wird neu gerendert, daher kann sich die Umgebung über die Jahreszeit hinaus verändern. Bria rendert das gesamte Bild mit etwa 1 Megapixel neu, daher ist das Ergebnis nicht pixelgenau zur Eingabe ausgerichtet.`,display_name:`Bria Jahreszeit ändern`,inputs:{image:{name:`Bild`},moderation:{name:`Moderation`,tooltip:`Moderationseinstellungen`},season:{name:`Jahreszeit`,tooltip:`Anzuwendende Jahreszeit.`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`Strukturierte Beschreibung des bearbeiteten Bildes für eine nachfolgende Bearbeitung mit Bria FIBO Image Edit.`}}},Onr={description:`Reparieren Sie mit Bria ein altes oder beschädigtes Foto: Körnung, Kratzer und Unschärfe werden entfernt, und altersbedingte Farbstiche werden neutralisiert. Passepartouts und Studioumrandungen können abgeschnitten werden, und Gesichter werden neu gezeichnet. Bria rendert das gesamte Bild mit etwa 1 Megapixel neu, daher ist das Ergebnis nicht pixelgenau zur Eingabe ausgerichtet. Verwenden Sie stattdessen Bria Increase Resolution zum Vergrößern.`,display_name:`Bria Foto restaurieren`,inputs:{image:{name:`Bild`},moderation:{name:`Moderation`,tooltip:`Moderationseinstellungen`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`Strukturierte Beschreibung des bearbeiteten Bildes für eine anschließende Bearbeitung mit Bria FIBO Image Edit.`}}},knr={description:`Entfernt mit Bria den Hintergrund aus einem Video und gibt die freigestellten Frames plus eine Alphamaske zurück. Verbinden Sie beide mit einem Compositing-Node oder führen Sie sie Save WEBM zu, um ein transparentes Video zu schreiben.`,display_name:`Bria Videohintergrund entfernen (transparent)`,inputs:{control_after_generate:{name:`Steuerung nach Generierung`},seed:{name:`Seed`,tooltip:`Der Seed steuert, ob der Node erneut ausgeführt werden soll; die Ergebnisse sind unabhängig vom Seed nicht deterministisch.`},video:{name:`Video`}},outputs:{0:{name:`Bilder`,tooltip:null},1:{name:`Maske`,tooltip:null}}},Anr={description:`Löschen Sie mit Bria aus einem Video alles, was von einer Maske pro Frame abgedeckt wird, und füllen Sie die Lücke. Die Maske muss dort weiß sein, wo etwas entfernt werden soll, und andernorts schwarz. Bria akzeptiert Clips von maximal 5,1 Sekunden bei 20 bis 30 Frames pro Sekunde mit geraden Pixelabmessungen; Audio wird standardmäßig beibehalten. Der zurückgegebene Clip kann einige Frames kürzer als die Eingabe sein.`,display_name:`Bria Video Eraser`,inputs:{mask:{name:`mask`,tooltip:`Eine Maske pro Frame des Videos, weiß an den Stellen, an denen sich das zu löschende Objekt befindet. Geben Sie entweder eine Maske oder ein Maskenvideo an, nicht beides.`},mask_video:{name:`mask_video`,tooltip:`Ein bereits kodiertes Maskenvideo mit denselben Abmessungen und derselben Frame-Anzahl wie das Video. Geben Sie entweder eine Maske oder ein Maskenvideo an, nicht beides.`},preserve_audio:{name:`preserve_audio`,tooltip:`Audiospur der Eingabe beibehalten.`},video:{name:`video`,tooltip:`Clip, aus dem gelöscht werden soll.`}},outputs:{0:{tooltip:null}}},jnr={description:`Ersetzt mit Bria den Hintergrund eines Videos durch einen einfarbigen Chroma-Key-Hintergrund.`,display_name:`Bria Video Greenscreen`,inputs:{control_after_generate:{name:`Steuerung nach Generierung`},green_shade:{name:`green_shade`,tooltip:`Einfarbiger Chroma-Key-Farbton, der hinter dem Vordergrund angewendet wird: broadcast_green (#00B140), chroma_green (#00FF00) oder blue_screen (#0000FF).`},seed:{name:`Seed`,tooltip:`Der Seed steuert, ob der Node erneut ausgeführt werden soll; die Ergebnisse sind unabhängig vom Seed nicht deterministisch.`},video:{name:`Video`}},outputs:{0:{tooltip:null}}},Mnr={description:`Ersetzt mit Bria den Hintergrund eines Videos durch ein bereitgestelltes Bild oder Video. Die Ausgabe behält Auflösung und Bildrate des Vordergrunds bei; ein Hintergrund mit einem anderen Seitenverhältnis wird passend gestreckt. Verwenden Sie daher ein passendes Seitenverhältnis, um unverzerrte Ergebnisse zu erhalten.`,display_name:`Bria Videohintergrund ersetzen`,inputs:{background_image:{name:`background_image`,tooltip:`Hintergrundbild, das hinter dem Vordergrund zusammengesetzt wird. Geben Sie entweder ein Hintergrundbild oder ein Hintergrundvideo an, nicht beides.`},background_video:{name:`background_video`,tooltip:`Hintergrundvideo, das hinter dem Vordergrund zusammengesetzt wird. Geben Sie entweder ein Hintergrundbild oder ein Hintergrundvideo an, nicht beides.`},control_after_generate:{name:`Steuerung nach Generierung`},seed:{name:`Seed`,tooltip:`Der Seed steuert, ob der Node erneut ausgeführt werden soll; die Ergebnisse sind unabhängig vom Seed nicht deterministisch.`},video:{name:`Video`,tooltip:`Vordergrundvideo, dessen Hintergrund ersetzt wird.`}},outputs:{0:{tooltip:null}}},Nnr={description:`Erstellt einen JSON-Prompt für das Ideogram-4-Modell.`,display_name:`JSON-Prompt erstellen (Ideogram)`,inputs:{aesthetics:{name:`aesthetics`,tooltip:`Erforderliche ästhetische Schlüsselwörter (z. B. stimmungsvoll, filmisch, entsättigt).`},background:{name:`background`,tooltip:`Erforderliche Beschreibung des Bildhintergrunds oder der Umgebung.`},color_palette:{name:`color_palette`,tooltip:`Hex-Farbcodes, die die dominanten Farben des Bildes steuern. Bis zu 16 Einträge.`},element:{name:`Element`,tooltip:`Prompt-Elemente aus dem Node Create Bounding Boxes.`},high_level_description:{name:`high_level_description`,tooltip:`Optionale Beschreibung des Bildes in ein oder zwei Sätzen. Dringend empfohlen.`},lighting:{name:`lighting`,tooltip:`Erforderliche Beleuchtungsbeschreibung (z. B. goldene Stunde, Kantenlicht, dramatische Schatten).`},medium:{name:`medium`,tooltip:`Erforderlicher Medientyp (z. B. photograph, illustration, 3d_render, painting, graphic_design). Wenn style = photo, auf photograph setzen.`},style:{name:`style`}},outputs:{0:{name:`prompt`,tooltip:null}}},Pnr={description:`Erstellt ein animiertes GLB aus Pose-Daten oder speichert eine BVH-Mocap-Datei.`,display_name:`3D-Animationsdatei erstellen`,inputs:{camera_translation:{name:`camera_translation`,tooltip:`pred_cam_t in die Translation der Wurzel einbacken: 'off' = Bind-Position, 'centered' = Delta ab Frame 0, 'absolute' = Rohwert (Z ist die Kameratiefe — normalerweise Meter entfernt).`},format:{name:`format`,tooltip:`Ausgabeformat; beide werden an Save 3D Model übergeben, um sie auf die Festplatte zu schreiben. 'glb' = animiertes GLB (Mesh / Bones / openpose / scail). 'bvh' = BVH-Mocap-Clip (ein Skelett; benötigt das Modell).`},format_bone_smooth_window:{name:`bone_smooth_window`},format_mesh_style:{name:`mesh_style`},format_mesh_style_bone_vis:{name:`bone_vis`},format_mesh_style_shader:{name:`shader`},fps:{name:`fps`,tooltip:`Bildrate der Animation.`},pose_data:{name:`pose_data`,tooltip:`3D-Pose-Daten.`},sam3d_body_model:{name:`sam3d_body_model`},track_index:{name:`track_index`,tooltip:`-1 = alle Tracks; ≥0 = einzelner Track.`}},outputs:{0:{name:`model_3d`,tooltip:null}}},Fnr={description:`Rendert das finale 1080p-Video eines Seedance-2.5-Drafts. Das finale Video behält Szene und Bewegung des Entwurfs bei und verwendet dessen Prompt, Referenzen, Dauer, Seitenverhältnis und Audioeinstellung erneut.`,display_name:`ByteDance Seedance 2.5 Draft in finales Video`,inputs:{draft_task_id:{name:`draft_task_id`,tooltip:`Der Output draft_task_id eines Seedance-2.5-Node, der mit dem Modell Seedance 2.5 Draft ausgeführt wurde, oder eine eingefügte Entwurfs-Task-ID. Setzen Sie die Seed-Steuerung dieses Node auf „fest“, da der nächste Durchlauf sonst einen neuen Entwurf erzeugt, anstatt den von Ihnen überprüften wiederzuverwenden. Ein Entwurf kann 7 Tage nach seiner Erstellung gerendert werden.`},watermark:{name:`Wasserzeichen`,tooltip:`Legt fest, ob dem Video ein Wasserzeichen hinzugefügt wird.`}},outputs:{0:{tooltip:null}}},Inr={description:`Generiert mit Seedance 2.5 oder 2.0 ein Video aus einem Bild des ersten Frames und einem optionalen Bild des letzten Frames.`,display_name:`ByteDance Seedance 2.5: Video aus erstem und letztem Frame`,inputs:{control_after_generate:{name:`Steuerung nach dem Generieren`},first_frame:{name:`first_frame`,tooltip:`Bild des ersten Frames für das Video.`},first_frame_asset_id:{name:`first_frame_asset_id`,tooltip:`Seedance asset_id, die als erster Frame verwendet werden soll. Schliesst die first_frame-Bildeingabe gegenseitig aus.`},last_frame:{name:`last_frame`,tooltip:`Bild des letzten Frames für das Video.`},last_frame_asset_id:{name:`last_frame_asset_id`,tooltip:`Seedance asset_id, die als letzter Frame verwendet werden soll. Schliesst die last_frame-Bildeingabe gegenseitig aus.`},model:{name:`model`,tooltip:`Seedance 2.5 für das neueste Modell, Videos bis zu 30 Sekunden und mp4/mov-Output; Seedance 2.5 Draft für eine schnelle 480p-Vorschau, deren draft_task_id das finale 1080p-Video im Node Seedance 2.5 Draft in finales Video rendert; Seedance 2.0 für maximale Qualität und 4k; Fast zur Geschwindigkeitsoptimierung; Mini für die schnellste und kostengünstigste Generierung.`},model_duration:{name:`Dauer`},model_generate_audio:{name:`generate_audio`},model_output_format:{name:`output_format`},model_prompt:{name:`Prompt`},model_resolution:{name:`Auflösung`},seed:{name:`seed`,tooltip:`Der Seed steuert, ob der Node erneut ausgeführt werden soll; Ergebnisse sind unabhängig vom Seed nicht deterministisch.`},watermark:{name:`watermark`,tooltip:`Ob dem Video ein Wasserzeichen hinzugefügt werden soll.`}},outputs:{0:{tooltip:null},1:{name:`draft_task_id`,tooltip:`Task-ID eines Seedance-2.5-Draft-Durchlaufs. Verbinden Sie sie mit dem Node Seedance 2.5 Draft in finales Video, um das finale 1080p-Video zu rendern.`}}},Lnr={description:`Generieren, bearbeiten oder erweitern Sie Videos mit Seedance 2.5 oder 2.0 anhand von Referenzbildern, Videos und Audio. Unterstützt multimodale Referenzen, Videobearbeitung und Videoerweiterung.`,display_name:`ByteDance Seedance 2.5 Referenz zu Video (Legacy)`,inputs:{control_after_generate:{name:`Steuerung nach dem Generieren`},model:{name:`Modell`,tooltip:`Seedance 2.5 für das neueste Modell, Videos bis zu 30 Sekunden und mp4/mov-Output; Seedance 2.5 Draft für eine schnelle 480p-Vorschau, deren draft_task_id das finale 1080p-Video im Node Seedance 2.5 Draft in finales Video rendert; Seedance 2.0 für maximale Qualität und 4k; Fast zur Geschwindigkeitsoptimierung; Mini für die schnellste und kostengünstigste Generierung.`},model_auto_downscale:{name:`auto_downscale`},model_auto_upscale:{name:`auto_upscale`},model_duration:{name:`Dauer`},model_generate_audio:{name:`generate_audio