:{tooltip:null}}},rsr={description:`Geordnete Referenzbilder an die positive und negative Konditionierung anhängen.`,display_name:`HiDream-O1 Referenzbilder`,inputs:{images:{name:`images`,tooltip:`Referenzbilder werden in numerischer Socket-Reihenfolge verwendet.`},negative:{name:`negative`},positive:{name:`positive`}},outputs:{0:{name:`positive`,tooltip:null},1:{name:`negative`,tooltip:null}}},isr={description:`Skalieren Sie niedrig aufgelöste Bilder auf Superauflösung hoch und entfernen Sie Artefakte und Rauschen. Maximale Ausgabe: 32 Megapixel.`,display_name:`HitPaw Allgemeine Bildverbesserung`,inputs:{auto_downscale:{name:`auto_downscale`,tooltip:`Skaliert das Eingabebild automatisch herunter, wenn die Ausgabe das Limit überschreiten würde.`},image:{name:`image`},model:{name:`model`},upscale_factor:{name:`upscale_factor`}},outputs:{0:{tooltip:null}}},asr={description:`Skalieren Sie niedrig aufgelöste Videos auf hohe Auflösung hoch und entfernen Sie Artefakte und Rauschen. Die angezeigten Preise gelten pro Videosekunde.`,display_name:`HitPaw Videobearbeitung`,inputs:{model:{name:`model`},model_resolution:{name:`resolution`},video:{name:`video`}},outputs:{0:{tooltip:null}}},osr={display_name:`Hunyuan3Dv2Conditioning`,inputs:{clip_vision_output:{name:`clip_vision_output`}},outputs:{0:{name:`positive`,tooltip:null},1:{name:`negative`,tooltip:null}}},ssr={display_name:`Hunyuan3Dv2ConditioningMultiView`,inputs:{back:{name:`back`},front:{name:`front`},left:{name:`left`},right:{name:`right`}},outputs:{0:{name:`positive`,tooltip:null},1:{name:`negative`,tooltip:null}}},csr={description:`Bearbeitet oder kombiniert bis zu 5 Referenzbilder anhand eines Text-Prompts mit dem Hunyuan Image-Modell von Tencent.`,display_name:`Tencent HY Image: Bearbeiten`,inputs:{control_after_generate:{name:`Steuerung nach Generierung`},model:{name:`Modell`,tooltip:`Zu verwendendes Modell.`},model_aspect_ratio:{name:`aspect_ratio`},model_height:{name:`Höhe`},model_prompt:{name:`Prompt`},model_r