`Opacidad inicial de la capa.`},rotation:{name:`rotación`,tooltip:`Rotación inicial en grados, en sentido horario.`},width:{name:`ancho`,tooltip:`Ancho de visualización inicial. 0 mantiene el ancho nativo de la imagen.`},x:{name:`x`,tooltip:`Ubicación horizontal inicial en el lienzo.`},y:{name:`y`,tooltip:`Ubicación vertical inicial en el lienzo.`},z_index:{name:`índice z`,tooltip:`Anulación de apilamiento. Las capas se ordenan de forma estable por índice z; los valores iguales mantienen su orden en la lista.`}},outputs:{0:{tooltip:`La pila de capas con esta capa añadida.`}}},qEr={display_name:`Agregar ruido`,inputs:{latent_image:{name:`imagen_latente`},model:{name:`modelo`},noise:{name:`ruido`},sigmas:{name:`sigmas`}},outputs:{0:{tooltip:null}}},JEr={description:`Añade un prefijo a todos los textos.`,display_name:`Agregar prefijo de texto`,inputs:{prefix:{name:`prefijo`,tooltip:`Prefijo para agregar.`},texts:{name:`textos`,tooltip:`Texto a procesar.`}},outputs:{0:{name:`textos`,tooltip:`Textos procesados`}}},YEr={description:`Añade un sufijo a todos los textos.`,display_name:`Agregar sufijo de texto`,inputs:{suffix:{name:`sufijo`,tooltip:`Sufijo para agregar.`},texts:{name:`textos`,tooltip:`Texto a procesar.`}},outputs:{0:{name:`textos`,tooltip:`Textos procesados`}}},XEr={description:`Ajusta el brillo de una imagen.`,display_name:`Ajustar brillo`,inputs:{factor:{name:`factor`,tooltip:`Factor de brillo. 1.0 = sin cambio, <1.0 = más oscuro, >1.0 = más brillante.`},images:{name:`imágenes`,tooltip:`Imagen a procesar.`}},outputs:{0:{name:`imágenes`,tooltip:`Imágenes procesadas`}}},ZEr={description:`Ajusta el contraste de una imagen.`,display_name:`Ajustar contraste`,inputs:{factor:{name:`factor`,tooltip:`Factor de contraste. 1.0 = sin cambio, <1.0 = menos contraste, >1.0 = más contraste.`},images:{name:`imágenes`,tooltip:`Imagen a procesar.`}},outputs:{0:{name:`imágenes`,tooltip:`Imágenes procesadas`}}},QEr={display_name:`Programador alinea tus pasos`,inputs:{denoise:{name:`desruido`},model_type:{name:`tipo_de_modelo`},steps:{name:`pasos`}},outputs:{0:{tooltip:null}}},$Er={display_name:`Aplicar Anima LLLite`,inputs:{end_percent:{name:`porcentaje final`},image:{name:`imagen`},mask:{name:`máscara`},model:{name:`modelo`},model_patch:{name:`parche de modelo`},start_percent:{name:`porcentaje de inicio`},strength:{name:`intensidad`}}},eDr={description:`Adjunta IMAGEs de textura horneada al diseño UV de una malla para SaveGLB. Conecte la MISMA malla que horneó`,display_name:`Aplicar textura a malla`,inputs:{base_color:{name:`base_color`},mesh:{name:`mesh`},metallic:{name:`metallic`},normal_map:{name:`normal_map`},occlusion:{name:`occlusion`},roughness:{name:`roughness`}},outputs:{0:{name:`mesh`,tooltip:null}}},tDr={description:`Ajusta el volumen del audio en una cantidad especificada en decibelios (dB).`,display_name:`Ajustar volumen de audio`,inputs:{audio:{name:`audio`},volume:{name:`volumen`,tooltip:`Ajuste de volumen en decibelios (dB). 0 = sin cambios, +6 = doble, -6 = mitad, etc.`}},outputs:{0:{tooltip:null}}},nDr={description:`Concatena el audio1 al audio2 en la dirección especificada.`,display_name:`Concatenar audio`,inputs:{audio1:{name:`audio1`},audio2:{name:`audio2`},direction:{name:`dirección`,tooltip:`Si agregar audio2 después o antes de audio1.`}},outputs:{0:{tooltip:null}}},rDr={display_name:`Codificar con codificador de audio`,inputs:{audio:{name:`audio`},audio_encoder:{name:`codificador_de_audio`}},outputs:{0:{tooltip:null}}},iDr={display_name:`Cargar codificador de audio`,inputs:{audio_encoder_name:{name:`nombre_del_codificador_de_audio`}},outputs:{0:{tooltip:null}}},aDr={display_name:`Ecualizador de audio (3 bandas)`,inputs:{audio:{name:`audio`},high_freq:{name:`frecuencia_alta`,tooltip:`Frecuencia de corte para el estante alto`},high_gain_dB:{name:`ganancia_alta_dB`,tooltip:`Ganancia para frecuencias altas (Agudos)`},low_freq:{name:`frecuencia_baja`,tooltip:`Frecuencia de corte para el estante bajo`},low_gain_dB:{name:`ganancia_baja_dB`,tooltip:`Ganancia para frecuencias bajas (Bajo)`},mid_freq:{name:`frecuencia_media`,tooltip:`Frecuencia central para medios`},mid_gain_dB:{name:`ganancia_media_dB`,tooltip:`Ganancia para frecuencias medias`},mid_q:{name:`mid_q`,tooltip:`Factor Q (ancho de banda) para medios`}},outputs:{0:{tooltip:null}}},oDr={description:`Combina dos pistas de audio superponiendo sus formas de onda.`,display_name:`Combinar audio`,inputs:{audio1:{name:`audio1`},audio2:{name:`audio2`},merge_method:{name:`método_de_fusión`,tooltip:`El método utilizado para combinar las formas de onda de audio.`}},outputs:{0:{tooltip:null}}},sDr={description:`Hornea un mapa de oclusión ambiental desde una malla de alta densidad poligonal al diseño UV de una malla de baja densidad poligonal (blanco = abierto, oscuro = grietas). Conecte low_poly con UV desplegadas y la high_poly de la que se decimó. Genera una imagen en escala de grises para la entrada occlusion de Aplicar textura a malla (empaquetada en el mapa ORM / occlusionTexture).`,display_name:`Hornear oclusión ambiental`,inputs:{bias:{name:`bias`,tooltip:`Elevación del origen del rayo sobre la superficie, como fracción de la diagonal del cuadro delimitador. Aumente si incluso las superficies uniformes muestran manchas/agujeros oscuros.`},high_poly:{name:`high_poly`},low_poly:{name:`low_poly`},max_distance:{name:`max_distance`,tooltip:`Longitud del rayo, como fracción de la diagonal del cuadro delimitador. Menor = oclusión más ajustada y local.`},resolution:{name:`resolution`},samples:{name:`samples`,tooltip:`Rayos por texel. Más = más suave, más lento. Aumente si hay granulado.`},strength:{name:`strength`,tooltip:`Escala la oclusión. >1 oscurece, <1 aclara.`}},outputs:{0:{name:`occlusion`,tooltip:null}}},cDr={description:`Hornea un mapa normal en espacio tangente (glTF/OpenGL +Y) desde una malla de alta densidad poligonal al diseño UV de una malla de baja densidad poligonal, capturando el detalle perdido durante la decimación. Conecte low_poly con UV desplegadas y la high_poly de la que se decimó. Genera una imagen para la entrada normal_map de Aplicar textura a malla.`,display_name:`Hornear mapa normal desde malla`,inputs:{cage_distance:{name:`cage_distance`,tooltip:`Banda de búsqueda de superficie, como fracción de la diagonal del cuadro delimitador. Aumente para zonas erróneas o faltantes con decimación intensa; reduzca si captura a través de huecos.`},high_poly:{name:`high_poly`},ignore_backfaces:{name:`ignore_backfaces`,tooltip:`Omite las superficies de alta densidad orientadas en sentido opuesto al texel, para que las grietas o espacios cerrados no capturen la pared opuesta. Desactívelo solo si la orientación de las caras de high_poly es inconsistente.`},low_poly:{name:`low_poly`},resolution:{name:`resolution`}},outputs:{0:{name:`normal_map`,tooltip:null}}},lDr={description:`Hornea texturas PBR en el diseño UV existente de la malla (muestreo trilineal del volumen de vóxeles disperso). NO realiza el desplegado UV: conecte antes un nodo de desplegado UV. Genera IMAGEs de base_color y IMAGEs en escala de grises de metallic/roughness (negras si no hay PBR); conéctelas a Aplicar textura a malla (la MISMA malla) para SaveGLB.`,display_name:`Hornear textura desde vóxel`,inputs:{mesh:{name:`mesh`},reference_mesh:{name:`reference_mesh`,tooltip:`Malla densa opcional previa a la decimación; reproyecta cada texel sobre su superficie real antes del muestreo, eliminando el horneado facetado en mallas gruesas.`},texture_size:{name:`texture_size`,tooltip:`Resolución cuadrada del atlas UV.`},voxel_colors:{name:`voxel_colors`}},outputs:{0:{name:`base_color`,tooltip:null},1:{name:`metallic`,tooltip:null},2:{name:`roughness`,tooltip:null}}},uDr={display_name:`Guía básica`,inputs:{conditioning:{name:`acondicionamiento`},model:{name:`modelo`}},outputs:{0:{tooltip:null}}},dDr={display_name:`Programador básico`,inputs:{denoise:{name:`desruido`},model:{name:`modelo`},scheduler:{name:`programador`},steps:{name:`pasos`}},outputs:{0:{tooltip:null}}},fDr={display_name:`Procesar imágenes por lotes`,inputs:{images:{name:`imágenes`}},outputs:{0:{tooltip:null}}},pDr={display_name:`Procesar latentes por lotes`,inputs:{latents:{name:`latentes`}},outputs:{0:{tooltip:null}}},mDr={display_name:`Procesar máscaras por lotes`,inputs:{masks:{name:`máscaras`}},outputs:{0:{tooltip:null}}},hDr={description:`Edita una sola imagen con Beeble SwitchX. Cambia cualquier elemento de la escena (fondo, iluminación, vestuario) mientras conserva los píxeles originales del sujeto. Proporciona una imagen de referencia y/o un prompt de texto para describir el nuevo aspecto. Máx. ~2,77MP.`,display_name:`Beeble SwitchX Edición de Imagen`,inputs:{alpha_mode:{name:`modo_alpha`,tooltip:`Controla cómo SwitchX decide qué conservar y qué regenerar. 'auto' aísla automáticamente el sujeto principal. 'fill' regenera todo el fotograma conservando la geometría. 'select' propaga un keyframe del primer fotograma a lo largo del clip. 'custom' utiliza un alfa matte por fotograma que proporciones.`},control_after_generate:{name:`control después de generar`},image:{name:`imagen`},max_resolution:{name:`resolución_máxima`,tooltip:`Resolución máxima de salida.`},prompt:{name:`prompt`,tooltip:`Descripción en texto del resultado deseado (máx. 2000 caracteres). Se requiere al menos uno de 'prompt' o 'reference_image'.`},reference_image:{name:`imagen_de_referencia`,tooltip:`Imagen de referencia cuyo aspecto (fondo, iluminación, vestuario) debe adoptar el resultado. Se requiere al menos uno de 'reference_image' o 'prompt'.`},seed:{name:`semilla`,tooltip:`La semilla controla si el nodo debe ejecutarse de nuevo; los resultados son no deterministas independientemente de la semilla.`}},outputs:{0:{name:`imagen`,tooltip:null},1:{name:`alfa`,tooltip:`El alfa matte utilizado por Beeble. Vacío en modo 'fill', que no tiene matte separado.`}}},gDr={description:`Edita un video con Beeble SwitchX. Cambia cualquier elemento de la escena (fondo, iluminación, vestuario) mientras conserva los píxeles y el movimiento originales del sujeto. Proporciona una imagen de referencia y/o un prompt de texto para describir el nuevo aspecto. Máx. 240 fotogramas, máx. ~2,77MP por fotograma.`,display_name:`Beeble SwitchX Edición de Video`,inputs:{alpha_mode:{name:`modo_alpha`,tooltip:`Controla cómo SwitchX decide qué conservar y qué regenerar. 'auto' aísla automáticamente el sujeto principal. 'fill' regenera todo el fotograma conservando la geometría. 'select' propaga un keyframe del primer fotograma a lo largo del clip. 'custom' utiliza un alfa matte por fotograma que proporciones.`},control_after_generate:{name:`control después de generar`},max_resolution:{name:`resolución_máxima`,tooltip:`Resolución máxima de salida.`},prompt:{name:`prompt`,tooltip:`Descripción en texto del resultado deseado (máx. 2000 caracteres). Se requiere al menos uno de 'prompt' o 'reference_image'.`},reference_image:{name:`imagen_de_referencia`,tooltip:`Imagen de referencia cuyo aspecto (fondo, iluminación, vestuario) debe adoptar el resultado. Se requiere al menos uno de 'reference_image' o 'prompt'.`},seed:{name:`semilla`,tooltip:`La semilla controla si el nodo debe ejecutarse de nuevo; los resultados son no deterministas independientemente de la semilla.`},video:{name:`video`}},outputs:{0:{name:`video`,tooltip:null},1:{name:`alfa`,tooltip:`El alfa matte utilizado por Beeble. Vacío en modo 'fill', que no tiene matte separado.`}}},_Dr={description:`Nodo de conditioning para Bernini en el contexto de conditioning de video/imagen. Puede usarse para las siguientes tareas: t2v (texto a video), v2v (video a video), rv2v (edición de video guiada por referencia), r2v (referencia a video), ads2v (insertar imagen/video en video). Las imágenes de referencia inyectadas como tokens en contexto (r2v, rv2v) se codifican de forma independiente en su propia relación de aspecto nativa (el lado largo limitado por ref_max_size).`,display_name:`Bernini Conditioning`,inputs:{batch_size:{name:`tamaño_lote`},height:{name:`alto`},length:{name:`longitud`},negative:{name:`negativo`},positive:{name:`positivo`},ref_max_size:{name:`ref_max_size`,tooltip:`Tamaño máximo para el lado largo de reference_video y reference_images. Redimensionado manteniendo la relación de aspecto y ajustado a múltiplos de 16px.`},reference_images:{name:`imágenes_referencia`},reference_video:{name:`video_referencia`,tooltip:`Video para insertar en el video fuente (ads2v).`},source_video:{name:`video_fuente`,tooltip:`Video fuente para editar o cambiar de estilo (v2v, rv2v). Redimensionado a ancho/alto y recortado a la longitud.`},vae:{name:`vae`},width:{name:`ancho`}},outputs:{0:{name:`positivo`,tooltip:null},1:{name:`negativo`,tooltip:null},2:{name:`latente`,tooltip:null}}},vDr={display_name:`Programador de muestreo beta`,inputs:{alpha:{name:`alfa`},beta:{name:`beta`},model:{name:`modelo`},steps:{name:`pasos`}},outputs:{0:{tooltip:null}}},yDr={description:`Aplica atención dispersa por bloques a las capas de atención del modelo aptas, reduciendo el cómputo para secuencias largas. La mejora de velocidad aumenta con la longitud de la secuencia, ya que las secuencias cortas suelen ser más rápidas con atención densa. Fuera de start/end_percent, con dense_blocks y por debajo de min_tokens, el modelo usa el backend de atención densa del modelo. Use el nodo Backend de atención del modelo para seleccionar esa alternativa.`,display_name:`Atención dispersa por bloques del modelo`,inputs:{dense_blocks:{name:`dense_blocks`,tooltip:`Bloques del transformador que siempre se ejecutan de forma densa, p. ej., '0, 1, 47-49'.`},end_percent:{name:`end_percent`,tooltip:`Punto porcentual en el que termina la atención dispersa. Después de este punto, la atención vuelve a ser densa.`},extra_tokens:{name:`extra_tokens`,tooltip:`Tokens adicionales con mayor puntuación a los que atiende cada bloque de consulta además de sus bloques seleccionados. Más cercano a denso para dedicar más tiempo a la atención; se recomiendan 256, 0 lo desactiva. Se ignora para VSA.`},min_tokens:{name:`min_tokens`,tooltip:`Las secuencias más cortas que esto permanecen densas.`},model:{name:`model`,tooltip:`El modelo que se va a modificar.`},selection:{name:`selection`,tooltip:`Método utilizado para elegir bloques de claves para la atención completa a nivel de token. sol-attn: Sparsifying Online Attention usa un umbral adaptativo sin entrenamiento para cada cabeza de atención y bloque de consulta. sla: Sparse-Linear Attention mantiene un porcentaje fijo de los bloques de claves con mayor puntuación; úselo solo con pesos de modelo entrenados para este patrón. vsa: Video Sparse Attention (FastVideo) usa mosaicos 3D de cubos de vídeo y una rama de atención gruesa aprendida; requiere pesos de modelo FastH3.`},selection_tau:{name:`tau`},sink_conditioning:{name:`sink_conditioning`,tooltip:`Solo MiniMax-H3. exact_kv: cada consulta atiende exactamente a las filas compactadas de texto/audio/referencia (~3 % de coste). exact_kv_and_rows: además ejecuta de forma densa las filas de consulta del audio objetivo (mantiene intacto el audio generado).`},start_percent:{name:`start_percent`,tooltip:`Punto porcentual en el que comienza la atención dispersa. Antes de este punto, la atención permanece densa.`},verbose:{name:`verbose`,tooltip:`Registra si cada forma de atención utilizó atención dispersa o por qué permaneció densa.`}},outputs:{0:{name:`model`,tooltip:`El modelo con atención dispersa por bloques aplicada.`}}},bDr={description:`Inserta en una imagen un objeto descrito en texto simple con Bria. Bria vuelve a renderizar todo el fotograma a aproximadamente 1 megapíxel, por lo que el resultado no queda alineado a píxeles con la entrada.`,display_name:`Bria Añadir objeto`,inputs:{control_after_generate:{name:`control después de generar`},image:{name:`imagen`},instruction:{name:`instrucción`,tooltip:`Qué añadir y dónde, por ejemplo, «Coloca un jarrón rojo con flores sobre la mesa».`},moderation:{name:`moderación`,tooltip:`Ajustes de moderación`},seed:{name:`semilla`,tooltip:`Bria no acepta ninguna semilla aquí y reimagina la edición en cada llamada, por lo que las ejecuciones repetidas pueden diferir. El valor nunca se envía: solo cambia la clave de caché de este nodo para que un grafo idéntico ejecute la edición de nuevo en lugar de devolver el resultado almacenado en caché.`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`Descripción estructurada de la imagen editada para una edición posterior con Bria FIBO Image Edit.`}}},xDr={description:`Elimina de una imagen con Bria un objeto nombrado en texto simple. Bria vuelve a renderizar todo el fotograma a aproximadamente 1 megapíxel, por lo que el resultado no queda alineado a píxeles con la entrada.`,display_name:`Bria Borrar por texto`,inputs:{image:{name:`imagen`},moderation:{name:`moderación`,tooltip:`Ajustes de moderación`},object_name:{name:`object_name`,tooltip:`Nombre del objeto que se va a eliminar, por ejemplo, «la lámpara». Se pueden nombrar varios objetos a la vez, por ejemplo, «el teléfono y los lápices». Nombrar algo que no está en la imagen aun así devuelve y factura una imagen renderizada de nuevo.`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`Descripción estructurada de la imagen editada para una edición posterior con Bria FIBO Image Edit.`}}},SDr={description:`Elimina el primer plano de una imagen con Bria y genera un fondo en su lugar. Se elimina todo lo que Bria interpreta como primer plano, no solo las personas. Los píxeles intactos se conservan, pero la salida se vuelve a renderizar a un tamaño estándar cercano a 1 megapíxel.`,display_name:`Bria Borrar primer plano`,inputs:{image:{name:`imagen`},moderation:{name:`moderación`,tooltip:`Ajustes de moderación`}},outputs:{0:{tooltip:null}}},CDr={description:`Elimina de una imagen objetos o áreas delimitadas por una máscara mediante Bria.`,display_name:`Borrador Bria`,inputs:{image:{name:`image`},mask:{name:`mask`,tooltip:`Las áreas blancas se eliminan y las negras se conservan. La máscara se binariza antes de enviarla, por lo que las áreas parcialmente pintadas se consideran blancas. Debe tener la misma relación de aspecto que la imagen.`},mask_type:{name:`mask_type`,tooltip:`manual para máscaras dibujadas a mano o con pincel; automático para máscaras generadas por modelos de segmentación como SAM.`},moderation:{name:`moderation`,tooltip:`Ajustes de moderación`}},outputs:{0:{tooltip:null}}},wDr={description:`Amplía una imagen más allá de sus bordes con contenido generado mediante Bria.`,display_name:`Ampliar imagen con Bria`,inputs:{control_after_generate:{name:`control después de generar`},expand_mode:{name:`expand_mode`,tooltip:`Forma objetivo de la imagen ampliada: una relación de aspecto predefinida, una relación personalizada o la colocación manual de la imagen original en un lienzo. Manual es el único modo que puede alcanzar un lienzo más alto que 1:2.`},image:{name:`image`},moderation:{name:`moderation`,tooltip:`Ajustes de moderación`},negative_prompt:{name:`negative_prompt`},prompt:{name:`prompt`,tooltip:`Descripción opcional de la escena ampliada; si está vacía, Bria genera una a partir de la imagen.`},seed:{name:`seed`}},outputs:{0:{tooltip:null},1:{name:`prompt`,tooltip:`El prompt utilizado para la ampliación; Bria lo genera automáticamente cuando la entrada de prompt está vacía.`}}},TDr={description:`Genera objetos o paisajes dentro de una región enmascarada de una imagen mediante Bria.`,display_name:`Relleno generativo de Bria`,inputs:{control_after_generate:{name:`control después de generar`},image:{name:`image`},mask:{name:`mask`,tooltip:`Las áreas blancas se rellenan con contenido generado y las negras se conservan. La máscara se binariza antes de enviarla, por lo que las áreas parcialmente pintadas se consideran blancas. Debe tener la misma relación de aspecto que la imagen.`},moderation:{name:`moderación`,tooltip:`Configuración de moderación`},negative_prompt:{name:`negative_prompt`},prompt:{name:`prompt`,tooltip:`Descripción de lo que se generará dentro de la región enmascarada.`},refine_prompt:{name:`refine_prompt`,tooltip:`Ajusta automáticamente el prompt para obtener mejores resultados; desactívalo para usar el prompt exactamente como está escrito.`},seed:{name:`seed`}},outputs:{0:{tooltip:null}}},EDr={description:`Edita imágenes usando el modelo más reciente de Bria`,display_name:`Bria: Edición de imagen FIBO`,inputs:{control_after_generate:{name:`control después de generar`},guidance_scale:{name:`escala_de_guía`,tooltip:`Un valor más alto hace que la imagen siga la instrucción más de cerca.`},image:{name:`imagen`},mask:{name:`máscara`,tooltip:`Si se omite, la edición se aplica a toda la imagen.`},model:{name:`modelo`},moderation:{name:`moderación`,tooltip:`Configuración de moderación`},negative_prompt:{name:`prompt_negativo`},prompt:{name:`prompt`,tooltip:`Instrucción para editar la imagen`},seed:{name:`semilla`},steps:{name:`pasos`},structured_prompt:{name:`prompt_estructurado`,tooltip:`Una cadena que contiene la instrucción de edición estructurada en formato JSON. Usa esto en lugar de la instrucción habitual para un control preciso y programático.`}},outputs:{0:{tooltip:null},1:{name:`prompt_estructurado`,tooltip:null}}},DDr={description:`Amplía una imagen 2x o 4x con Bria, conservando el contenido original.`,display_name:`Aumentar resolución con Bria`,inputs:{auto_downscale:{name:`auto_downscale`,tooltip:`Reduce automáticamente el multiplicador y, si aún no es suficiente, reduce la imagen de entrada cuando la salida superaría el límite.`},desired_increase:{name:`desired_increase`,tooltip:`Multiplicador de resolución. La salida debe ajustarse a un máximo de 8192 píxeles por lado.`},image:{name:`imagen`},moderation:{name:`moderación`,tooltip:`Configuración de moderación`}},outputs:{0:{tooltip:null}}},ODr={description:`Cambia la atmósfera y la dirección de la iluminación de una imagen con Bria. Bria vuelve a renderizar todo el fotograma a aproximadamente 1 megapíxel, por lo que el resultado no queda alineado a píxeles con la entrada.`,display_name:`Bria Reiluminar`,inputs:{image:{name:`imagen`},light_direction:{name:`light_direction`,tooltip:`De dónde procede la luz. Las atmósferas de luz dura, como mediodía, foco sobre el sujeto e iluminación intensa de estudio, son las que más reaccionan a ello.`},light_type:{name:`light_type`,tooltip:`Atmósfera de iluminación que se aplicará.`},moderation:{name:`moderación`,tooltip:`Ajustes de moderación`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`Descripción estructurada de la imagen editada para una edición posterior con Bria FIBO Image Edit.`}}},kDr={description:`Quita el fondo de una imagen usando Bria RMBG 2.0.`,display_name:`Bria: Quitar fondo de imagen`,inputs:{control_after_generate:{name:`control después de generar`},image:{name:`imagen`},moderation:{name:`moderación`,tooltip:`Configuración de moderación`},seed:{name:`semilla`,tooltip:`La semilla controla si el nodo debe ejecutarse de nuevo; los resultados son no deterministas independientemente de la semilla.`}},outputs:{0:{tooltip:null}}},ADr={description:`Quita el fondo de un video usando Bria.`,display_name:`Bria: Quitar fondo de video`,inputs:{background_color:{name:`color de fondo`,tooltip:`Color de fondo para el video de salida.`},control_after_generate:{name:`control después de generar`},seed:{name:`semilla`,tooltip:`La semilla controla si el nodo debe ejecutarse de nuevo; los resultados son no deterministas independientemente de la semilla.`},video:{name:`vídeo`}},outputs:{0:{tooltip:null}}},jDr={description:`Reemplaza el fondo de una imagen con Bria, descrito mediante un prompt o guiado por imágenes de referencia. Los píxeles del sujeto se conservan; el fondo se genera a su alrededor.`,display_name:`Bria Reemplazar fondo de imagen`,inputs:{background:{name:`fondo`,tooltip:`Describe el nuevo fondo con un prompt o guíalo con imágenes de referencia.`},background_mode:{name:`modo`},background_prompt:{name:`prompt`},background_refine_prompt:{name:`refine_prompt`},control_after_generate:{name:`control después de generar`},image:{name:`imagen`},moderation:{name:`moderación`,tooltip:`Ajustes de moderación`},original_quality:{name:`original_quality`,tooltip:`Devuelve el tamaño exacto en píxeles de la entrada en lugar de escalar el resultado a aproximadamente 1 megapíxel. Una entrada grande devuelve entonces una imagen grande.`},seed:{name:`semilla`,tooltip:`La misma semilla suele devolver el mismo fondo; el refinamiento automático del prompt aún puede variarlo.`}},outputs:{0:{tooltip:null},1:{name:`refined_prompt`,tooltip:`El prompt que generó Bria, vacío en la ruta de imagen de referencia.`}}},MDr={description:`Sustituye un objeto de una imagen por otro descrito en texto sin formato usando Bria. Bria vuelve a renderizar todo el fotograma a aproximadamente 1 megapíxel, por lo que el resultado no está alineado a nivel de píxel con la entrada.`,display_name:`Bria Reemplazar objeto`,inputs:{control_after_generate:{name:`control después de generar`},image:{name:`imagen`},instruction:{name:`instrucción`,tooltip:`Qué reemplazar por qué, como «Reemplaza la manzana roja por una pera verde».`},moderation:{name:`moderación`,tooltip:`Ajustes de moderación`},seed:{name:`semilla`,tooltip:`Bria no admite ninguna semilla aquí y vuelve a imaginar la edición en cada llamada, por lo que las ejecuciones repetidas pueden diferir. El valor nunca se envía: solo cambia la clave de caché de este nodo, para que un grafo idéntico ejecute la edición de nuevo en lugar de devolver el resultado almacenado en caché.`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`Descripción estructurada de la imagen editada, para una edición posterior con Bria FIBO Image Edit.`}}},NDr={description:`Cambia una imagen a otra estación con Bria. Toda la escena se vuelve a renderizar, por lo que el paisaje puede cambiar más allá de la estación en sí. Bria vuelve a renderizar todo el fotograma a aproximadamente 1 megapíxel, por lo que el resultado no está alineado a nivel de píxel con la entrada.`,display_name:`Bria Cambiar estación`,inputs:{image:{name:`imagen`},moderation:{name:`moderación`,tooltip:`Ajustes de moderación`},season:{name:`estación`,tooltip:`Estación que se aplicará.`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`Descripción estructurada de la imagen editada, para una edición posterior con Bria FIBO Image Edit.`}}},PDr={description:`Repara una fotografía antigua o dañada con Bria: se eliminan el grano, los arañazos y el desenfoque, y se neutralizan las dominantes de color relacionadas con la edad. Los soportes de cartón y los bordes de estudio pueden recortarse, y los rostros se redibujan. Bria vuelve a renderizar todo el fotograma a aproximadamente 1 megapíxel, por lo que el resultado no está alineado a nivel de píxel con la entrada. Usa Bria Increase Resolution para ampliar en su lugar.`,display_name:`Bria Restaurar foto`,inputs:{image:{name:`imagen`},moderation:{name:`moderación`,tooltip:`Ajustes de moderación`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`Descripción estructurada de la imagen editada para una edición posterior con Bria FIBO Image Edit.`}}},FDr={description:`Elimina el fondo de un video usando Bria y devuelve los fotogramas recortados más una máscara alfa. Conéctalos ambos a un nodo de composición, o envíalos a Guardar WEBM para crear un video transparente.`,display_name:`Bria Eliminar Fondo de Video (Transparente)`,inputs:{control_after_generate:{name:`control después de generar`},seed:{name:`semilla`,tooltip:`La semilla controla si el nodo debe ejecutarse de nuevo; los resultados son no deterministas independientemente de la semilla.`},video:{name:`video`}},outputs:{0:{name:`imágenes`,tooltip:null},1:{name:`mask`,tooltip:null}}},IDr={description:`Borra de un vídeo todo lo que cubra una máscara por fotograma con Bria y rellena el hueco. La máscara debe ser blanca en lo que debe eliminarse y negra en el resto. Bria acepta clips de un máximo de 5,1 segundos a 20-30 fotogramas por segundo con dimensiones de píxeles pares; el audio se conserva de forma predeterminada. El clip devuelto puede tener unos pocos fotogramas menos que la entrada.`,display_name:`Borrador de vídeo Bria`,inputs:{mask:{name:`mask`,tooltip:`Una máscara por cada fotograma del vídeo, blanca donde está el objeto que se debe borrar. Proporciona una máscara o un vídeo de máscara, no ambos.`},mask_video:{name:`mask_video`,tooltip:`Un vídeo de máscara ya codificado con las mismas dimensiones y número de fotogramas que el vídeo. Proporciona una máscara o un vídeo de máscara, no ambos.`},preserve_audio:{name:`preserve_audio`,tooltip:`Conserva la pista de audio de entrada.`},video:{name:`video`,tooltip:`Clip del que borrar.`}},outputs:{0:{tooltip:null}}},LDr={description:`Reemplaza el fondo de un video con una pantalla sólida de croma usando Bria.`,display_name:`Bria Video Green Screen`,inputs:{control_after_generate:{name:`control after generate`},green_shade:{name:`green_shade`,tooltip:`Tono sólido de croma aplicado detrás del primer plano: broadcast_green (#00B140), chroma_green (#00FF00) o blue_screen (#0000FF).`},seed:{name:`seed`,tooltip:`La semilla controla si el nodo debe ejecutarse de nuevo; los resultados son no deterministas independientemente de la semilla.`},video:{name:`video`}},outputs:{0:{tooltip:null}}},RDr={description:`Reemplaza el fondo de un video con una imagen o video proporcionado usando Bria. La salida mantiene la resolución y la tasa de fotogramas del primer plano; un fondo con una relación de aspecto diferente se estira para ajustarse, así que iguala la relación para obtener resultados sin distorsión.`,display_name:`Bria Video Reemplazar Fondo`,inputs:{background_image:{name:`imagen_de_fondo`,tooltip:`Imagen de fondo para componer detrás del primer plano. Proporcione una imagen de fondo o un video de fondo, no ambos.`},background_video:{name:`video_de_fondo`,tooltip:`Video de fondo para componer detrás del primer plano. Proporcione una imagen de fondo o un video de fondo, no ambos.`},control_after_generate:{name:`control después de generar`},seed:{name:`semilla`,tooltip:`La semilla controla si el nodo debe ejecutarse de nuevo; los resultados no son deterministas independientemente de la semilla.`},video:{name:`video`,tooltip:`Video de primer plano cuyo fondo será reemplazado.`}},outputs:{0:{tooltip:null}}},zDr={description:`Construye un prompt JSON para el modelo Ideogram 4.`,display_name:`Construir prompt JSON (Ideogram)`,inputs:{aesthetics:{name:`estética`,tooltip:`Palabras clave estéticas obligatorias (ej. melancólico, cinematográfico, desaturado).`},background:{name:`fondo`,tooltip:`Descripción obligatoria del fondo o entorno de la imagen.`},color_palette:{name:`paleta_de_colores`,tooltip:`Códigos de color hexadecimales que guían los colores dominantes de la imagen. Hasta 16 entradas.`},element:{name:`elemento`,tooltip:`Elementos del prompt desde el nodo Crear Cajas Delimitadoras.`},high_level_description:{name:`descripción_general`,tooltip:`Descripción opcional de la imagen en una o dos frases. Altamente recomendado.`},lighting:{name:`iluminación`,tooltip:`Descripción obligatoria de la iluminación (ej. hora dorada, luz de contorno, sombras dramáticas).`},medium:{name:`medio`,tooltip:`Tipo de medio obligatorio (ej. fotografía, ilustración, 3d_render, pintura, diseño_gráfico). Cuando estilo = foto, establecer en fotografía.`},style:{name:`estilo`}},outputs:{0:{name:`prompt`,tooltip:null}}},BDr={description:`Crea un GLB animado a partir de datos de pose o guarda un archivo de mocap BVH.`,display_name:`Crear archivo de animación 3D`,inputs:{camera_translation:{name:`camera_translation`,tooltip:`Incorpora pred_cam_t en la traslación de la raíz. 'off' = posición de enlace; 'centered' = diferencia desde el fotograma 0; 'absolute' = sin procesar (Z es la profundidad de la cámara, normalmente a metros de distancia).`},format:{name:`formato`,tooltip:`Formato de salida; ambos se envían a Save 3D Model para escribirlos en disco. 'glb' = GLB animado (malla / huesos / openpose / scail). 'bvh' = clip de mocap BVH (un esqueleto; necesita el modelo).`},format_bone_smooth_window:{name:`bone_smooth_window`},format_mesh_style:{name:`mesh_style`},format_mesh_style_bone_vis:{name:`bone_vis`},format_mesh_style_shader:{name:`shader`},fps:{name:`fps`,tooltip:`Frecuencia de fotogramas de la animación.`},pose_data:{name:`pose_data`,tooltip:`Datos de pose 3D.`},sam3d_body_model:{name:`sam3d_body_model`},track_index:{name:`track_index`,tooltip:`-1 = todas las pistas; ≥0 = una sola pista.`}},outputs:{0:{name:`model_3d`,tooltip:null}}},VDr={description:`Renderiza el vídeo final en 1080p de un borrador de Seedance 2.5. El resultado final conserva la escena y el movimiento del borrador, y reutiliza su prompt, referencias, duración, relación de aspecto y configuración de audio.`,display_name:`ByteDance Seedance 2.5 Borrador a vídeo final`,inputs:{draft_task_id:{name:`draft_task_id`,tooltip:`La salida draft_task_id de un nodo de Seedance 2.5 ejecutado con el modelo Seedance 2.5 Draft, o un ID de tarea de borrador pegado. Establece el control de seed de ese nodo en fijo; de lo contrario, la siguiente ejecución generará un borrador nuevo en lugar de reutilizar el que revisaste. Un borrador puede renderizarse durante los 7 días posteriores a su creación.`},watermark:{name:`marca de agua`,tooltip:`Indica si se añade una marca de agua al vídeo.`}},outputs:{0:{tooltip:null}}},HDr={description:`Genera un video usando Seedance 2.0 a partir de una imagen del primer fotograma y, opcionalmente, una imagen del último fotograma.`,display_name:`ByteDance Seedance 2.0 Primer-Último Fotograma a Video`,inputs:{control_after_generate:{name:`control después de generar`},first_frame:{name:`primer_fotograma`,tooltip:`Imagen del primer fotograma para el video.`},first_frame_asset_id:{name:`first_frame_asset_id`,tooltip:`ID de asset de Seedance para usar como primer fotograma. Es excluyente con la entrada de imagen first_frame.`},last_frame:{name:`último_fotograma`,tooltip:`Imagen del último fotograma para el video.`},last_frame_asset_id:{name:`last_frame_asset_id`,tooltip:`ID de asset de Seedance para usar como último fotograma. Es excluyente con la entrada de imagen last_frame.`},model:{name:`modelo`,tooltip:`Seedance 2.5 para el modelo más reciente, vídeos de hasta 30 segundos y salida mp4/mov; Seedance 2.5 Draft para una vista previa rápida en 480p cuyo draft_task_id renderiza el resultado final en 1080p en el nodo Seedance 2.5 Draft to Final Video; Seedance 2.0 para máxima calidad y 4k; Fast para optimizar la velocidad; Mini para la generación más rápida y de menor coste.`},model_duration:{name:`duración`},model_generate_audio:{name:`generar_audio`},model_output_format:{name:`formato_de_salida`},model_prompt:{name:`prompt`},model_resolution:{name:`resolución`},seed:{name:`semilla`,tooltip:`La semilla controla si el nodo debe ejecutarse de nuevo; los resultados son no deterministas independientemente de la semilla.`},watermark:{name:`marca_de_agua`,tooltip:`Indica si se debe añadir una marca de agua al video.`}},outputs:{0:{tooltip:null},1:{name:`draft_task_id`,tooltip:`ID de tarea de una ejecución de Seedance 2.5 Draft. Conéctalo al nodo Seedance 2.5 Draft to Final Video para renderizar el resultado final en 1080p.`}}},UDr={description:`Genera, edita o extiende video usando Seedance 2.0 con imágenes, videos y audio de referencia. Soporta referencia multimodal, edición de video y extensión de video.`,display_name:`ByteDance Seedance 2.5 Referencia a vídeo (Heredado)`,inputs:{control_after_generate:{name:`control después de generar`},model:{name:`modelo`,tooltip:`Seedance 2.5 para el modelo más reciente, vídeos de hasta 30 segundos y salida mp4/mov; Seedance 2.5 Draft para una vista previa rápida en 480p cuyo draft_task_id renderiza el resultado final en 1080p en el nodo Seedance 2.5 Draft to Final Video; Seedance 2.0 para máxima calidad y 4k; Fast para optimizar la velocidad; Mini para la generación más rápida y de menor coste.`},model_auto_downscale:{name:`auto_downscale`},model_auto_upscale:{name:`auto_upscale`},model_duration:{name:`duración`},model_generate_audio:{name:`generar_audio`},model_output_format:{name:`formato_de_salida`},model_prompt:{name:`prompt`},model_ratio:{name:`relación`},model_resolution:{name:`resolución`},model_video_editing:{name:`edición_de_video`},seed:{name:`semilla`,tooltip:`La semilla controla si el nodo debe ejecutarse de nuevo; los resultados son no deterministas independientemente de la semilla.`},watermark:{name:`marca_de_agua`,tooltip:`Indica si se debe añadir una marca de agua al video.`}},outputs:{0:{tooltip:null}}},WDr={description:`Genera, edita o amplía vídeo con Seedance 2.5 o 2.0 mediante imágenes, vídeos y audio de referencia. Admite referencias multimodales, edición de vídeo y ampliación de vídeo.`,display_name:`ByteDance Seedance 2.5 Referencia a vídeo`,inputs:{control_after_generate:{name:`control después de generar`},model:{name:`modelo`,tooltip:`Seedance 2.5 para el modelo más reciente, vídeos de hasta 30 segundos y salida mp4/mov; Seedance 2.5 Draft para una vista previa rápida en 480p cuyo draft_task_id renderiza el resultado final en 1080p en el nodo Seedance 2.5 Draft to Final Video; Seedance 2.0 para máxima calidad y 4k; Fast para optimizar la velocidad; Mini para la generación más rápida y de menor coste.`},model_auto_downscale:{name:`reducción_automática`},model_auto_upscale:{name:`ampliación_automática`},model_duration:{name:`duración`},model_generate_audio:{name:`generar_audio`},model_output_format:{name:`formato_de_salida`},model_prompt:{name:`prompt`},model_ratio:{name:`relación`},model_resolution:{name:`resolución`},model_task_type:{name:`tipo_de_tarea`},seed:{name:`semilla`,tooltip:`La semilla controla si el nodo debe ejecutarse de nuevo; los resultados no son deterministas independientemente de la semilla.`},watermark:{name:`marca de agua`,tooltip:`Si se añade una marca de agua al vídeo.`}},outputs:{0:{tooltip:null},1:{name:`draft_task_id`,tooltip:`ID de tarea de una ejecución de Seedance 2.5 Draft. Conéctalo al nodo Seedance 2.5 Draft to Final Video para renderizar el resultado final en 1080p.`}}},GDr={description:`Genera video usando modelos Seedance 2.0 a partir de un prompt de texto.`,display_name:`ByteDance Seedance 2.0 Texto a Video`,inputs:{control_after_generate:{name:`control después de generar`},model:{name:`modelo`,tooltip:`Seedance 2.5 para el modelo más reciente, vídeos de hasta 30 segundos y salida mp4/mov; Seedance 2.5 Draft para una vista previa rápida en 480p cuyo draft_task_id renderiza el resultado final en 1080p en el nodo Seedance 2.5 Draft to Final Video; Seedance 2.0 para máxima calidad y 4k; Fast para optimizar la velocidad; Mini para la generación más rápida y de menor coste.`},model_duration:{name:`duración`},model_generate_audio:{name:`generar_audio`},model_output_format:{name:`formato_de_salida`},model_prompt:{name:`prompt`},model_ratio:{name:`relación`},model_resolution:{name:`resolución`},seed:{name:`semilla`,tooltip:`La semilla controla si el nodo debe ejecutarse de nuevo; los resultados son no deterministas independientemente de la semilla.`},watermark:{name:`marca_de_agua`,tooltip:`Indica si se debe añadir una marca de agua al video.`}},outputs:{0:{tooltip:null},1:{name:`draft_task_id`,tooltip:`ID de tarea de una ejecución de Seedance 2.5 Draft. Conéctalo al nodo Seedance 2.5 Draft to Final Video para renderizar el resultado final en 1080p.`}}},KDr={description:`Crea un asset de imagen personal de Seedance 2.0. Sube la imagen de entrada y la registra en el grupo de assets indicado. Si group_id está vacío, ejecuta un flujo de autenticación H5 de persona real para crear un nuevo grupo antes de añadir el asset.`,display_name:`Crear asset de imagen usando ByteDance`,inputs:{group_id:{name:`group_id`,tooltip:`Reutiliza un ID de grupo de assets de Seedance existente para omitir la verificación humana repetida para la misma persona. Déjalo vacío para ejecutar la autenticación de persona real en el navegador y crear un nuevo grupo.`},image:{name:`image`,tooltip:`Imagen para registrar como asset personal.`}},outputs:{0:{name:`asset_id`,tooltip:null},1:{name:`group_id`,tooltip:null}}},qDr={description:`Crea un asset de video personal de Seedance 2.0. Sube el video de entrada y lo registra en el grupo de assets indicado. Si group_id está vacío, ejecuta un flujo de autenticación H5 de persona real para crear un nuevo grupo antes de añadir el asset.`,display_name:`Crear asset de video usando ByteDance`,inputs:{group_id:{name:`group_id`,tooltip:`Reutiliza un ID de grupo de assets de Seedance existente para omitir la verificación humana repetida para la misma persona. Déjalo vacío para ejecutar la autenticación de persona real en el navegador y crear un nuevo grupo.`},video:{name:`video`,tooltip:`Video para registrar como asset personal.`}},outputs:{0:{name:`asset_id`,tooltip:null},1:{name:`group_id`,tooltip:null}}},JDr={description:`Generar video usando prompt y primer y último fotograma.`,display_name:`Primer-Último-Fotograma a video usando ByteDance`,inputs:{aspect_ratio:{name:`relación_de_aspecto`,tooltip:`La relación de aspecto del video de salida.`},camera_fixed:{name:`cámara_fija`,tooltip:`Especifica si se debe fijar la cámara. La aplicación añade una instrucción para fijar la cámara a tu prompt, pero no garantiza el efecto real.`},control_after_generate:{name:`control después de generar`},duration:{name:`duración`,tooltip:`La duración del video de salida en segundos.`},first_frame:{name:`primer_fotograma`,tooltip:`Primer fotograma que se utilizará para el video.`},generate_audio:{name:`generar_audio`,tooltip:`Este parámetro se ignora para cualquier modelo excepto seedance-1-5-pro.`},last_frame:{name:`último_fotograma`,tooltip:`Último fotograma que se utilizará para el video.`},model:{name:`modelo`},prompt:{name:`prompt`,tooltip:`El texto prompt utilizado para generar el video.`},resolution:{name:`resolución`,tooltip:`La resolución del video de salida.`},seed:{name:`semilla`,tooltip:`Semilla a utilizar para la generación.`},watermark:{name:`marca_de_agua`,tooltip:`Si se debe añadir una marca de agua "Generado por IA" al video.`}},outputs:{0:{tooltip:null}}},YDr={description:`Generar video usando modelos ByteDance via api basado en imagen y prompt`,display_name:`Imagen a video usando ByteDance`,inputs:{aspect_ratio:{name:`relación_de_aspecto`,tooltip:`La relación de aspecto del video de salida.`},camera_fixed:{name:`cámara_fija`,tooltip:`Especifica si fijar la cámara. La plataforma añade una instrucción para fijar la cámara a tu prompt, pero no garantiza el efecto real.`},control_after_generate:{name:`control después de generar`},duration:{name:`duración`,tooltip:`La duración del video de salida en segundos.`},generate_audio:{name:`generar_audio`,tooltip:`Este parámetro se ignora para cualquier modelo excepto seedance-1-5-pro.`},image:{name:`imagen`,tooltip:`Primer fotograma a usar para el video.`},model:{name:`modelo`},prompt:{name:`prompt`,tooltip:`El prompt de texto usado para generar el video.`},resolution:{name:`resolución`,tooltip:`La resolución del video de salida.`},seed:{name:`semilla`,tooltip:`Semilla a utilizar para la generación.`},watermark:{name:`marca_de_agua`,tooltip:`Si añadir una marca de agua "Generado por IA" al video.`}},outputs:{0:{tooltip:null}}},XDr={description:`Genera voz, música, efectos de sonido y diálogos con varios hablantes a partir de un solo prompt con ByteDance Seed Audio 1.0. Describe en el prompt las voces, la emoción, el ambiente, la música de fondo y los efectos de sonido, e incluye las líneas que se deben pronunciar. Opcionalmente, elige una voz predefinida integrada, clona voces a partir de hasta 3 clips de referencia (etiquetados como {'@'}Audio1-3 en el prompt) o deriva una voz de la imagen de un personaje. Hasta 2 minutos de audio por ejecución. El modelo multilingüe admite 20 idiomas y control de temporización basado en marcas de tiempo.`,display_name:`ByteDance Seed Audio 1.0`,inputs:{control_after_generate:{name:`control after generate`},loudness_rate:{name:`loudness_rate`,tooltip:`Volumen. 0 = normal, 100 = 2.0x, -50 = 0.5x.`},model:{name:`model`,tooltip:`seed-audio-1.0-multilingual: 20 idiomas (inglés, chino, japonés, coreano, español mexicano y castellano, indonesio, alemán, portugués brasileño, francés, tailandés, vietnamita, malayo, filipino, italiano, ruso, neerlandés, polaco, turco, sueco) además de control de tiempo por frase mediante marcas de tiempo como "[5.5s:8.0s] ...". seed-audio-1.0: solo inglés y chino, sin control de tiempo.`},pitch_rate:{name:`pitch_rate`,tooltip:`Desplazamiento de tono en semitonos (-12 a 12).`},reference_mode:{name:`reference_mode`,tooltip:`Cómo condicionar la voz: 'solo texto' (describe todo en el prompt), 'referencia de audio' (clona hasta 3 voces, etiquetadas como @Audio1-3), 'referencia de imagen' (deriva una voz de la imagen de un personaje), o 'voz predefinida' (elige una voz incorporada que lee el prompt).`},sample_rate:{name:`sample_rate`,tooltip:`Frecuencia de muestreo de salida en Hz.`},seed:{name:`seed`,tooltip:`La semilla controla si el nodo debe volver a ejecutarse; los resultados son no deterministas independientemente de la semilla.`},speech_rate:{name:`speech_rate`,tooltip:`Velocidad de habla. 0 = normal, 100 = 2.0x, -50 = 0.5x.`},text_prompt:{name:`text_prompt`,tooltip:`Describe la(s) voz/vozes, emoción, ritmo, ambiente, música de fondo y efectos de sonido, e incluye las líneas a pronunciar (nombra los personajes en línea para diálogos). En el modo 'referencia de audio', referencia los clips conectados por orden como @Audio1, @Audio2, @Audio3. Máximo 3000 caracteres.`}},outputs:{0:{tooltip:null}}},ZDr={description:`Genera respuestas de texto con los modelos Seed 2.0 de ByteDance. Proporciona un prompt de texto y opcionalmente una o más imágenes o videos para contexto multimodal.`,display_name:`ByteDance Seed`,inputs:{control_after_generate:{name:`control after generate`},model:{name:`model`,tooltip:`El modelo Seed utilizado para generar la respuesta.`},model_temperature:{name:`temperature`},prompt:{name:`prompt`,tooltip:`Entrada de texto para el modelo.`},seed:{name:`seed`,tooltip:`Seed controla si el nodo debe ejecutarse de nuevo; los resultados son no deterministas independientemente del seed.`},system_prompt:{name:`system_prompt`,tooltip:`Instrucciones fundamentales que dictan el comportamiento del modelo.`}},outputs:{0:{tooltip:null}}},QDr={description:`Descompone una imagen en una placa de fondo más hasta 16 capas transparentes reposicionables, cada una con orden de apilamiento, caja delimitadora, nombre y descripción.`,display_name:`ByteDance Seedream 5.0 Pro Separación de capas (heredado)`,inputs:{control_after_generate:{name:`controlar después de generar`},crop_layers:{name:`recortar_capas`,tooltip:`Geometría de las salidas por lote de capas/máscaras (layer_stack no se ve afectado y siempre es ajustado). Lienzo completo: cada capa en un lienzo del tamaño base en su posición de caja delimitadora - recomponer directamente con ImageCompositeMasked. Tamaño mínimo: cada capa recortada a su caja delimitadora (rellenada al tamaño de la capa más grande para el lote) - tensores mucho más pequeños; reconstruir la colocación con Layers From Bounding Boxes usando la salida bboxes.`},image:{name:`imagen`,tooltip:`La imagen a separar. Exactamente una imagen, al menos 512x512 píxeles, relación de aspecto entre 1:16 y 16:1. Las entradas mayores a unos 4MP se reducen antes de subir.`},prompt:{name:`prompt`,tooltip:`Cómo separar la imagen. Déjalo vacío para detectar automáticamente y separar todos los elementos principales. Describe los elementos en lenguaje natural para controlar la separación, o apunta a regiones exactas con etiquetas <bbox>izquierda arriba derecha abajo</bbox> (coordenadas por mil de 0-1000).`},prompt_optimization:{name:`optimización_prompt`,tooltip:`Modo de optimización del prompt: 'standard' da mayor calidad, 'fast' menor tiempo de generación.`},seed:{name:`semilla`,tooltip:`Semilla a usar para la generación.`},size:{name:`tamaño`,tooltip:`Nivel de resolución de salida. 'auto' sigue el tamaño de la imagen de entrada (limitado al rango 1K-2K).`},watermark:{name:`marca_de_agua`,tooltip:`Si se añade o no una marca de agua "AI generated" a las imágenes.`}},outputs:{0:{name:`imagen_base`,tooltip:`La imagen base (placa de fondo) sobre la que se apilan las capas.`},1:{name:`máscara_base`,tooltip:`Transparencia de la imagen base (1 = transparente, convención LoadImage); actualmente siempre completamente opaca.`},2:{name:`capas`,tooltip:`Capas transparentes ordenadas de abajo hacia arriba. Modo lienzo completo: colocadas en un lienzo negro del tamaño base en su posición de caja delimitadora. Modo tamaño mínimo: recortadas a su caja delimitadora, ancladas arriba a la izquierda, rellenadas al tamaño de la capa más grande.`},3:{name:`máscaras`,tooltip:`Transparencia por capa, alineada por índice con el lote de capas (1 = transparente, convención LoadImage). Para composición estilo ImageCompositeMasked, añade primero InvertMask.`},4:{name:`bboxes`,tooltip:`Una caja de colocación por capa, alineada por índice con el lote de capas (alimenta ambos, más máscaras, a Layers From Bounding Boxes para reconstruir la colocación por capa): {x, y, width, height, metadata: {name, desc, z_index, native_size, content_rect, flags}}. content_rect = [izquierda, arriba, ancho, alto] es la región de contenido de la capa dentro de su propio marco; se coloca en el lienzo en la posición de la caja más ese desplazamiento.`},5:{name:`pila_de_capas`,tooltip:`Documento de capas listo para editar para Crear Imagen por Capas: la placa base más cada elemento como su propia capa nombrada, recortada y ajustada en su posición real y orden de apilamiento. Conecta directamente, o extiende con Añadir Capa.`}}},$Dr={description:`Descompone una imagen en una placa de fondo y hasta 16 capas transparentes reposicionables, cada una con orden de apilamiento, cuadro delimitador, nombre y descripción.`,display_name:`ByteDance Seedream 5.0 Separación de capas`,inputs:{control_after_generate:{name:`control después de generar`},model:{name:`modelo`},model_crop_layers:{name:`crop_layers`},model_prompt:{name:`prompt`},model_prompt_optimization:{name:`prompt_optimization`},model_seed:{name:`seed`},model_size:{name:`tamaño`},model_watermark:{name:`marca de agua`}},outputs:{0:{name:`base_image`,tooltip:`La imagen base (placa de fondo) sobre la que se apilan las capas.`},1:{name:`base_mask`,tooltip:`Transparencia de la imagen base (1 = transparente, convención de LoadImage); actualmente siempre es completamente opaca.`},2:{name:`capas`,tooltip:`Capas transparentes ordenadas de abajo arriba. Modo de lienzo completo: se colocan en un lienzo negro del tamaño de la base, en la posición de su cuadro delimitador. Modo de tamaño mínimo: se recortan a su cuadro delimitador, se anclan en la esquina superior izquierda y se rellenan hasta el tamaño de la capa más grande.`},3:{name:`máscaras`,tooltip:`Transparencia por capa, alineada por índice con el lote de capas (1 = transparente, convención de LoadImage). Para la composición al estilo ImageCompositeMasked, añade primero InvertMask.`},4:{name:`bboxes`,tooltip:`Un cuadro de colocación por capa, alineado por índice con el lote de capas (introduce ambos, además de masks, en Layers From Bounding Boxes para reconstruir la colocación por capa): {x, y, width, height, metadata: {name, desc, z_index, native_size, content_rect, flags}}. content_rect = [left, top, width, height] es la región de contenido de la capa dentro de su propio marco; se sitúa en el lienzo en la posición del cuadro más ese desplazamiento.`},5:{name:`layer_stack`,tooltip:`Documento de capas listo para editar para Create Layered Image: la placa base más cada elemento como su propia capa con nombre, recortada ajustadamente, en su posición y orden de apilamiento reales. Conéctalo directamente o amplíalo con Add Layer.`}}},eOr={description:`Generación unificada de texto a imagen y edición precisa de oraciones individuales con resolución de hasta 4K.`,display_name:`ByteDance Seedream 4.5 y 5.0`,inputs:{control_after_generate:{name:`control después de generar`},fail_on_partial:{name:`fallar_en_parcial`,tooltip:`Si está habilitado, abortar la ejecución si faltan algunas imágenes solicitadas o devuelven un error.`},height:{name:`alto`,tooltip:"Alto personalizado para la imagen. El valor funciona solo si `predefinición_de_tamaño` está establecido en `Personalizado`."},image:{name:`imagen`,tooltip:`Imagen(es) de entrada para generación de imagen a imagen. Lista de 1-10 imágenes para generación de referencia única o múltiple.`},max_images:{name:`máximo_de_imágenes`,tooltip:`Número máximo de imágenes a generar cuando generación_secuencial_de_imágenes='automático'. El total de imágenes (entrada + generadas) no puede exceder 15.`},model:{name:`modelo`},prompt:{name:`prompt`,tooltip:`Prompt de texto para crear o editar una imagen.`},seed:{name:`semilla`,tooltip:`Semilla a utilizar para la generación.`},sequential_image_generation:{name:`generación_secuencial_de_imagen`,tooltip:`Modo de generación grupal de imágenes. 'deshabilitado' genera una sola imagen. 'automático' permite al modelo decidir si generar múltiples imágenes relacionadas (ej., escenas de historia, variaciones de personajes).`},size_preset:{name:`preajuste_de_tamaño`,tooltip:`Selecciona un tamaño recomendado. Elige Personalizado para usar el ancho y alto a continuación.`},watermark:{name:`marca_de_agua`,tooltip:`Si añadir una marca de agua "Generado por IA" a la imagen.`},width:{name:`ancho`,tooltip:"Ancho personalizado para la imagen. El valor funciona solo si `predefinición_de_tamaño` está establecido en `Personalizado`."}},outputs:{0:{tooltip:null}}},tOr={description:`Generación unificada de texto a imagen y edición precisa de una sola frase hasta una resolución de 4K.`,display_name:`ByteDance Seedream 4.5 y 5.0 (heredado)`,inputs:{control_after_generate:{name:`control después de generar`},model:{name:`modelo`},model_height:{name:`altura`},model_size_preset:{name:`preajuste_de_tamaño`},model_width:{name:`ancho`},prompt:{name:`prompt`,tooltip:`Indicador de texto para crear o editar una imagen.`},seed:{name:`semilla`,tooltip:`Semilla a utilizar para la generación.`},thinking:{name:`thinking`,tooltip:`Activa el razonamiento de optimización de prompts del modelo ('thinking') para una mejor adherencia. Puede aumentar considerablemente el tiempo de generación, especialmente en Seedream 5.0 Pro. Solo se puede desactivar para texto a imagen (no cuando se proporcionan imágenes de referencia).`},watermark:{name:`marca de agua`,tooltip:`Indica si se añade una marca de agua de "Generado por IA" a la imagen.`}},outputs:{0:{tooltip:null}}},nOr={description:`Generación unificada de texto a imagen y edición precisa con una sola frase en resolución de hasta 4K.`,display_name:`ByteDance Seedream 4.5 y 5.0`,inputs:{control_after_generate:{name:`control después de generar`},model:{name:`modelo`},model_height:{name:`altura`},model_prompt_optimization:{name:`optimización_del_prompt`},model_seed:{name:`semilla`},model_size_preset:{name:`preajuste_de_tamaño`},model_thinking:{name:`razonamiento`},model_watermark:{name:`marca_de_agua`},model_width:{name:`anchura`},prompt:{name:`prompt`,tooltip:`Prompt de texto para crear o editar una imagen.`}},outputs:{0:{tooltip:null}}},rOr={description:`Generar video usando modelos de ByteDance mediante API basado en prompt`,display_name:`Texto a video usando ByteDance`,inputs:{aspect_ratio:{name:`relación_de_aspecto`,tooltip:`La relación de aspecto del video de salida.`},camera_fixed:{name:`cámara_fija`,tooltip:`Especifica si fijar la cámara. La aplicación añade una instrucción para fijar la cámara a tu prompt, pero no garantiza el efecto real.`},control_after_generate:{name:`control después de generar`},duration:{name:`duración`,tooltip:`La duración del video de salida en segundos.`},generate_audio:{name:`generar_audio`,tooltip:`Este parámetro se ignora para cualquier modelo excepto seedance-1-5-pro.`},model:{name:`modelo`},prompt:{name:`prompt`,tooltip:`El prompt de texto utilizado para generar el video.`},resolution:{name:`resolución`,tooltip:`La resolución del video de salida.`},seed:{name:`semilla`,tooltip:`Semilla a utilizar para la generación.`},watermark:{name:`marca_de_agua`,tooltip:`Si añadir una marca de agua "Generado por IA" al video.`}},outputs:{0:{tooltip:null}}},iOr={description:`Aumenta la resolución y restaura un vídeo con ByteDance vCube: superresolución de hasta 8K, eliminación de artefactos de compresión y ruido, mejora del color y la nitidez, e interpolación de fotogramas opcional.`,display_name:`ByteDance vCube Mejora de vídeo`,inputs:{bitrate_level:{name:`nivel_de_tasa_de_bits`,tooltip:`Tasa de bits objetivo del archivo entregado, ajustada a la resolución y frecuencia de fotogramas de salida.`},fps:{name:`fps`,tooltip:`Frecuencia de fotogramas de salida. Una frecuencia superior a la de origen activa la interpolación de fotogramas por IA; una inferior descarta fotogramas. 'source' conserva la frecuencia de origen, hasta 120 fps. Las frecuencias superiores a 30 fps cuestan 2x y las superiores a 60 fps, 4x.`},resolution:{name:`resolución`,tooltip:`Resolución de salida. El lado corto se establece en el nivel elegido y el lado largo sigue la relación de aspecto de origen. 'source' conserva el tamaño de origen; 'custom' establece el lado corto en píxeles. A las fuentes más anchas o altas que aproximadamente 2.2:1 se les cobra un nivel de resolución superior.`},tool_version:{name:`versión_de_herramienta`,tooltip:`'standard' equilibra velocidad y calidad con más de 10 algoritmos de mejora. 'professional' utiliza más de 30 algoritmos para una restauración de calidad cinematográfica, tarda aproximadamente 3x más y cuesta 10x más.`},tool_version_enhance_style:{name:`estilo_de_mejora`},tool_version_scene:{name:`scene`},video:{name:`vídeo`,tooltip:`Vídeo que se va a mejorar. La resolución de origen debe ser como máximo de 2560x1440 (2K); el tamaño de salida se establece mediante la entrada de resolución.`}},outputs:{0:{tooltip:null}}},aOr={display_name:`Guía CFG`,inputs:{cfg:{name:`cfg`},model:{name:`modelo`},negative:{name:`negativo`},positive:{name:`positivo`}},outputs:{0:{tooltip:null}}},oOr={display_name:`Normalización CFG`,inputs:{model:{name:`modelo`},pre_cfg:{name:`pre_cfg`,tooltip:`Si está activado, reajusta el ruido combinado ANTES de la combinación CFG del muestreador, sin limitar (puede amplificar). Coincide con el CFG escalado por norma utilizado por modelos como Lens. El valor predeterminado en falso mantiene el comportamiento original de atenuación solo en el espacio x0 después del CFG.`},strength:{name:`fuerza`}},outputs:{0:{name:`modelo_parcheado`,tooltip:null}}},sOr={description:`Anula cfg a un valor fijo sobre un intervalo de porcentaje [inicio, fin] de los pasos. Con múltiples anulaciones, la más cercana al muestreador prevalece en caso de solapamiento.`,display_name:`Anulación de CFG`,inputs:{cfg:{name:`cfg`},end_percent:{name:`porcentaje_fin`},model:{name:`modelo`},start_percent:{name:`porcentaje_inicio`}},outputs:{0:{tooltip:null}}},cOr={display_name:`CFGZeroStar`,inputs:{model:{name:`modelo`}},outputs:{0:{name:`modelo_parcheado`,tooltip:null}}},lOr={display_name:`Multiplicar atención CLIP`,inputs:{clip:{name:`clip`},k:{name:`k`},out:{name:`salida`},q:{name:`q`},v:{name:`v`}},outputs:{0:{tooltip:null}}},uOr={description:`Recetas:
