`,tooltip:`Una imagen 2D para guiar el proceso de texturizado. No se puede usar al mismo tiempo que 'text_style_prompt'.`},meshy_task_id:{name:`id_de_tarea_meshy`},model:{name:`modelo`},pbr:{name:`pbr`},text_style_prompt:{name:`prompt_de_estilo_de_texto`,tooltip:`Describe el estilo de textura deseado para el objeto usando texto. Máximo 600 caracteres. No se puede usar al mismo tiempo que 'image_style'.`},texture_resolution:{name:`resolución de textura`,tooltip:`Resolución de la textura de color base. Las resoluciones más altas capturan más detalle de la superficie.`}},outputs:{0:{name:`archivo_del_modelo`,tooltip:null},1:{name:`id_de_tarea_meshy`,tooltip:null},2:{name:`GLB`,tooltip:null},3:{name:`FBX`,tooltip:null}}},aIr={description:`Edita o combina hasta 10 imágenes de referencia siguiendo un prompt de texto mediante el modelo Muse Image de Meta.`,display_name:`Edición de imágenes Meta Muse`,inputs:{control_after_generate:{name:`control después de generar`},model:{name:`model`,tooltip:`Modelo que se va a usar.`},model_aspect_ratio:{name:`aspect_ratio`},model_enable_image_search:{name:`enable_image_search`},model_enable_shell:{name:`enable_shell`},model_enable_web_search:{name:`enable_web_search`},model_prompt:{name:`prompt`},model_reasoning_strength:{name:`reasoning_strength`},model_seed:{name:`seed`}},outputs:{0:{tooltip:null}}},oIr={description:`Genera imágenes a partir de un prompt de texto mediante el modelo Muse Image de Meta, que razona sobre el prompt antes de renderizar.`,display_name:`Meta Muse Image: Texto a imagen`,inputs:{control_after_generate:{name:`control después de generar`},model:{name:`model`,tooltip:`Modelo que se va a usar.`},model_aspect_ratio:{name:`aspect_ratio`},model_enable_image_search:{name:`enable_image_search`},model_enable_shell:{name:`enable_shell`},model_enable_web_search:{name:`enable_web_search`},model_prompt:{name:`prompt`},model_reasoning_strength:{name:`reasoning_strength`},model_seed:{name:`seed`}},outputs:{0:{tooltip:null}}},sIr={description:`Fija una imagen, un clip corto, audio o un clip con su banda sonora en cualquier fotograma de un vídeo MiniMax H3. Encadena varios nodos para fijar varios fotogramas.`,display_name:`Añadir guía para MiniMax H3`,inputs:{audio:{name:`audio`,tooltip:`Pista de audio que se anclará a partir del mismo índice de fotograma, recortada a la duración restante del vídeo.`},audio_vae:{name:`audio_vae`,tooltip:`VAE de audio, necesario cuando se conecta audio.`},frame_idx:{name:`frame_idx`,tooltip:`Índice del fotograma en el que se anclará la imagen o el primer fotograma del clip. Los valores negativos se cuentan desde el final del vídeo.`},image:{name:`image`,tooltip:`Imagen o fotogramas de vídeo que se anclarán. Los lotes de varios fotogramas se anclan como un clip y se recortan a las longitudes de clip válidas del modelo: 5, 22, 39... (17k + 5) fotogramas. Los lotes de menos de 5 fotogramas usan solo la primera imagen.`},latent:{name:`latente`},positive:{name:`positivo`},vae:{name:`vae`,tooltip:`VAE de vídeo, necesario cuando se conecta una imagen.`}},outputs:{0:{name:`positive`,tooltip:null}}},cIr={description:`Aplica un MiniMax H3 Fun ControlNet a un modelo de texto a vídeo como parche de modelo.`,display_name:`Aplicar MiniMax H3 Fun ControlNet`,inputs:{control_video:{name:`control_video`},end_percent:{name:`end_percent`},mask:{name:`mask`,tooltip:`1 marca las regiones que se regenerarán.`},model:{name:`model`},model_patch:{name:`model_patch`},source_video:{name:`source_video`,tooltip:`Vídeo detrás de la mask; solo se lee cuando se proporciona una mask.`},start_percent:{name:`start_percent`},strength:{name:`strength`},vae:{name:`vae`}},outputs:{0:{tooltip:null}}},lIr={display_name:`MiniMax H3 Imagen a Video`,inputs:{clip:{name:`clip`},first_frame:{name:`primer_fotograma`},height:{name:`alto`},last_frame:{name:`último_fotograma`},length:{name:`duración`,tooltip:`Cantidad de fotogramas a 24 fps, ajustada a la cuadrícula de 17k+5 del modelo (124 = ~5s; el rango entrenado es ~124-362, valores mayores no están probados)`},prompt:{name:`prompt`},vae:{name:`vae`},width:{name:`ancho`}},outputs:{0:{name:`positivo`,tooltip:null},1:{tooltip:null}}},uIr={description:`Condicionamiento de referencia <Picture i> / <Video k> / <Audio j> para MiniMax H3. Usa las mismas etiquetas al generar el prompt.`,display_name:`MiniMax H3 Referencia a Video`,inputs:{audio_vae:{name:`audio_vae`,tooltip:`VAE de audio. Sin él, el audio de referencia solo condiciona al codificador de texto.`},clip:{name:`clip`},height:{name:`alto`},length:{name:`duración`,tooltip:`Cantidad de fotogramas a 24 fps, (124 = ~5s, rango entrenado es ~124-362)`},prompt:{name:`prompt`},ref_audios:{name:`audios_ref`},ref_image_size:{name:`tamaño_imagen_ref`,tooltip:`Tamaño de la imagen de referencia. 'match' escala cada referencia (solo reducción, manteniendo la proporción) al área de píxeles de la generación; 'max' usa el borde corto de 2048px del pipeline de referencia para mejor fidelidad de identidad. Los tokens de referencia se mantienen en cada paso de muestreo, por lo que 'max' puede ser varias veces más lento.`},ref_images:{name:`imágenes_ref`},ref_video_audios:{name:`audios_video_ref`},ref_videos:{name:`videos_ref`},vae:{name:`vae`,tooltip:`VAE de vídeo. Sin él, las imágenes/vídeos de referencia solo condicionan al codificador de texto.`},width:{name:`ancho`}},outputs:{0:{name:`positivo`,tooltip:null},1:{tooltip:null}}},dIr={description:`Establece los desplazamientos del flujo de video/audio.`,display_name:`MiniMax H3 Sigma Shift`,inputs:{model:{name:`modelo`},shift_audio:{name:`desplazamiento de audio`},shift_video:{name:`desplazamiento de video`}},outputs:{0:{tooltip:null}}},fIr={description:`Usa un modelo CLIP MiniMax Music3 para generar la secuencia de condicionamiento acústico.`,display_name:`Codificación de texto MiniMax Music3`,inputs:{caption:{name:`caption`},cfg_scale:{name:`cfg_scale`},clip:{name:`clip`},control_after_generate:{name:`control después de generar`},lyrics:{name:`letras`},max_duration:{name:`max_duration`,tooltip:`Duración máxima en segundos; el modelo puede terminar la canción antes.`},seed:{name:`semilla`},top_k:{name:`top_k`}},outputs:{0:{tooltip:null},1:{name:`segundos`,tooltip:null}}},pIr={description:`Analiza el contexto de texto y medios con MiniMax H3 Context IR y genera un prompt de vídeo mejorado y estructurado. Conecta la salida al prompt de un nodo de vídeo MiniMax H3 y adjunta allí los mismos medios en el mismo orden, ya que el prompt mejorado hace referencia a los medios adjuntos por posición.`,display_name:`MiniMax H3 Context IR (Mejorador de prompts)`,inputs:{first_frame:{name:`first_frame`,tooltip:`Primer fotograma del vídeo que pretende generar. No se puede combinar con medios de referencia.`},last_frame:{name:`last_frame`,tooltip:`Último fotograma del vídeo que pretende generar. No se puede combinar con medios de referencia.`},model:{name:`model`,tooltip:`Modelo que se usará para mejorar el prompt.`},model_duration:{name:`duration`},model_prompt:{name:`prompt`},model_ratio:{name:`ratio`}},outputs:{0:{tooltip:null}}},mIr={description:`Genera vídeo a partir de una imagen de primer fotograma y una imagen opcional de último fotograma mediante los modelos MiniMax H3. La relación de aspecto del vídeo sigue las imágenes proporcionadas.`,display_name:`MiniMax H3 Primer-Último Fotograma a Video`,inputs:{control_after_generate:{name:`control after generate`},first_frame:{name:`first_frame`,tooltip:`Imagen del primer fotograma para el video.`},last_frame:{name:`last_frame`,tooltip:`Imagen opcional de último fotograma para el video.`},model:{name:`model`,tooltip:`Modelo a utilizar para la generación de video.`},model_duration:{name:`duration`},model_prompt:{name:`prompt`},model_resolution:{name:`resolution`},seed:{name:`seed`,tooltip:`Semilla aleatoria. La misma solicitud con la misma semilla da resultados similares, pero no idénticos garantizados.`},watermark:{name:`watermark`,tooltip:`Si se debe a