ودی.`}},outputs:{0:{tooltip:null}}},k4r={display_name:`تبدیل رنگ به ماسک`,inputs:{color:{name:`رنگ`},image:{name:`تصویر`}},outputs:{0:{tooltip:null}}},A4r={description:`دو تصویر را به صورت کنار هم با اسلایدر مقایسه می‌کند.`,display_name:`مقایسه تصویر`,inputs:{compare_view:{name:`نمای مقایسه`},image_a:{name:`تصویر A`},image_b:{name:`تصویر B`}}},j4r={display_name:`ترکیب تصویر با ماسک`,inputs:{destination:{name:`مقصد`},mask:{name:`ماسک`},resize_source:{name:`تغییر اندازه مبدأ`},source:{name:`مبدأ`},x:{name:`مختصات افقی (x)`},y:{name:`مختصات عمودی (y)`}},outputs:{0:{tooltip:null}}},M4r={display_name:`ایجاد تصویر لایه‌ای`,inputs:{compositor:{name:`ترکیب‌کننده`,tooltip:`ترکیب لایه‌ای ذخیره‌شده توسط ویرایشگر ترکیب‌کننده.`},layers:{name:`لایه‌ها`,tooltip:`پشته لایه‌ها برای ترکیب؛ آن را با افزودن لایه بسازید. آیتم‌ها بر اساس z_index چیده می‌شوند، فریم‌های دسته‌ای درون یک آیتم به لایه‌های متوالی گسترش می‌یابند و جایگذاری آیتم، شفافیت و حالت ترکیب، ترکیب اولیه را تعیین می‌کنند. بدون بوم سند صریح، اندازه بر اساس بیشترین گستره ممکن از لایه‌های قرار داده شده تعیین می‌شود. ترکیب ذخیره‌شده‌ای که با ورودی‌های فعلی مطابقت دارد، اولویت دارد.`}},outputs:{0:{tooltip:`تصویر ترکیب‌شده. اگر ترکیب دارای نواحی شفاف باشد (مثلاً پس‌زمینه مخفی)، کانال آلفا را حمل می‌کند، در غیر این صورت فقط RGB ساده است.`},1:{tooltip:`شفافیت ترکیب (۱ = کاملاً شفاف). اگر ترکیب مات باشد، همه مقادیر صفر هستند.`}}},N4r={display_name:`برش تصویر`,inputs:{height:{name:`ارتفاع`},image:{name:`تصویر`},width:{name:`عرض`},x:{name:`مختصات افقی (x)`},y:{name:`مختصات عمودی (y)`}},outputs:{0:{tooltip:null}}},P4r={display_name:`برش تصویر بر اساس ماسک`,inputs:{background:{name:`پس‌زمینه`,tooltip:`رنگ پس‌زمینه در پشت سوژهٔ ماسک‌شده.`},grow_mask:{name:`grow_mask`,tooltip:`پیش از برش، ماسک را به این تعداد پیکسل گسترش یا کوچک می‌کند.`},height:{name:`ارتفاع`,tooltip:`ارتفاع خروجی بر حسب پیکسل.`},images:{name:`تصاویر`},masks:{name:`ماسک‌ها`},pad_factor:{name:`pad_factor`,tooltip:`حاشیهٔ اضافی پیرامون کادر محدودکنندهٔ ماسک، به‌صورت ضری