زی راهنماها`},Qai={name:`ذخیره و بازیابی موقعیت و سطح بزرگ‌نمایی بوم در workflowها`},$ai={name:`نمایش مدل‌های مفقود در برگهٔ مشکلات`,tooltip:`وقتی غیرفعال باشد، فایل‌های مدل یافت‌نشده در برگهٔ مشکلات فهرست نمی‌شوند و nodeهای آن‌ها برجسته نمی‌شوند.`},eoi={name:`روش پیش‌نمایش زنده`,options:{auto:`خودکار`,default:`پیش‌فرض`,latent2rgb:`latent2rgb`,none:`هیچ‌کدام`,taesd:`taesd`},tooltip:`روش پیش‌نمایش زنده هنگام تولید تصویر. «پیش‌فرض» از تنظیم CLI سرور استفاده می‌کند.`},toi={name:`تعداد ارقام اعشاری گرد کردن ابزارک اعشاری [۰ = خودکار].`,tooltip:`(نیاز به بارگذاری مجدد صفحه)`},noi={name:`سرعت حرکت خودکار`,tooltip:`حداکثر سرعت هنگام حرکت خودکار با کشیدن به لبه بوم. برای غیرفعال‌سازی حرکت خودکار، مقدار را روی ۰ قرار دهید.`},roi={name:`نمایش اطلاعات بوم در گوشه پایین سمت چپ (fps و غیره)`},ioi={name:`نمایش منوی بوم گراف`},aoi={name:`فعال‌سازی میانبر بزرگ‌نمایی سریع (Ctrl + Shift + کشیدن)`},ooi={name:`حذف شناسه‌های تکراری node در زیرگراف`,tooltip:`شناسه‌های تکراری node در زیرگراف‌ها هنگام بارگذاری workflow به‌صورت خودکار دوباره اختصاص داده می‌شوند.`},soi={name:`نشانگرهای میانه‌ی پیوند`,options:{Arrow:`پیکان`,Circle:`دایره`,None:`هیچ‌کدام`}},coi={name:`انتخاب زنده`,tooltip:`در صورت فعال بودن، nodeها به صورت آنی هنگام کشیدن مستطیل انتخاب، انتخاب یا لغو انتخاب می‌شوند؛ مشابه سایر ابزارهای طراحی.`},loi={name:`سرعت بزرگ‌نمایی بوم`},uoi={name:`فاصله داخلی nodeهای انتخاب‌شده در گروه`},doi={name:`دوبار کلیک روی عنوان گروه برای ویرایش`},foi={name:`عملکرد هنگام رها کردن پیوند (بدون کلید ترکیبی)`,options:{"context menu":`منوی زمینه`,"no action":`بدون عمل`,"search box":`جعبه جستجو`}},poi={name:`عملکرد هنگام رها کردن پیوند (کلید Shift)`,options:{"context menu":`منوی زمینه`,"no action":`بدون عمل`,"search box":`جعبه جستجو`}},moi={name:`حالت نمایش پیوند`,options:{Hidden:`مخفی`,Linear:`خطی`,Spline:`اسپلاین`,Straight:`مستقیم`},tooltip:`ظاهر و نمایش پیوندهای ارتباطی بین nodeها روی canvas را کنترل می‌کند.`},hoi={name:`فعال‌سازی نمایشگر سه‌بعدی (بتا)`,tooltip:`نمایشگر سه‌بعدی (بتا) را برای nodeهای انتخاب‌شده فعال می‌کند. این قابلیت به شما امکان می‌دهد مدل‌های سه‌بعدی را مستقیماً در نمایشگر سه‌بعدی با اندازه کامل مشاهده و با آن‌ها تعامل داشته باشید.`},goi={name:`رنگ پس‌زمینه اولیه`,tooltip:`رنگ پیش‌فرض پس‌زمینه صحنه سه‌بعدی را کنترل می‌کند. این تنظیم ظاهر پس‌زمینه را هنگام ایجاد یک ابزارک سه‌بعدی جدید تعیین می‌کند، اما پس از ایجاد، می‌توان آن را برای هر ابزارک به صورت جداگانه تغییر داد.`},_oi={name:`نوع دوربین اولیه`,options:{orthographic:`orthographic`,perspective:`perspective`},tooltip:`تعیین می‌کند که دوربین به صورت پیش‌فرض هنگام ایجاد یک ابزارک سه‌بعدی جدید، perspective یا orthographic باشد. این پیش‌فرض را می‌توان برای هر ابزارک به صورت جداگانه تغییر داد.`},voi={name:`گام تنظیم نور`,tooltip:`اندازه گام هنگام تنظیم شدت نور در صحنه‌های سه‌بعدی را کنترل می‌کند. مقدار گام کوچکتر امکان کنترل دقیق‌تر نور را فراهم می‌کند، در حالی که مقدار بزرگ‌تر باعث تغییرات محسوس‌تر در هر تنظیم می‌شود.`},yoi={name:`شدت نور اولیه`,tooltip:`سطح روشنایی پیش‌فرض نور در صحنه سه‌بعدی را تعیین می‌کند. این مقدار مشخص می‌کند که نورها هنگام ایجاد یک ابزارک سه‌بعدی جدید با چه شدتی به اشیاء تابیده می‌شوند، اما می‌توان آن را برای هر ابزارک به صورت جداگانه تغییر داد.`},boi={name:`حداکثر شدت نور`,tooltip:`حداکثر مقدار مجاز شدت نور برای صحنه‌های سه‌بعدی را تعیین می‌کند. این مقدار، بالاترین حد روشنایی را هنگام تنظیم نور در هر ابزارک سه‌بعدی مشخص می‌کند.`},xoi={name:`حداقل شدت نور`,tooltip:`حداقل مقدار مجاز شدت نور برای صحنه‌های سه‌بعدی را تعیین می‌کند. این مقدار، پایین‌ترین حد روشنایی را هنگام تنظیم نور در هر ابزارک سه‌بعدی مشخص می‌کند.`},Soi={name:`موتور PLY`,options:{fastply:`fastply`,threejs:`threejs`},tooltip:`موتور بارگذاری فایل‌های PLY را انتخاب کنید. «threejs» از PLYLoader بومی Three.js استفاده می‌کند (مناسب برای فایل‌های مش PLY). «fastply» از یک بارگذار بهینه‌شده برای فایل‌های point cloud PLY به صورت ASCII استفاده می‌کند. «sparkjs» از Spark.js برای فایل‌های 3D Gaussian Splatting PLY استفاده می‌کند.`},Coi={name:`نمایش اولیه شبکه`,tooltip:`تعیین می‌کند که شبکه (Grid) به صورت پیش‌فرض هنگام ایجاد یک ابزارک سه‌بعدی جدید قابل مشاهده باشد یا خیر. این پیش‌فرض را می‌توان برای هر ابزارک به صورت جداگانه تغییر داد.`},woi={name:`زبان`},Toi={name:`ضریب سرعت تنظیم قلم‌مو`,tooltip:`کنترل می‌کند که اندازه و سختی قلم‌مو هنگام تنظیم با چه سرعتی تغییر کند. مقادیر بالاتر به معنای تغییرات سریع‌تر است.`},Eoi={name:`قفل تنظیم قلم‌مو به محور غالب`,tooltip:`در صورت فعال بودن، تنظیمات قلم‌مو فقط اندازه یا سختی را بر اساس جهتی که بیشتر حرکت می‌کنید تغییر می‌دهد.`},Doi={name:`بارگذاری خودکار همه پوشه‌های مدل`,tooltip:`اگر فعال باشد، همه پوشه‌ها به محض باز کردن کتابخانه مدل بارگذاری می‌شوند (این کار ممکن است باعث تأخیر در بارگذاری شود). اگر غیرفعال باشد، پوشه‌های مدل در سطح ریشه فقط پس از کلیک شما بارگذاری می‌شوند.`},Ooi={name:`نمایش نام در نمای درختی کتابخانه مدل`,options:{filename:`filename`,title:`title`},tooltip:`گزینه «filename» را انتخاب کنید تا نمای ساده‌ای از نام فایل خام (بدون مسیر یا پسوند ".safetensors") در لیست مدل نمایش داده شود. گزینه «title» عنوان متادیتای قابل تنظیم مدل را نمایش می‌دهد.`},koi={name:`حالت نشان شناسه نود`,options:{None:`هیچ‌کدام`,"Show all":`نمایش همه`}},Aoi={name:`حالت نشان چرخه عمر نود`,options:{None:`هیچ‌کدام`,"Show all":`نمایش همه`}},joi={name:`حالت نشان منبع نود`,options:{"Hide built-in":`مخفی کردن داخلی‌ها`,None:`هیچ‌کدام`,"Show all":`نمایش همه`}},Moi={name:`نمایش نشان قیمت‌گذاری API نود`},Noi={name:`طراحی جدید کتابخانه Node`,tooltip:`فعال‌سازی نوار کناری بازطراحی‌شده کتابخانه node با تب‌های (ضروری، همه، سفارشی)، جستجوی بهبود یافته و پیش‌نمایش هنگام قرار گرفتن نشانگر ماوس.`},Poi={name:`فعال‌سازی جایگزینی خودکار node`,tooltip:`در صورت فعال بودن، nodeهای مفقود می‌توانند به‌طور خودکار با معادل‌های جدیدتر خود جایگزین شوند اگر نگاشت جایگزینی وجود داشته باشد.`},Foi={name:`پیاده‌سازی جعبه جستجوی نود`,options:{default:`پیش‌فرض`,"litegraph (legacy)":`litegraph (قدیمی)`,"v1 (legacy)":`v۱ (قدیمی)`}},Ioi={name:`افزودن نودها دنبال‌رو نشانگر ماوس`,tooltip:`در صورت فعال بودن، نودهایی که از جعبه جستجو اضافه می‌شوند تا زمان کلیک برای قرار دادن، نشانگر ماوس را دنبال می‌کنند. این گزینه فقط برای پیاده‌سازی پیش‌فرض اعمال می‌شود.`},Loi={name:`پیش‌نمایش نود`,tooltip:`فقط برای پیاده‌سازی پیش‌فرض اعمال می‌شود`},Roi={name:`نمایش دسته‌بندی نود در نتایج جستجو`,tooltip:`فقط برای پیاده‌سازی پیش‌فرض اعمال می‌شود`},zoi={name:`نمایش نام شناسه نود در نتایج جستجو`,tooltip:`فقط برای پیاده‌سازی پیش‌فرض اعمال می‌شود`},Boi={name:`نمایش فراوانی نود در نتایج جستجو`,tooltip:`فقط برای پیاده‌سازی پیش‌فرض اعمال می‌شود`},Voi={name:`تعداد پیشنهادهای node`,tooltip:`فقط برای جعبه جستجوی litegraph/منوی زمینه`},Hoi={name:`نمایش عرض × ارتفاع زیر پیش‌نمایش تصویر`},Uoi={name:`نمایش همیشگی ابزارهای پیشرفته در همه نودها`,tooltip:`در صورت فعال بودن، ابزارهای پیشرفته همیشه در همه نودها قابل مشاهده هستند و نیازی به باز کردن جداگانه آن‌ها نیست.`},Woi={name:`اتصال خودکار لینک به اسلات نود`,tooltip:`هنگام کشیدن یک لینک روی نود، لینک به طور خودکار به ورودی مناسب روی نود متصل می‌شود.`},Goi={name:`حفظ همه لینک‌ها هنگام حذف نود`,tooltip:`هنگام حذف یک نود، تلاش می‌شود همه ورودی‌ها و خروجی‌های آن مجدداً به هم متصل شوند (با عبور از نود حذف‌شده).`},Koi={name:`ویرایش عنوان نود با دوبار کلیک`},qoi={name:`ایجاد نود Reroute با کلیک وسط`},Joi={name:`شفافیت نود`},Yoi={name:`نمایش نودهای منسوخ در جستجو`,tooltip:`نودهای منسوخ به طور پیش‌فرض در رابط کاربری پنهان هستند، اما در workflowهای موجود که از آن‌ها استفاده می‌کنند، همچنان فعال خواهند بود.`},Xoi={name:`نمایش نودهای آزمایشی در جستجو`,tooltip:`نودهای آزمایشی در رابط کاربری به این صورت علامت‌گذاری می‌شوند و ممکن است در نسخه‌های آینده تغییرات اساسی یا حذف شوند. در workflowهای تولیدی با احتیاط استفاده شود.`},Zoi={name:`برجسته‌سازی نود هنگام اتصال لینک`,tooltip:`هنگام کشیدن یک لینک روی نود با ورودی مناسب، نود برجسته می‌شود.`},Qoi={name:`نمایش به‌روزرسانی نسخه‌ها`,tooltip:`نمایش به‌روزرسانی‌ها برای مدل‌های جدید و ویژگی‌های اصلی جدید.`},$oi={name:`میزان جابجایی اشاره‌گر هنگام کلیک (حداکثر فاصله)`,tooltip:`اگر اشاره‌گر بیش از این فاصله در هنگام نگه داشتن دکمه حرکت کند، به عنوان کشیدن (drag) در نظر گرفته می‌شود نه کلیک.

به جلوگیری از جابجایی ناخواسته اشیاء هنگام حرکت اشاره‌گر در حین کلیک کمک می‌کند.`},esi={name:`بازه زمانی دوبار کلیک (حداکثر)`,tooltip:`حداکثر زمان به میلی‌ثانیه بین دو کلیک برای ثبت دوبار کلیک. افزایش این مقدار ممکن است در صورتی که دوبار کلیک گاهی ثبت نمی‌شود، کمک کند.`},tsi={name:`فرمت تصویر پیش‌نمایش`,tooltip:`هنگام نمایش پیش‌نمایش در ابزارک تصویر، آن را به یک تصویر سبک مانند webp، jpeg، webp;50 و غیره تبدیل می‌کند.`},nsi={name:`درخواست نام فایل هنگام ذخیره workflow`},rsi={name:`محدودیت تعداد batch`,tooltip:`حداکثر تعداد taskهایی که با یک کلیک به صف اضافه می‌شوند`},isi={name:`اندازه تاریخچه صف`,tooltip:`حداکثر تعداد taskهایی که در تاریخچه صف نمایش داده می‌شوند.`},asi={name:`استفاده از صف کار یکپارچه در پنل کناری دارایی‌ها`,tooltip:`پنل شناور صف کار را با صف کاری معادل که در پنل کناری دارایی‌ها قرار دارد جایگزین می‌کند. می‌توانید این گزینه را غیرفعال کنید تا به چیدمان پنل شناور بازگردید.`},osi={name:`نمایش زبانهٔ مشکلات در پنل کناری`,tooltip:`در صورت فعال بودن، زبانهٔ مشکلات در پنل کناری راست نمایش داده می‌شود تا خطاهای مسدودکننده و منابعِ مفقودی که نیاز به راه‌اندازی دارند را نشان دهد.`},ssi={name:`محل نوار کناری`,options:{left:`چپ`,right:`راست`}},csi={name:`اندازه نوار کناری`,options:{normal:`معمولی`,small:`کوچک`}},lsi={name:`سبک نوار کناری`,options:{connected:`متصل`,floating:`شناور`}},usi={name:`عرض یکپارچه نوار کناری`},dsi={name:`اندازه شبکه برای چسباندن به شبکه`,tooltip:`هنگام کشیدن و تغییر اندازه nodeها با نگه داشتن shift، آن‌ها به شبکه تراز می‌شوند. این گزینه اندازه آن شبکه را کنترل می‌کند.`},fsi={name:`اندازه فونت ابزارک textarea`},psi={name:`بررسی املای ابزارک textarea`},msi={name:`فاصله داخلی آیتم‌های مرورگر درختی`},hsi={name:`چیدمان نوار تب`,options:{Default:`پیش‌فرض`,Legacy:`قدیمی`},tooltip:`چیدمان نوار تب را کنترل می‌کند. «یکپارچه» کنترل‌های راهنما و کاربر را به ناحیه نوار تب منتقل می‌کند.`},gsi={name:`استفاده از منوی جدید`,options:{Disabled:`غیرفعال`,Top:`بالا`},tooltip:`فعال‌سازی نوار منوی بازطراحی‌شده بالا.`},_si={name:`اعتبارسنجی workflowها`},vsi={name:`طراحی مدرن node (Nodes 2.0)`,tooltip:`مدرن: رندر مبتنی بر DOM با تعامل‌پذیری بیشتر، ویژگی‌های بومی مرورگر و طراحی بصری به‌روز. کلاسیک: رندر سنتی مبتنی بر canvas.`},ysi={name:`حالت کنترل ابزارک`,options:{after:`بعد`,before:`قبل`},tooltip:`زمان به‌روزرسانی مقادیر ابزارک (تصادفی/افزایش/کاهش) را کنترل می‌کند؛ یا قبل از قرار گرفتن prompt در صف یا بعد از آن.`},bsi={name:`نمایش تأیید هنگام بستن پنجره`},xsi={name:`ذخیره‌سازی خودکار`,options:{"after delay":`پس از تأخیر`,off:`خاموش`}},Ssi={name:`تأخیر ذخیره‌سازی خودکار (میلی‌ثانیه)`,tooltip:`فقط زمانی اعمال می‌شود که ذخیره‌سازی خودکار روی «پس از تأخیر» تنظیم شده باشد.`},Csi={name:`نمایش تأیید هنگام حذف ورک‌فلو`},wsi={name:`بازیابی مقادیر ویجت بر اساس نام`},Tsi={name:`حفظ وضعیت ورک‌فلو و بازیابی هنگام بارگذاری (مجدد) صفحه`},Esi={name:`نمایش رسانه‌های مفقود در برگهٔ مشکلات`,tooltip:`وقتی غیرفعال باشد، تصاویر ورودی، ویدیوها و صوت‌های یافت‌نشده در برگهٔ مشکلات فهرست نمی‌شوند و nodeهای آن‌ها برجسته نمی‌شوند.`},Dsi={name:`نمایش nodeهای مفقود در برگهٔ مشکلات`,tooltip:`وقتی غیرفعال باشد، بسته‌های node مفقود در برگهٔ مشکلات فهرست نمی‌شوند و nodeهای آن‌ها برجسته نمی‌شوند. workflow همچنان تا زمان نصب آن‌ها اجرا نمی‌شود.`},Osi={name:`مرتب‌سازی شناسه نودها هنگام ذخیره ورک‌فلو`},ksi={name:`نیاز به تأیید برای بازنویسی بلوپرینت ساب‌گراف موجود`},Asi={name:`موقعیت ورک‌فلوهای باز شده`,options:{Sidebar:`نوار کناری`,Topbar:`نوار بالا`}},jsi={name:`حداکثر فریم بر ثانیه`,tooltip:`حداکثر تعداد فریم در ثانیه که بوم مجاز به رندر است. مصرف GPU را با هزینه کاهش روانی محدود می‌کند. اگر ۰ باشد، نرخ تازه‌سازی صفحه نمایش استفاده می‌شود. پیش‌فرض: ۰`},Msi={name:`آستانه اندازه فونت برای سطح جزئیات نود هنگام زوم`,tooltip:`کنترل می‌کند که نودها چه زمانی به رندر LOD با کیفیت پایین‌تر تغییر کنند. از اندازه فونت بر حسب پیکسل برای تعیین زمان تغییر استفاده می‌کند. برای غیرفعال کردن روی ۰ تنظیم کنید. مقادیر ۱ تا ۲۴ آستانه حداقل اندازه فونت برای LOD را تعیین می‌کنند - مقادیر بالاتر (۲۴ پیکسل) = تغییر سریع‌تر به رندر ساده هنگام زوم به بیرون، مقادیر پایین‌تر (۱ پیک