:`rogner`},height:{name:`hauteur`},model:{name:`modèle`},samples:{name:`échantillons`},upscale_method:{name:`méthode_d_agrandissement`},width:{name:`largeur`}},outputs:{0:{tooltip:null}}},lvi={display_name:`HunyuanVideo15SuperResolution`,inputs:{clip_vision_output:{name:`clip_vision_output`},latent:{name:`latent`},negative:{name:`négatif`},noise_augmentation:{name:`augmentation_du_bruit`},positive:{name:`positif`},start_image:{name:`image_de_départ`},vae:{name:`vae`}},outputs:{0:{name:`positif`,tooltip:null},1:{name:`négatif`,tooltip:null},2:{name:`latent`,tooltip:null}}},uvi={display_name:`HyperTile`,inputs:{max_depth:{name:`profondeur_max`},model:{name:`modèle`},scale_depth:{name:`échelle_profondeur`},swap_size:{name:`taille_échange`},tile_size:{name:`taille_tuile`}},outputs:{0:{tooltip:null}}},dvi={display_name:`HypernetworkLoader`,inputs:{hypernetwork_name:{name:`nom_hypernetwork`},model:{name:`modèle`},strength:{name:`force`}},outputs:{0:{tooltip:null}}},fvi={display_name:`Planificateur Ideogram 4`,inputs:{height:{name:`hauteur`},mu:{name:`mu`},std:{name:`écart_type`},steps:{name:`étapes`},width:{name:`largeur`}},outputs:{0:{tooltip:null}}},pvi={description:`Modifie ou combine jusqu’à 5 images selon une invite textuelle à l’aide d’Ideogram 4.5. Effectue un nouveau rendu de l’image entière et peut modifier sa taille ou son rapport largeur/hauteur\xA0; utilisez Ideogram 4.5 Modification précise pour que les pixels non modifiés restent inchangés.`,display_name:`Ideogram 4.5 Modifier`,inputs:{control_after_generate:{name:`contrôle après la génération`},model:{name:`modèle`,tooltip:`Modèle à utiliser.`},model_height:{name:`hauteur`},model_prompt:{name:`invite`},model_quality:{name:`qualité`},model_seed:{name:`graine`},model_size:{name:`taille`},model_width:{name:`largeur`}},outputs:{0:{tooltip:null}}},mvi={description:`Génère des images à l'aide de P-Image, le modèle texte-vers-image rapide d'Ideogram. Excellente typographie et photoréalisme ; prend en charge les légendes JSON structurées Ideogram 4.0 pour un texte, des couleurs et une mise en page exacts.`,display_name:`Ideogram & Pruna P-Image`,inputs:{aspect_ratio:{name:`aspect_ratio`,tooltip:`Le ratio d'aspect pour la génération d'image.`},control_after_generate:{name:`control after generate`},prompt:{name:`prompt`,tooltip:`Prompt textuel. Accepte également une légende JSON structurée Ideogram 4.0 (couleurs exactes en hexadécimal #RRGGBB, chaînes de texte exactes, mise en page par boîte englobante) — réglez prompt_upsampling sur OFF pour l'utiliser tel quel.`},prompt_upsampling:{name:`prompt_upsampling`,tooltip:`Développe les prompts courts en une légende structurée détaillée avant la génération (le prompt réécrit est renvoyé comme final_prompt). Réglez sur OFF lorsque vous fournissez votre propre légende JSON ou un texte exact.`},quality:{name:`quality`,tooltip:`Niveau de vitesse/prix/qualité. MEDIUM est le choix par défaut quotidien ; HIGH pour des prompts complexes, des détails fins et du texte difficile ; VERY_LOW/LOW pour des brouillons à grande échelle. Le texte difficile est mal rendu en dessous de MEDIUM.`},resolution:{name:`resolution`,tooltip:`Classe de taille de sortie (les pixels exacts suivent le ratio d'aspect, par exemple 16:9 donne 1280x720 en 1K et 2560x1440 en 2K). Préférez HIGH + 2K pour une typographie nette.`},seed:{name:`seed`,tooltip:`Graine pour une génération reproductible. Avec prompt_upsampling sur OFF, la même graine et les mêmes paramètres donnent la même image ; avec ON/AUTO, la réécriture du prompt varie à chaque exécution — reproduisez un résultat en réutilisant la sortie final_prompt avec prompt_upsampling sur OFF et la même graine.`}},outputs:{0:{tooltip:null},1:{name:`final_prompt`,tooltip:`Le prompt à partir duquel l'image a réellement été générée (la légende structurée réécrite si prompt_upsampling a été utilisé, sinon votre prompt). Réutilisez-le avec prompt_upsampling sur OFF et la même graine pour reproduire cette image.`}}},hvi={description:`Modifie une image selon une invite textuelle à l’aide de la modification précise d’Ideogram 4.5\xA0: seuls les éléments demandés par l’invite changent, les pixels non modifiés restent identiques et la sortie conserve la taille de l’image 1 (les images de plus de ~4 MP sont d’abord réduites). Accepte jusqu’à 4 images de référence.`,display_name:`Ideogram 4.5 Modification précise`,inputs:{control_after_generate:{name:`contrôle après la génération`},model:{name:`modèle`,tooltip:`Modèle à utiliser.`},model_prompt:{name:`invite`},model_quality:{name:`qualité`},model_seed:{name:`graine`}},outputs:{0:{tooltip:null}}},gvi={description:`Génère des images à partir d’une invite textuelle à l’aide d’Ideogram 4.5.`,display_name:`Ideogram 4.5 Texte vers image`,inputs:{control_after_generate:{name:`contrôle après génération`},model:{name:`modèle`,tooltip:`Modèle à utiliser.`},model_magic_prompt:{name:`magic_prompt`},model_prompt:{name:`prompt`},model_quality:{name:`qualité`},model_seed:{name:`graine`},model_size:{name:`taille`}},outputs:{0:{tooltip:null},1:{name:`final_prompt`,tooltip:`La légende structurée à partir de laquelle l’image a été générée. Renvoyez-la avec magic_prompt défini sur « off » et la même graine pour reproduire l’image.`}}},_vi={description:`Génère des images de façon synchrone avec le modèle Ideogram V3.

Prend en charge la génération d’images à partir de prompts textuels ainsi que l’édition d’images avec mask.
Les liens des images sont disponibles pour une durée limitée ; si vous souhaitez conserver l’image, vous devez la télécharger.`,display_name:`Ideogram V3`,inputs:{aspect_ratio:{name:`aspect_ratio`,tooltip:`Le ratio d’aspect pour la génération d’image. Ignoré si la résolution n’est pas réglée sur Auto.`},character_image:{name:`image_du_personnage`,tooltip:`Image à utiliser comme référence de personnage.`},character_mask:{name:`masque_du_personnage`,tooltip:`Masque optionnel pour l'image de référence du personnage.`},control_after_generate:{name:`control after generate`},image:{name:`image`,tooltip:`Image de référence optionnelle pour l’édition d’image.`},magic_prompt_option:{name:`magic_prompt_option`,tooltip:`Détermine si MagicPrompt doit être utilisé lors de la génération`},mask:{name:`mask`,tooltip:`Mask optionnel pour l’inpainting (les zones blanches seront remplacées)`},num_images:{name:`num_images`},prompt:{name:`prompt`,tooltip:`Prompt pour la génération ou l’édition d’image`},rendering_speed:{name:`rendering_speed`,tooltip:`Contrôle le compromis entre la vitesse de génération et la qualité`},resolution:{name:`resolution`,tooltip:`La résolution pour la génération d’image. Si elle n’est pas réglée sur Auto, cela remplace le paramètre aspect_ratio.`},seed:{name:`seed`}},outputs:{0:{tooltip:null}}},vvi={description:`Génère des images à l’aide du modèle Ideogram 4.0 à partir d’une invite textuelle.`,display_name:`Ideogram V4`,inputs:{control_after_generate:{name:`contrôle après génération`},prompt:{name:`invite`,tooltip:`Invite textuelle pour la génération d’image.`},rendering_speed:{name:`vitesse_de_rendu`,tooltip:`Contrôle le compromis entre la vitesse de génération et la qualité.`},resolution:{name:`résolution`},seed:{name:`graine`}},outputs:{0:{tooltip:null}}},yvi={display_name:`Ajout de bruit à l'image`,inputs:{control_after_generate:{name:`contrôle après génération`},image:{name:`image`},seed:{name:`graine`,tooltip:`La graine aléatoire utilisée pour créer le bruit.`},strength:{name:`intensité`}},outputs:{0:{tooltip:null}}},bvi={display_name:`Images en lot`,inputs:{image1:{name:`image1`},image2:{name:`image2`}}},xvi={display_name:`Mélange d'images`,inputs:{blend_factor:{name:`facteur_mélange`},blend_mode:{name:`mode_mélange`},image1:{name:`image1`},image2:{name:`image2`}},outputs:{0:{tooltip:null}}},Svi={display_name:`Flou d'image`,inputs:{blur_radius:{name:`rayon_flou`},image:{name:`image`},sigma:{name:`sigma`}},outputs:{0:{tooltip:null}}},Cvi={description:`Convertit sRGB, Rec.709 linéaire, HDR (Rec.2020 HLG), HDR PQ (Rec.2020 PQ), HDR LogC3 et HDR ACEScct. LogC3 utilise la courbe EI 800 avec les primaires Rec.709 et des codes limités à [0, 1]. ACEScct utilise les primaires AP1 et le point blanc D60, avec une adaptation de Bradford vers D65. Convertissez LogC3 ou ACEScct en linéaire pour l’enregistrement EXR. Le linéaire 1.0 utilise le même blanc de référence de 203 nits que sRGB ; HLG utilise un écran de référence de 1000 nits. Les sorties linéaires et ACEScct préservent les valeurs étendues. Les conversions du linéaire vers HDR préservent les hautes lumières sans mappage de tons ; les sorties HLG et PQ écrêtent les canaux négatifs. La sortie SDR et la conversion de PQ vers HLG appliquent un mappage de tons à l’excès de luminance sur l’ensemble du lot et compressent les couleurs hors gamut. Les conversions sont calculées en float32 et renvoient l’appareil intermédiaire et le dtype. L’alpha droit n’est pas transformé chromatiquement.`,display_name:`Convertir l’espace colorimétrique de l’image`,inputs:{destination:{name:`destination`,tooltip:`Espace colorimétrique des pixels de sortie. Réglez le nœud d’enregistrement sur ce même espace colorimétrique. Convertissez LogC3 ou ACEScct en linéaire avant d’enregistrer au format EXR, ou en sRGB/HDR/HDR PQ avant d’enregistrer une vidéo.`},image:{name:`image`},source:{name:`source`,tooltip:`Espace colorimétrique des pixels d’entrée.`}},outputs:{0:{tooltip:null}}},wvi={display_na