}},outputs:{0:{name:`positivo`,tooltip:null},1:{name:`latent`,tooltip:null}}},Zra={display_name:`Hunyuan Latent Refiner`,inputs:{latent:{name:`latent`},negative:{name:`negativo`},noise_augmentation:{name:`aumento del rumore`},positive:{name:`positivo`}},outputs:{0:{name:`positivo`,tooltip:null},1:{name:`negativo`,tooltip:null},2:{name:`latent`,tooltip:null}}},Qra={display_name:`HunyuanVideo15ImageToVideo`,inputs:{batch_size:{name:`dimensione batch`},clip_vision_output:{name:`clip_vision_output`},height:{name:`altezza`},length:{name:`lunghezza`},negative:{name:`negativo`},positive:{name:`positivo`},start_image:{name:`immagine iniziale`},vae:{name:`vae`},width:{name:`larghezza`}},outputs:{0:{name:`positivo`,tooltip:null},1:{name:`negativo`,tooltip:null},2:{name:`latente`,tooltip:null}}},$ra={display_name:`Upscaling latent Hunyuan Video 1.5 con modello`,inputs:{crop:{name:`ritaglio`},height:{name:`altezza`},model:{name:`modello`},samples:{name:`campioni`},upscale_method:{name:`metodo di upscaling`},width:{name:`larghezza`}},outputs:{0:{tooltip:null}}},eia={display_name:`Hunyuan Video 1.5 Super Risoluzione`,inputs:{clip_vision_output:{name:`clip_vision_output`},latent:{name:`latente`},negative:{name:`negativo`},noise_augmentation:{name:`aumento rumore`},positive:{name:`positivo`},start_image:{name:`immagine iniziale`},vae:{name:`vae`}},outputs:{0:{name:`positivo`,tooltip:null},1:{name:`negativo`,tooltip:null},2:{name:`latente`,tooltip:null}}},tia={display_name:`HyperTile`,inputs:{max_depth:{name:`profondità massima`},model:{name:`modello`},scale_depth:{name:`scala profondità`},swap_size:{name:`dimensione swap`},tile_size:{name:`dimensione tile`}},outputs:{0:{tooltip:null}}},nia={display_name:`Carica Hypernetwork`,inputs:{hypernetwork_name:{name:`nome hypernetwork`},model:{name:`modello`},strength:{name:`intensità`}},outputs:{0:{tooltip:null}}},ria={display_name:`Ideogram 4 Scheduler`,inputs:{height:{name:`altezza`},mu:{name:`mu`},std:{name:`std`},steps:{name:`passi`},width:{name:`larghezza`}},outputs:{0:{tooltip:null}}},iia={description:`Modifica o combina fino a 5 immagini, guidato da un prompt di testo, usando Ideogram 4.5. Esegue nuovamente il rendering dell'intera immagine e può modificarne la dimensione o il rapporto d'aspetto; usa Ideogram 4.5 Modifica precisa per mantenere invariati i pixel non interessati.`,display_name:`Ideogram 4.5 Modifica`,inputs:{control_after_generate:{name:`controllo dopo la generazione`},model:{name:`modello`,tooltip:`Modello da usare.`},model_height:{name:`altezza`},model_prompt:{name:`prompt`},model_quality:{name:`qualità`},model_seed:{name:`seme`},model_size:{name:`dimensione`},model_width:{name:`larghezza`}},outputs:{0:{tooltip:null}}},aia={description:`Genera immagini utilizzando P-Image, il modello text-to-image veloce di Ideogram. Tipografia avanzata e fotorealismo; supporta le didascalie strutturate JSON di Ideogram 4.0 per testo, colori e layout esatti.`,display_name:`Ideogram & Pruna P-Image`,inputs:{aspect_ratio:{name:`aspect_ratio`,tooltip:`Il rapporto d’aspetto per la generazione dell’immagine.`},control_after_generate:{name:`control after generate`},prompt:{name:`prompt`,tooltip:`Prompt testuale. Accetta anche una didascalia strutturata JSON di Ideogram 4.0 (colori esatti come esadecimali #RRGGBB, stringhe di testo esatte, layout con bounding-box) — imposta prompt_upsampling su OFF per utilizzarla letteralmente.`},prompt_upsampling:{name:`prompt_upsampling`,tooltip:`Espande prompt brevi in una didascalia strutturata dettagliata prima della generazione (il prompt riscritto viene restituito come final_prompt). Imposta su OFF quando fornisci la tua didascalia JSON o testo esatto.`},quality:{name:`quality`,tooltip:`Livello di velocità/prezzo/qualità. MEDIUM è il valore predefinito per l’uso quotidiano; HIGH per prompt complessi, dettagli fini e testo difficile; VERY_LOW/LOW per bozze su larga scala. Il testo difficile viene reso male sotto MEDIUM.`},resolution:{name:`resolution`,tooltip:`Classe di dimensione dell’output (i pixel esatti seguono il rapporto d’aspetto, ad es. 16:9 produce 1280x720 a 1K e 2560x1440 a 2K). Preferisci HIGH + 2K per una tipografia nitida.`},seed:{name:`seed`,tooltip:`Seed per una generazione riproducibile. Con prompt_upsampling su OFF, lo stesso seed e impostazioni restituiscono la stessa immagine; con ON/AUTO la riscrittura del prompt varia ad ogni esecuzione — riproduci un risultato riutilizzando il suo final_prompt con prompt_upsampling su OFF e lo stesso seed.`}},outputs:{0:{tooltip:null},1:{name:`final_prompt`,tooltip:`Il prompt da cui è stata effettivamente generata l’immagine (la didascalia strutturata riscritta se prompt_upsampling era attivo, altrimenti il tuo prompt). Riutilizzalo con prompt_upsampling su OFF e lo stesso seed per riprodurre questa immagine.`}}},oia={description:`Modifica un'immagine guidandosi con un prompt di testo usando la modifica precisa di Ideogram 4.5: cambia solo ciò che il prompt richiede, i pixel non interessati rimangono identici e l'output mantiene le dimensioni dell'immagine 1 (le immagini oltre ~4 MP vengono prima ridimensionate). Accetta fino a 4 immagini di riferimento.`,display_name:`Ideogram 4.5 Modifica precisa`,inputs:{control_after_generate:{name:`controllo dopo la generazione`},model:{name:`modello`,tooltip:`Modello da usare.`},model_prompt:{name:`prompt`},model_quality:{name:`qualità`},model_seed:{name:`seme`}},outputs:{0:{tooltip:null}}},sia={description:`Genera immagini da un prompt di testo usando Ideogram 4.5.`,display_name:`Ideogram 4.5 da testo a immagine`,inputs:{control_after_generate:{name:`controllo dopo la generazione`},model:{name:`modello`,tooltip:`Modello da usare.`},model_magic_prompt:{name:`magic_prompt`},model_prompt:{name:`prompt`},model_quality:{name:`qualità`},model_seed:{name:`seme`},model_size:{name:`dimensione`}},outputs:{0:{tooltip:null},1:{name:`final_prompt`,tooltip:`La didascalia strutturata da cui è stata generata l'immagine. Reinseriscila con magic_prompt impostato su 'off' e lo stesso seme per riprodurre l'immagine.`}}},cia={description:`Genera immagini utilizzando il modello Ideogram V3. Supporta sia la generazione di immagini da prompt testuali sia la modifica di immagini con mask.`,display_name:`Ideogram V3`,inputs:{aspect_ratio:{name:`aspect_ratio`,tooltip:`Il rapporto d’aspetto per la generazione dell’immagine. Ignorato se la risoluzione non è impostata su Auto.`},character_image:{name:`character_image`,tooltip:`Immagine da utilizzare come riferimento per il personaggio.`},character_mask:{name:`character_mask`,tooltip:`Mask opzionale per l’immagine di riferimento del personaggio.`},control_after_generate:{name:`control after generate`},image:{name:`image`,tooltip:`Immagine di riferimento opzionale per la modifica dell’immagine.`},magic_prompt_option:{name:`magic_prompt_option`,tooltip:`Determina se MagicPrompt deve essere utilizzato nella generazione`},mask:{name:`mask`,tooltip:`Mask opzionale per inpainting (le aree bianche verranno sostituite)`},num_images:{name:`num_images`},prompt:{name:`prompt`,tooltip:`Prompt per la generazione o modifica dell’immagine`},rendering_speed:{name:`rendering_speed`,tooltip:`Controlla il bilanciamento tra velocità di generazione e qualità`},resolution:{name:`resolution`,tooltip:`La risoluzione per la generazione dell’immagine. Se non impostata su Auto, questa opzione sovrascrive il parametro aspect_ratio.`},seed:{name:`seed`}},outputs:{0:{tooltip:null}}},lia={description:`Genera immagini utilizzando il modello Ideogram 4.0 da un prompt testuale.`,display_name:`Ideogram V4`,inputs:{control_after_generate:{name:`controllo dopo la generazione`},prompt:{name:`prompt`,tooltip:`Prompt testuale per la generazione dell'immagine.`},rendering_speed:{name:`velocità di rendering`,tooltip:`Controlla il compromesso tra velocità di generazione e qualità.`},resolution:{name:`risoluzione`},seed:{name:`seme`}},outputs:{0:{tooltip:null}}},uia={display_name:`Aggiungi Rumore all'Immagine`,inputs:{control_after_generate:{name:`controllo dopo la generazione`},image:{name:`immagine`},seed:{name:`seme`,tooltip:`Il seme casuale utilizzato per creare il rumore.`},strength:{name:`intensità`}},outputs:{0:{tooltip:null}}},dia={display_name:`Batch Immagini (DEPRECATO)`,inputs:{image1:{name:`immagine1`},image2:{name:`immagine2`}}},fia={display_name:`Fondi Immagini`,inputs:{blend_factor:{name:`fattore di fusione`},blend_mode:{name:`modalità di fusione`},image1:{name:`immagine1`},image2:{name:`immagine2`}},outputs:{0:{tooltip:null}}},pia={display_name:`Sfoca Immagine`,inputs:{blur_radius:{name:`raggio di sfocatura`},image:{name:`immagine`},sigma:{name:`sigma`}},outputs:{0:{tooltip:null}}},mia={description:`Converti tra sRGB, Rec.709 lineare, HDR (Rec.2020 HLG), HDR PQ (Rec.2020 PQ), HDR LogC3 e HDR ACEScct. LogC3 usa la curva EI 800 con primari Rec.709 e codici limitati a [0, 1]. ACEScct usa primari AP1 e punto di bianco D60, con adattamento Bradford a D65. Converti LogC3 o ACEScct in lineare per il salvataggio EXR. Il lineare 1.0 usa lo stesso bianco di riferimento da 203 nit di sRGB; HLG usa un display di riferimento da 1000 nit. Gli output lineari e ACEScct conservano i valori estesi. Le conversioni da lineare a HDR preservano le alte luci senza tone mapping; gli output HLG e PQ ritagliano i canali negativi. L'output SDR e la conversione da PQ a HLG applicano il tone mapping alla luminanza in eccesso nell'intero batch e comprimono i colori fuori gamut. Le conversioni vengono calcolate in float32 e restituiscono device e dtype intermedi. L'alfa non premoltiplicato non viene trasformato nello spazio colore.`,display_name:`Converti spazio colore dell'immagine`,inputs:{destination:{name:`destination`,tooltip:`Spazio colore dei pixel di output. Imposta il nodo di salvataggio sullo stesso spazio colore. Converti LogC3 o ACEScct in lineare prima di salvare in EXR, oppure in sRGB/HDR/HDR PQ prima di salvare un video.`},image:{name:`image`},source:{name:`source`,tooltip:`Spazio colore dei pixel di input.`}},outputs:{0:{tooltip:null}}},hia={display_name:`Converti Colore Immagine in Maschera`,inputs:{color:{name:`colore`},image:{name:`immagine`}},outputs:{0:{tooltip:null}}},gia={description:`Confronta due immagini affiancate con uno slider.`,display_name:`Confronta Immagini`,inputs:{compare_view:{name:`vista di confronto`},image_a:{name:`immagine_a`},image_b:{name:`immagine_b`}}},_ia={display_name:`Composizione Immagine Mascherata`,inputs:{destination:{name:`destinazione`},mask:{name:`maschera`},resize_source:{name:`ridimensiona sorgente`},source:{name:`sorgente`},x:{name:`x`},y:{name:`y`}},outputs:{0:{tooltip:null}}},via={display_name:`Crea Immagine a Livelli`,inputs:{compositor:{name:`compositor`,tooltip:`Composizione a livelli salvata dall'editor del compositore.`},layers:{name:`layers`,tooltip:`Stack di livelli da comporre; costruiscilo con Aggiungi Livello. Gli elementi sono impilati secondo z_index, i frame in batch all'interno di un elemento si espandono in livelli consecutivi, e la posizione, opacità e modalità di fusione dell'elemento definiscono la composizione iniziale. Senza una canvas del documento esplicita, la dimensione è la massima estensione possibile dei livelli posizionati. Una composizione salvata che corrisponde agli input attuali ha la priorità.`}},outputs:{0:{tooltip:`Immagine composta. Include un canale alfa quando la composizione ha aree trasparenti (ad es. sfondo nascosto), altrimenti solo RGB.`},1:{tooltip:`Trasparenza della composizione (1 = completamente trasparente). Tutti zeri quando la composizione è opaca.`}}},yia={display_name:`Ritaglia Immagine (DEPRECATO)`,inputs:{height:{name:`altezza`},image:{name:`immagine`},width:{name:`larghezza`},x:{name:`x`},y:{name:`y`}},outputs:{0:{tooltip:null}}},bia={display_name:`Ritaglia immagine in base alla maschera`,inputs:{background:{name:`sfondo`,tooltip:`Colore di sfondo dietro il soggetto mascherato.`},grow_mask:{name:`espandi_maschera`,tooltip:`Espande o 