on_output:{name:`clip_vision_output`},latent:{name:`latent`},negative:{name:`negative`},noise_augmentation:{name:`노이즈 증강`},positive:{name:`positive`},start_image:{name:`시작 이미지`},vae:{name:`vae`}},outputs:{0:{name:`positive`,tooltip:null},1:{name:`negative`,tooltip:null},2:{name:`latent`,tooltip:null}}},q$a={display_name:`하이퍼 타일`,inputs:{max_depth:{name:`최대 깊이`},model:{name:`모델`},scale_depth:{name:`스케일 깊이`},swap_size:{name:`스왑 크기`},tile_size:{name:`타일 크기`}},outputs:{0:{tooltip:null}}},J$a={display_name:`하이퍼네트워크 로드`,inputs:{hypernetwork_name:{name:`하이퍼네트워크 이름`},model:{name:`모델`},strength:{name:`강도`}},outputs:{0:{tooltip:null}}},Y$a={display_name:`Ideogram 4 스케줄러`,inputs:{height:{name:`height`},mu:{name:`mu`},std:{name:`std`},steps:{name:`steps`},width:{name:`width`}},outputs:{0:{tooltip:null}}},X$a={description:`Ideogram 4.5를 사용하여 텍스트 프롬프트의 안내에 따라 최대 5개의 이미지를 편집하거나 결합합니다. 전체 이미지를 다시 렌더링하며 크기나 가로세로비를 변경할 수 있습니다. 수정하지 않은 픽셀을 그대로 유지하려면 Ideogram 4.5 Precise Edit을 사용하세요.`,display_name:`Ideogram 4.5 편집`,inputs:{control_after_generate:{name:`생성 후 제어`},model:{name:`모델`,tooltip:`사용할 모델입니다.`},model_height:{name:`높이`},model_prompt:{name:`프롬프트`},model_quality:{name:`품질`},model_seed:{name:`시드`},model_size:{name:`크기`},model_width:{name:`너비`}},outputs:{0:{tooltip:null}}},Z$a={description:`Ideogram의 빠른 텍스트-투-이미지 모델인 P-Image를 사용하여 이미지를 생성합니다. 강력한 타이포그래피와 포토리얼리즘을 제공하며, 정확한 텍스트, 색상 및 레이아웃을 위한 Ideogram 4.0 구조화 JSON 캡션을 지원합니다.`,display_name:`Ideogram & Pruna P-Image`,inputs:{aspect_ratio:{name:`종횡비`,tooltip:`이미지 생성에 사용할 종횡비입니다.`},control_after_generate:{name:`생성 후 제어`},prompt:{name:`프롬프트`,tooltip:`텍스트 프롬프트입니다. Ideogram 4.0 구조화 JSON 캡션(정확한 색상은 #RRGGBB 헥스, 정확한 텍스트 문자열, 바운딩 박스 레이아웃)도 입력할 수 있습니다 — 이를 그대로 사용하려면 prompt_upsampling을 OFF로 설정하세요.`},prompt_upsampling:{name:`프롬프트 업샘플링`,tooltip:`생성 전에 짧은 프롬프트를 자세한 구조화 캡션으로 확장합니다(재작성된 프롬프트는 final_prompt로 반환됨). 직접 JSON 캡션이나 정확한 문구를 제공할 때는 OFF로 설정하세요.`},quality:{name:`품질`,tooltip:`속도/가격/품질 등급입니다. MEDIUM은 일상적인 기본값이며, HIGH는 복잡한 프롬프트, 세밀한 디테일 및 어려운 텍스트에 적합합니다. VERY_LOW/LOW는 대량 초안용입니다. MEDIUM 이하에서는 어려운 텍스트가 제대로 렌더링되지 않습니다.`},resolution:{name:`해상도`,tooltip:`출력 크기 클래스(정확한 픽셀은 종횡비를 따릅니다. 예: 16:9는 1K에서 1280x720, 2K에서 2560x1440). 선명한 타이포그래피에는 HIGH + 2K를 권장합니다.`},seed:{name:`시드`,tooltip:`재현 가능한 생성을 위한 시드입니다. prompt_upsampling이 OFF일 때 동일한 시드와 설정으로 동일한 이미지를 반환합니다. ON/AUTO일 때는 프롬프트 재작성 결과가 매번 달라집니다 — 결과를 재현하려면 해당 final_prompt와 동일한 시드, prompt_upsampling OFF로 다시 사용하세요.`}},outputs:{0:{tooltip:null},1:{name:`final_prompt`,tooltip:`실제로 이미지가 생성된 프롬프트(프롬프트 업샘플링이 실행된 경우 재작성된 구조화 캡션, 아니면 입력한 프롬프트). prompt_upsampling을 OFF로 하고 동일한 시드로 다시 입력하면 이 이미지를 재현할 수 있습니다.`}}},Q$a={description:`Ideogram 4.5 정밀 편집을 사용하여 텍스트 프롬프트의 안내에 따라 이미지를 편집합니다. 프롬프트에서 요청한 부분만 변경되고, 수정하지 않은 픽셀은 동일하게 유지되며 출력은 이미지 1의 크기를 유지합니다(약 4MP를 초과하는 이미지는 먼저 축소됨). 최대 4개의 참조 이미지를 허용합니다.`,display_name:`Ideogram 4.5 정밀 편집`,inputs:{control_after_generate:{name:`생성 후 제어`},model:{name:`모델`,tooltip:`사용할 모델입니다.`},model_prompt:{name:`프롬프트`},model_quality:{name:`품질`},model_seed:{name:`시드`}},outputs:{0:{tooltip:null}}},$$a={description:`Ideogram 4.5를 사용하여 텍스트 프롬프트로 이미지를 생성합니다.`,display_name:`Ideogram 4.5 텍스트-이미지`,inputs:{control_after_generate:{name:`생성 후 제어`},model:{name:`모델`,tooltip:`사용할 모델입니다.`},model_magic_prompt:{name:`magic_prompt`},model_prompt:{name:`프롬프트`},model_quality:{name:`품질`},model_seed:{name:`시드`},model_size:{name:`크기`}},outputs:{0:{tooltip:null},1:{name:`최종 프롬프트`,tooltip:`이미지가 생성된 기반이 되는 구조화된 캡션입니다. magic_prompt를 'off'로 설정하고 동일한 시드와 함께 다시 입력하면 이미지를 재현할 수 있습니다.`}}},e1a={description:`Ideogram V3 모델을 사용하여 동기적으로 이미지를 생성합니다.

