ooltip:`Unidade de saída do FOV.`}},outputs:{0:{name:`fov`,tooltip:null},1:{name:`focal_pixels`,tooltip:null}}},Kvo={description:`Execute o MoGe em uma única imagem para estimar profundidade e geometria.`,display_name:`Inferência MoGe`,inputs:{apply_mask:{name:`apply_mask`,tooltip:`Define pixels mascarados (céu/inválidos) como inf em pontos e profundidade para que a malha os descarte. Desative para manter a geometria prevista bruta em todo lugar; a máscara ainda é retornada separadamente.`},batch_size:{name:`batch_size`,tooltip:`Imagens por chamada de inferência. Reduza se ocorrer OOM em um vídeo longo/conjunto de imagens.`},force_projection:{name:`force_projection`},fov_x_degrees:{name:`fov_x_degrees`,tooltip:`Campo de visão horizontal da câmera de origem. Define a distância focal usada para desprojetar o mapa de profundidade em 3D. 0 = recuperar automaticamente dos pontos previstos.`},image:{name:`image`},moge_model:{name:`moge_model`},refine_steps:{name:`refine_steps`,tooltip:`Somente MoGe-3: passagens esparsas de refinamento volumétrico sobre a profundidade prevista. Mais passagens aprimoram detalhes finos e bordas com um custo aproximadamente linear. 0 desativa o refinamento. Ignorado por MoGe-1 / MoGe-2.`},resolution_level:{name:`resolution_level`,tooltip:`0 = mais rápido, 9 = mais detalhado.`}},outputs:{0:{name:`moge_geometry`,tooltip:null}}},qvo={description:`Execute o MoGe em uma panorâmica equiretangular dividindo-a em 12 vistas em perspectiva, realizando inferência em cada uma e mesclando os resultados em um único mapa de profundidade.`,display_name:`Inferência Panorama MoGe`,inputs:{batch_size:{name:`batch_size`,tooltip:`Visualizações por lote de inferência (12 divisões no total).`},image:{name:`image`,tooltip:`Panorama equiretangular (qualquer proporção).`},merge_resolution:{name:`merge_resolution`,tooltip:`Resolução do lado maior do mapa de distância equiretangular mesclado.`},moge_model:{name:`moge_model`},refine_steps:{name:`refine_steps`,tooltip:`So