tip:null}}},Yzo={display_name:`Партия изображений`,inputs:{image1:{name:`изображение1`},image2:{name:`изображение2`}}},Xzo={display_name:`Смешивание изображений`,inputs:{blend_factor:{name:`фактор_смешивания`},blend_mode:{name:`режим_смешивания`},image1:{name:`изображение1`},image2:{name:`изображение2`}},outputs:{0:{tooltip:null}}},Zzo={display_name:`Размытие изображения`,inputs:{blur_radius:{name:`радиус_размытия`},image:{name:`изображение`},sigma:{name:`сигма`}},outputs:{0:{tooltip:null}}},Qzo={description:`Преобразует sRGB, линейный Rec.709, HDR (Rec.2020 HLG), HDR PQ (Rec.2020 PQ), HDR LogC3 и HDR ACEScct. LogC3 использует кривую EI 800 с первичными цветами Rec.709, а значения кодов ограничиваются диапазоном [0, 1]. ACEScct использует первичные цвета AP1 и белую точку D60 с адаптацией Брэдфорда к D65. Для сохранения в EXR преобразуйте LogC3 или ACEScct в линейное пространство. Линейное 1.0 использует ту же опорную точку белого 203 нит, что и sRGB; HLG использует эталонный дисплей яркостью 1000 нит. Выходы Linear и ACEScct сохраняют расширенные значения. Преобразования из линейного пространства в HDR сохраняют светлые участки без тонального отображения; выходы HLG и PQ отсекают отрицательные каналы. Вывод SDR и преобразование PQ в HLG выполняют тональное отображение избыточной яркости для всего пакета и сжимают цвета вне цветового охвата. Преобразования вычисляются в float32 и возвращают промежуточные device и dtype. Прямой альфа-канал не подвергается цветовому преобразованию.`,display_name:`Преобразовать цветовое пространство изображения`,inputs:{destination:{name:`destination`,tooltip:`Цветовое пространство выходных пикселей. Установите в узле сохранения то же цветовое пространство. Перед сохранением EXR преобразуйте LogC3 или ACEScct в линейное пространство, а перед сохранением видео — в sRGB/HDR/HDR PQ.`},image:{name:`image`},source:{name:`source`,tooltip:`Цветовое пространство входных пикселей.`}},outputs:{0:{tooltip:null}}},$zo={display_name:`Цвет изображения в маску`,inputs:{color:{name:`цвет`},image:{name:`изображение`}},outputs:{0:{tooltip:null}}},eBo={description:`Сравнивает два изображения бок о бок с помощью ползунка.`,display_name:`Сравнение изображений`,inputs:{compare_view:{name:`compare_view`},image_a:{name:`image_a`},image_b:{name:`image_b`}}},tBo={display_name:`Составное изображение с маской`,inputs:{destination:{name:`назначение`},mask:{name:`маска`},resize_source:{name:`изменить_размер_источника`},source:{name:`источник`},x:{name:`x`},y:{name:`y`}},outputs:{0:{tooltip:null}}},nBo={display_name:`Создать многослойное изображение`,inputs:{compositor:{name:`композитор`,tooltip:`Многослойная композиция, сохранённая редактором композитора.`},layers:{name:`слои`,tooltip:`Стек слоёв для компоновки; создайте его с помощью Add Layer. Элементы располагаются по z_index, кадры батча внутри элемента разворачиваются в последовательные слои, а размещение, непрозрачность и режим наложения элемента определяют начальную композицию. Без явного холста документа размер определяется как максимально возможный по размещённым слоям. Сохранённая композиция, совпадающая с текущими входными данными, имеет приоритет.`}},outputs:{0:{tooltip:`Скомпонованное изображение. Содержит альфа-канал, если в композиции есть прозрачные области (например, скрытый фон), иначе обычный RGB.`},1:{tooltip:`Прозрачность композиции (1 = полностью прозрачно). Все нули, если композиция непрозрачна.`}}},rBo={display_name:`Обрезка изображения`,inputs:{height:{name:`высота`},image:{name:`изображение`},width:{name:`ширина`},x:{name:`x`},y:{name:`y`}},outputs:{0:{tooltip:null}}},iBo={display_name:`Обрезать изображение по маске`,inputs:{background:{name:`фон`,tooltip:`Цвет фона за объектом, выделенным маской.`},grow_mask:{name:`grow_mask`,tooltip:`Расширяет или сужает маску на указанное количество пикселей перед обрезкой.`},height:{name:`высота`,tooltip:`Высота вывода в пикселях.`},images:{name:`изображения`},masks:{name:`маски`},pad_factor:{name:`pad_factor`,to