olycount:{name:`target_polycount`},should_remesh_topology:{name:`topology`},style:{name:`style`},symmetry_mode:{name:`symmetry_mode`},ultra_mode:{name:`ультра-режим`,tooltip:`Выполняет дополнительный проход уточнения для более точной геометрии с более мелкими деталями поверхности.`},ultra_resolution:{name:`ultra_resolution`,tooltip:`Разрешение ultra-прохода: 2k запускает его при 2048³, 4k — при 4096³ для максимальной детализации поверхности. Для 4k требуется meshy-7.1 или новее. Используется только при включённом ultra_mode.`}},outputs:{0:{name:`файл модели`,tooltip:null},1:{name:`meshy_task_id`,tooltip:null},2:{name:`GLB`,tooltip:null},3:{name:`FBX`,tooltip:null}}},CUo={description:`Текстурирует ранее созданную модель, используя от 1 до 4 референсных ракурсов одного объекта.`,display_name:`Meshy: Текстурировать модель (мультиракурс)`,inputs:{enable_original_uv:{name:`использовать исходные UV`,tooltip:`Использует исходные UV модели вместо создания новых UV. При включении Meshy сохраняет существующие текстуры загруженной модели. Если у модели нет исходных UV, качество результата может быть ниже.`},meshy_task_id:{name:`ID задачи Meshy`},model:{name:`модель`},multiview_images:{name:`многовидовые изображения`,tooltip:`Референсные ракурсы одного объекта. Первое изображение — основной (фронтальный) ракурс; порядок остальных ракурсов не важен.`},pbr:{name:`PBR`},texture_resolution:{name:`разрешение текстуры`,tooltip:`Разрешение текстуры базового цвета. Более высокие разрешения передают больше деталей поверхности.`}},outputs:{0:{name:`файл модели`,tooltip:null},1:{name:`ID задачи Meshy`,tooltip:null},2:{name:`GLB`,tooltip:null},3:{name:`FBX`,tooltip:null}}},wUo={display_name:`Meshy: Модель текстуры`,inputs:{enable_original_uv:{name:`enable_original_uv`,tooltip:`Использовать оригинальные UV модели вместо генерации новых UV. При включении Meshy сохраняет существующие текстуры из загруженной модели. Если у модели нет оригинальных UV, качество результата может быть ниже.`},image_style:{name:`image_style`,tooltip:`2D-изображение для направления процесса текстурирования. Нельзя использовать одновременно с 'text_style_prompt'.`},meshy_task_id:{name:`meshy_task_id`},model:{name:`model`},pbr:{name:`pbr`},text_style_prompt:{name:`text_style_prompt`,tooltip:`Опишите желаемый стиль текстуры объекта с помощью текста. Максимум 600 символов. Нельзя использовать одновременно с 'image_style'.`},texture_resolution:{name:`разрешение текстуры`,tooltip:`Разрешение текстуры базового цвета. Более высокие разрешения передают больше деталей поверхности.`}},outputs:{0:{name:`файл модели`,tooltip:null},1:{name:`meshy_task_id`,tooltip:null},2:{name:`GLB`,tooltip:null},3:{name:`FBX`,tooltip:null}}},TUo={description:`Редактирует или объединяет до 10 эталонных изображений по текстовому запросу с помощью модели Muse Image от Meta.`,display_name:`Meta Muse Image: Редактирование`,inputs:{control_after_generate:{name:`control after generate`},model:{name:`model`,tooltip:`Используемая модель.`},model_aspect_ratio:{name:`aspect_ratio`},model_enable_image_search:{name:`enable_image_search`},model_enable_shell:{name:`enable_shell`},model_enable_web_search:{name:`enable_web_search`},model_prompt:{name:`prompt`},model_reasoning_strength:{name:`reasoning_strength`},model_seed:{name:`seed`}},outputs:{0:{tooltip:null}}},EUo={description:`Генерирует изображения по текстовому запросу с помощью модели Muse Image от Meta, которая анализирует запрос перед рендерингом.`,display_name:`Meta Muse Image: Текст в изображение`,inputs:{control_after_generate:{name:`control after generate`},model:{name:`model`,tooltip:`Используемая модель.`},model_aspect_ratio:{name:`aspect_ratio`},model_enable_image_search:{name:`enable_image_search`},model_enable_shell:{name:`enable_shell`},model_enable_web_search:{name:`enable_web_search`},model_prompt:{name:`prompt`},model_reasoning_strength:{name:`reasoning_strength`},model_seed:{name:`seed`}},outputs:{0:{tooltip:null}}},DUo={description:`Закрепляет изображение, короткий clip, аудио или clip со звуковой дорожкой на любом кадре видео MiniMax H3. Соедините несколько узлов, чтобы закрепить несколько кадров.`,display_name:`Добавить направляющую для MiniMax H3`,inputs:{audio:{name:`audio`,tooltip:`Звуковая дорожка для привязки, начиная с того же индекса кадра; обрезается до оставшейся длительности видео.`},audio_vae:{name:`audio_vae`,tooltip:`Аудио VAE, требуется при подключении аудио.`},frame_idx:{name:`frame_idx`,tooltip:`Индекс кадра, к которому будет привязано изображение или первый кадр clip. Отрицательные значения отсчитываются от конца видео.`},image:{name:`image`,tooltip:`Изображение или кадры видео для привязки. Пакеты из нескольких кадров привязываются как clip и обрезаются до допустимой для модели длины clip: 5, 22, 39... (17k + 5) кадров. Для пакетов короче 5 кадров используется только первое изображение.`},latent:{name:`латентный`},positive:{name:`позитивный`},vae:{name:`vae`,tooltip:`Видео VAE, требуется при подключении изображения.`}},outputs:{0:{name:`positive`,tooltip:null}}},OUo={description:`Применяет MiniMax H3 Fun ControlNet к модели преобразования текста в видео в качестве патча модели.`,display_name:`Применить MiniMax H3 Fun ControlNet`,inputs:{control_video:{name:`control_video`},end_percent:{name:`end_percent`},mask:{name:`mask`,tooltip:`1 отмечает области для регенерации.`},model:{name:`model`},model_patch:{name:`model_patch`},source_video:{name:`source_video`,tooltip:`Видео под маской; считывается только при наличии маски.`},start_percent:{name:`start_percent`},strength:{name:`strength`},vae:{name:`vae`}},outputs:{0:{tooltip:null}}},kUo={display_name:`MiniMax H3: изображение в видео`,inputs:{clip:{name:`clip`},first_frame:{name:`первый_кадр`},height:{name:`высота`},last_frame:{name:`последний_кадр`},length:{name:`длина`,tooltip:`Количество кадров при 24 кадрах/с, округляется вверх до сетки модели 17k+5 (124 = ~5с; обученный диапазон ~124-362, больше — не тестировалось)`},prompt:{name:`prompt`