rning:()=>Z$o,Comfy_Workflow_SortNodeIdOnSave:()=>Q$o,Comfy_Workflow_WarnBlueprintOverwrite:()=>$$o,Comfy_Workflow_WorkflowTabsPosition:()=>e1o,LiteGraph_Canvas_MaximumFps:()=>t1o,LiteGraph_Canvas_MinFontSizeForLOD:()=>n1o,LiteGraph_ContextMenu_Scaling:()=>r1o,LiteGraph_Group_SelectChildrenOnClick:()=>i1o,LiteGraph_Node_DefaultPadding:()=>a1o,LiteGraph_Node_TooltipDelay:()=>o1o,LiteGraph_Reroute_SplineOffset:()=>s1o,default:()=>l1o,pysssss_SnapToGrid:()=>c1o}),lQo,uQo,dQo,fQo,pQo,mQo,hQo,gQo,_Qo,vQo,yQo,bQo,xQo,SQo,CQo,wQo,TQo,EQo,DQo,OQo,kQo,AQo,jQo,MQo,NQo,PQo,FQo,IQo,LQo,RQo,zQo,BQo,VQo,HQo,UQo,WQo,GQo,KQo,qQo,JQo,YQo,XQo,ZQo,QQo,$Qo,e$o,t$o,n$o,r$o,i$o,a$o,o$o,s$o,c$o,l$o,u$o,d$o,f$o,p$o,m$o,h$o,g$o,_$o,v$o,y$o,b$o,x$o,S$o,C$o,w$o,T$o,E$o,D$o,O$o,k$o,A$o,j$o,M$o,N$o,P$o,F$o,I$o,L$o,R$o,z$o,B$o,V$o,H$o,U$o,W$o,G$o,K$o,q$o,J$o,Y$o,X$o,Z$o,Q$o,$$o,e1o,t1o,n1o,r1o,i1o,a1o,o1o,s1o,c1o,l1o,u1o=t((()=>{lQo={name:`Отключить анимации`,tooltip:`Отключает большинство CSS-анимаций и переходов. Ускоряет инференс, если видеокарта используется также для генерации.`},uQo={name:`Фоновое изображение холста`,tooltip:`URL изображения для фона холста. Вы можете кликнуть правой кнопкой мыши на изображении в панели результатов и выбрать «Установить как фон», чтобы использовать его.`},dQo={name:`Поведение при клике левой кнопкой мыши`,options:{Panning:`Перемещение`,Select:`Выбрать`}},fQo={name:`Прокрутка колесиком мыши`,options:{Panning:`Перемещение`,"Zoom in/out":`Приближение/отдаление`}},pQo={name:`Режим навигации по холсту`,options:{Custom:`Пользовательское`,"Drag Navigation":`Перетаскивание`,"Standard (New)":`Стандартный (новый)`}},mQo={name:`Показать панель инструментов выбора`,tooltip:`Отображает плавающую панель инструментов при выборе узлов, предоставляя быстрый доступ к основным действиям.`},hQo={name:`Требовать подтверждение при очистке рабочего процесса`},gQo={name:`Включить обрезку элементов DOM (включение может снизить производительность)`},_Qo={name:`Включить параметры режима разработчика (сохранение API и т. д.)`},vQo={name:`Отключить округление по умолчанию для плавающих виджетов.`,tooltip:`(требуется перезагрузка страницы) Невозможно отключить округление, если оно установлено узлом на сервере.`},yQo={name:`Отключить ползунки виджетов нод`},bQo={name:`Точность Ctrl+вверх/вниз`},xQo={name:`Включить подсказки`},SQo={name:`Сохранять и восстанавливать положение и уровень масштабирования холста в рабочих процессах`},CQo={name:`Показывать отсутствующие модели на вкладке проблем`,tooltip:`Если отключено, не найденные файлы моделей не отображаются на вкладке проблем, а их узлы не выделяются.`},wQo={name:`Метод живого предпросмотра`,options:{auto:`auto`,default:`default`,latent2rgb:`latent2rgb`,none:`none`,taesd:`taesd`},tooltip:`Метод живого предпросмотра во время генерации изображения. «default» использует настройку CLI сервера.`},TQo={name:`Количество знаков после запятой для округления плавающего виджета [0 = авто].`,tooltip:`(требуется перезагрузка страницы)`},EQo={name:`Скорость автопрокрутки`,tooltip:`Максимальная скорость автопрокрутки при перетаскивании к краю холста. Установите 0 для отключения автопрокрутки.`},DQo={name:`Показать информацию о холсте в нижнем левом углу (fps и т.д.)`},OQo={name:`Показать меню холста графа`},kQo={name:`Включить быстрый зум с помощью сочетания клавиш (Ctrl + Shift + Колёсико мыши)`},AQo={name:`Удалить дубликаты идентификаторов узлов подграфа`,tooltip:`Автоматически переназначать повторяющиеся идентификаторы узлов в подграфах при загрузке рабочего процесса.`},jQo={name:`Маркер середины ссылки`,options:{Arrow:`Стрелка`,Circle:`Круг`,None:`Нет`}},MQo={name:`Живое выделение`,tooltip:`Если включено, узлы выделяются/снимаются в реальном времени при перетаскивании прямоугольника выделения, как в других графических редакторах.`},NQo={name:`Скорость зума холста`},PQo={name:`Отступ для выбранных нод группы`},FQo={name:`Дважды щёлкните по заголовку группы, чтобы редактировать`},IQo={name:`Действие при отпускании ссылки (без модификатора)`,options:{"context menu":`контекстное меню`,"no action":`без действия`,"search box":`поисковая строка`}},LQo={name:`Действие при отпускании ссылки (Shift)`,options:{"context menu":`контекстное меню`,"no action":`без действия`,"search box":`поисковая строка`}},RQo={name:`Режим рендеринга ссылки`,options:{Hidden:`Скрытый`,Linear:`Линейный`,Spline:`Сплайн`,Straight:`Прямой`},tooltip:`Управляет внешним видом и видимостью соединительных линий между узлами на холсте.`},zQo={name:`Включить 3D просмотрщик (Бета)`,tooltip:`Включает 3D просмотрщик (Бета) для выбранных узлов. Эта функция позволяет визуализировать и взаимодействовать с 3D моделями прямо во встроенном полноразмерном 3D просмотрщике.`},BQo={name:`Начальный цвет фона`,tooltip:`Управляет цветом фона по умолчанию для 3D сцены. Эта настройка определяет внешний вид фона при создании нового 3D виджета, но может быть изменена индивидуально для каждого виджета после создания.`},VQo={name:`Начальный тип камеры`,options:{orthographic:`ортографическая`,perspective:`перспективная`},tooltip:`Определяет, будет ли камера по умолчанию перспективной или ортографической при создании нового 3D виджета. Этот параметр можно изменить индивидуально для каждого виджета после создания.`},HQo={name:`Шаг регулировки освещения`,tooltip:`Определяет размер шага при изменении интенсивности освещения в 3D сценах. Меньшее значение позволяет более точно настраивать освещение, а большее — приводит к более заметным изменениям при каждом шаге.`},UQo={name:`Начальная интенсивность освещения`,tooltip:`Устанавливает уровень яркости освещения по умолчанию в 3D сцене. Это значение определяет, насколько ярко свет освещает объекты при создании нового 3D виджета, но может быть изменено индивидуально для каждого виджета после создания.`},WQo={name:`Максимальная интенсивность освещения`,tooltip:`Устанавливает максимальное допустимое значение интенсивности освещения для 3D сцен. Это определяет верхний предел яркости, который можно установить при настройке освещения в любом 3D виджете.`},GQo={name:`Минимальная интенсивность освещения`,tooltip:`Устанавливает минимальное допустимое значение интенсивности освещения для 3D сцен. Это определяет нижний предел яркости, который можно установить при настройке освещения в любом 3D виджете.`},KQo={name:`Движок PLY`,options:{fastply:`fastply`,threejs:`threejs`},tooltip:`Выберите движок для загрузки PLY файлов. "threejs" использует встроенный загрузчик Three.js PLYLoader (лучше всего подходит для файлов сетки PLY). "fastply" использует оптимизированный загрузчик для ASCII PLY файлов облака точек. "sparkjs" использует Spark.js для PLY файлов с 3D Gaussian Splatting.`},qQo={name:`Начальная видимость сетки`,tooltip:`Определяет, будет ли сетка видимой по умолчанию при создании нового 3D виджета. Этот параметр можно изменить индивидуально для каждого виджета после создания.`},JQo={name:`Язык`},YQo={name:`Множитель скорости регулировки кисти`,tooltip:`Управляет тем, как быстро изменяются размер и жёсткость кисти при регулировке. Более высокие значения означают более быстрые изменения.`},XQo={name:`Закрепить регулировку кисти по доминирующей оси`,tooltip:`При включении регулировки кисти будет влиять только на размер или жёсткость в зависимости от того, в каком направлении вы двигаетесь больше`},ZQo={name:`Автоматически загружать все папки моделей`,tooltip:`Если true, все папки будут загружены, как только вы откроете библиотеку моделей (это может вызвать задержки при загрузке). Если false, корневые папки моделей будут загружены только после нажатия на них.`},QQo={name:`Какое название отображать в древовидном представлении библиотеки моделей`,options:{filename:`название файла`,title:`название`},tooltip:`Выберите "название файла", чтобы отобразить упрощённый вид сырого названия файла (без директории или расширения ".safetensors") в списке моделей. Выберите "название", чтобы отобразить настраиваемое название метаданных модели.`},$Qo={name:`Режим значка ID ноды`,options:{None:`Нет`,"Show all":`Показать все`}},e$o={name:`Режим значка жизненного цикла ноды`,options:{None:`Нет`,"Show all":`Показать все`}},t$o={name:`Режим значка источника ноды`,options:{"Hide built-in":`Скрыть встроенные`,None:`Нет`,"Show all":`Показать все`}},n$o={name:`Показать значок стоимости узла API`},r$o={name:`Новый дизайн библиотеки узлов`,tooltip:`Включить обновлённую боковую панель библиотеки узлов с вкладками (Основные, Все, Пользовательские), улучшенным поиском и предварительным просмотром при наведении.`},i$o={name:`Включить автоматическую замену узлов`,tooltip:`Если включено, отсутствующие узлы могут быть автоматически заменены их новыми эквивалентами, если существует соответствие для замены.`},a$o={name:`Реализация поискового поля нод`,options:{default:`по умолчанию`,"litegraph (legacy)":`litegraph (устаревший)`,"v1 (legacy)":`v1 (устаревший)`}},o$o={name:`Добавленные узлы следуют за курсором`,tooltip:`Если включено, узлы, добавленные из поискового окна, будут следовать за курсором до тех пор, пока не будут размещены щелчком. Применяется только к реализации по умолчанию.`},s$o={name:`Предварительный просмотр ноды`,tooltip:`Применяется только к стандартной реализации`},c$o={name:`Показать категорию ноды в результатах поиска`,tooltip:`Применяется только к стандартной реализации`},l$o={name:`Показать название ID ноды в результатах поиска`,tooltip:`Применяется только к стандартной реализации`},u$o={name:`Показать частоту ноды в результатах поиска`,tooltip:`Применяется только к стандартной реализации`},d$o={name:`Количество предложенных нод`,tooltip:`Только для поля поиска litegraph/контекстного меню`},f$o={name:`Показывать ширину × высоту под предварительным просмотром изображения`},p$o={name:`Всегда показывать расширенные виджеты на всех узлах`,tooltip:`Если включено, расширенные виджеты всегда видны на всех узлах без необходимости раскрывать их по отдельности.`},m$o={name:`Автоматически привязывать ссылку к слоту ноды`,tooltip:`При перетаскивании ссылки над нодой ссылка автоматически привязывается к подходящему входному слоту ноды`},h$o={name:`Сохранить все ссылки при удалении нод`,tooltip:`При удалении ноды попытаться переподключить все её входные и выходные ссылки (обходя удалённую ноду)`},g$o={name:`Дважды щёлкните по заголовку ноды, чтобы редактировать`},_$o={name:`Средний щелчок создаёт новую ноду перенаправления`},v$o={name:`Непрозрачность ноды`},y$o={name:`Показать устаревшие ноды в поиске`,tooltip:`Устаревшие ноды по умолчанию скрыты в интерфейсе, но остаются функциональными в существующих рабочих процессах, которые их используют.`},b$o={name:`Показать экспериментальные ноды в поиске`,tooltip:`Экспериментальные ноды помечены как таковые в интерфейсе и могут подвергаться значительным изменениям или удалению в будущих версиях. Используйте с осторожностью в производственных рабочих процессах`},x$o={name:`Подсветка ноды при привязке`,tooltip:`При перетаскивании ссылки над нодой с подходящим входным слотом, нода подсвечивается`},S$o={name:`Показывать обновления версий`,tooltip:`Показывать обновления новых моделей и основные новые функции.`},C$o={name:`Дрейф щелчка указателя (максимальное расстояние)`,tooltip:`Если указатель перемещается более чем на это расстояние, удерживая кнопку, это считается перетаскиванием (а не щелчком).

Помогает предотвратить непреднамеренное смещение объектов, если указатель перемещается во время щелчка.`},w$o={name:`Интервал двойного щелчка (максимум)`,tooltip:`Максимальное время в миллисекундах между двумя щелчками двойного щелчка. Увеличение этого значения может помочь, если двойные щелчки иногда не регистрируются.`},T$o={name:`Формат изображения предварительного просмотра`,tooltip:`При отображении предварительного просмотра в виджете изображения, преобразуйте его в легковесное изображение, например, webp, jpeg, webp;50 и т.д.`},E$o={name:`Запрос названия файла при сохранении рабочего процесса`},D$o={name:`Ограничение количества партий`,tooltip:`Максимальное количество задач, добавляемых в очередь за одно нажатие кнопки`},O$o={name:`Размер истории очереди`,tooltip:`Максимальное количество задач, отображаемых в истории очереди.`},k$o={name:`Использовать объединённую очередь заданий в боковой панели ресурсов`,tooltip:`Заменяет плавающую панель очереди заданий на аналогичную очередь, встроенную в боковую панель ресурсов. Вы можете отключить эту опцию, чтобы вернуться к плавающей панели.`},A$o={name:`Показывать вкладку проблем на боковой панели`,tooltip:`Когда включено, на правой боковой панели отображается вкладка «Проблемы», где показаны блокирующие ошибки и отсутствующие ресурсы, требующие настройки.`},j$o={name:`Расположение боковой панели`,options:{left:`слева`,right:`справа`}},M$o={name:`Размер боковой панели`,options:{normal:`нормальный`,small:`маленький`}},N$o={name:`Стиль боковой панели`,options:{connected:`прикреплённая`,floating:`плавающая`}},P$o={name:`Унифицированная ширина боковой панели`},F$o={name:`Размер сетки привязки`,tooltip:`При перетаскивании и изменении размера нод, удерживая shift, они будут выровнены по сетке, это контролирует размер этой сетки.`},I$o={name:`Размер шрифта виджета текстовой области`},L$o={name:`Проверка орфографии виджета текстовой области`},R$o={name:`Отступ элемента в проводнике дерева`},z$o={name:`Макет панели вкладок`,options:{Default:`По умолчанию`,Legacy:`Классический`},tooltip:`Управляет расположением панели вкладок. «Интегрированный» перемещает элементы управления Справкой и Пользователем в область панели вкладок.`},B$o={name:`Использовать новое меню`,options:{Disabled:`Отключено`,Top:`Вверху`},tooltip:`Расположение панели меню. На мобильных устройствах меню всегда отображается вверху.`},V$o={name:`Проверка рабочих процессов`},H$o={name:`Современный дизайн узлов (Vue узлы)`,tooltip:`Современный: DOM-рендеринг с улучшенной интерактивностью, нативными функциями браузера и обновлённым визуальным дизайном. Классический: Традиционный рендеринг на холсте.`},U$o={name:`Режим управления виджетом`,options:{after:`после`,before:`до`},tooltip:`Управляет тем, когда обновляются значения виджета (случайные/увеличение/уменьшение), либо до того, как запрос будет поставлен в очередь, либо после.`},W$o={name:`Показать подтверждение при закрытии окна`},G$o={name:`Автосохранение`,options:{"after delay":`после задержки`,off:`выключено`}},K$o={name:`Задержка автосохранения (мс)`,tooltip:`Применяется только если автосохранение установлено на "после задержки".`},q$o={name:`Показать подтверждение при удалении рабочих процессов`},J$o={name:`Восстановить значения виджетов по имени`},Y$o={name:`Сохранить состояние рабочего процесса и восстановить при (пере)загрузке страницы`},X$o={name:`Показывать отсутствующие медиафайлы на вкладке проблем`,tooltip:`Если отключено, не найденные входные изображения, видео и аудио не отображаются на вкладке проблем, а их узлы не выделяются.`},Z$o={name:`Показывать отсутствующие узлы на вкладке проблем`,tooltip:`Если отключено, отсутствующие пакеты узлов не отображаются на вкладке проблем, а их узлы не выделяются. Рабочий процесс всё равно нельзя запустить, пока они не будут установлены.`},Q$o={name:`Сортировать ID нод при сохранении рабочего процесса`},$$o={name:`Требовать подтверждение для перезаписи существующего шаблона подграфа`},e1o={name:`Положение открытых рабочих процессов`,options:{Sidebar:`Боковая панель`,Topbar:`Верхняя панель`}},t1o={name:`Максимум FPS`,tooltip:`Максимальное количество кадров в секунду, которое холст может рендерить. Ограничивает использование GPU за счёт плавности. Если 0, используется частота обновления экрана. По умолчанию: 0`},n1o={name:`Порог размера шрифта для уровня детализации ноды при масштабировании`,tooltip:`Управляет переключением нод на рендеринг с низким уровнем детализации. Использует размер шрифта в пикселях для определения момента переключения. Установите 0 для отключения. Значения 1-24 задают минимальный порог размера шрифта для уровня детализации - более высокие значения (24px) = переключение нод на упрощённый рендеринг раньше при уменьшении масштаба, более низкие значения (1px) = сохранение полного качества ноды дольше.`},r1o={name:`Масштабирование комбинированных виджетов меню узлов (списков) при увеличении`},i1o={name:`Выделять дочерние элементы группы при клике`,tooltip:`Если включено, при нажатии на группу будут выделены все узлы и элементы внутри неё`},a1o={name:`Всегда сжимать новые узлы`,tooltip:`Изменять размер узлов до минимально возможного при создании. Если отключено, новый узел будет немного расширен для отображения значений виджетов.`},o1o={name:`Задержка всплывающей подсказки`},s1o={name:`Перераспределение смещения сплайна`,tooltip:`Смещение контрольной точки Безье от центральной точки перераспределения`},c1o={name:`Всегда привязываться к сетке`,tooltip:`Если включено, узлы будут автоматически выравниваться по сетке при перемещении или изменении размера.`},l1o={"Comfy-Desktop_AutoUpdate":{name:`Автоматически проверять обновления`},"Comfy-Desktop_SendStatistics":{name:`Отправлять анонимную статистику использования`},"Comfy-Desktop_UV_PypiInstallMirror":{name:`Pypi Установить Зеркало`,tooltip:`Зеркало установки pip по умолчанию`},"Comfy-Desktop_UV_PythonInstallMirror":{name:`Зеркало для установки Python`,tooltip:`Управляемые установки Python загружаются из проекта Astral python-build-standalone. Эта переменная может быть установлена на URL-адрес зеркала для использования другого источника для установок Python. Предоставленный URL заменит https://github.com/astral-sh/python-build-standalone/releases/download в, например, https://github.com/astral-sh/python-build-standalone/releases/download/20240713/cpython-3.12.4%2B20240713-aarch64-apple-darwin-install_only.tar.gz. Дистрибутивы могут быть прочитаны из локального каталога, используя схему URL file://.`},"Comfy-Desktop_UV_TorchInstallMirror":{name:`Установочное Зеркало Torch`,tooltip:`Зеркало для установки pip для pytorch`},"Comfy-Desktop_WindowStyle":{name:`Стиль окна`,options:{custom:`пользовательский`,default:`по умолчанию`},tooltip:`Выберите пользовательский вариант, чтобы скрыть системную строку заголовка`},Comfy_Appearance_DisableAnimations:lQo,Comfy_Canvas_BackgroundImage:uQo,Comfy_Canvas_LeftMouseClickBehavior:dQo,Comfy_Canvas_MouseWheelScroll:fQo,Comfy_Canvas_NavigationMode:pQo,Comfy_Canvas_SelectionToolbox:mQo,Comfy_ConfirmClear:hQo,Comfy_DOMClippingEnabled:gQo,Comfy_DevMode:_Qo,Comfy_DisableFloatRounding:vQo,Comfy_DisableSliders:yQo,Comfy_EditAttention_Delta:bQo,Comfy_EnableTooltips:xQo,Comfy_EnableWorkflowViewRestore:SQo,Comfy_ErrorSystem_ShowMissingModels:CQo,Comfy_Execution_PreviewMethod:wQo,Comfy_FloatRoundingPrecision:TQo,Comfy_Graph_AutoPanSpeed:EQo,Comfy_Graph_CanvasInfo:DQo,Comfy_Graph_CanvasMenu:OQo,Comfy_Graph_CtrlShiftZoom:kQo,Comfy_Graph_DeduplicateSubgraphNodeIds:AQo,Comfy_Graph_LinkMarkers:jQo,Comfy_Graph_LiveSelection:MQo,Comfy_Graph_ZoomSpeed:NQo,Comfy_GroupSelectedNodes_Padding:PQo,Comfy_Group_DoubleClickTitleToEdit:FQo,Comfy_LinkRelease_Action:IQo,Comfy_LinkRelease_ActionShift:LQo,Comfy_LinkRenderMode:RQo,Comfy_Load3D_3DViewerEnable:zQo,Comfy_Load3D_BackgroundColor:BQo,Comfy_Load3D_CameraType:VQo,Comfy_Load3D_LightAdjustmentIncrement:HQo,Comfy_Load3D_LightIntensity:UQo,Comfy_Load3D_LightIntensityMaximum:WQo,Comfy_Load3D_LightIntensityMinimum:GQo,Comfy_Load3D