ht:{name:`高度`},length:{name:`长度`},negative:{name:`negative`},positive:{name:`positive`},ref_max_size:{name:`参考最大尺寸`,tooltip:`reference_video和reference_images长边的最大尺寸。调整尺寸时保持宽高比，并对齐到16像素。`},reference_images:{name:`参考图像`},reference_video:{name:`参考视频`,tooltip:`要插入到源视频中的视频（ads2v）。`},source_video:{name:`源视频`,tooltip:`要编辑或重绘风格的视频（v2v，rv2v）。会被调整为指定宽高并裁剪到指定长度。`},vae:{name:`vae`},width:{name:`宽度`}},outputs:{0:{name:`positive`,tooltip:null},1:{name:`negative`,tooltip:null},2:{name:`latent`,tooltip:null}}},Abs={display_name:`Beta采样调度器`,inputs:{alpha:{name:`alpha`},beta:{name:`beta`},model:{name:`模型`},steps:{name:`步数`}},outputs:{0:{tooltip:null}}},jbs={description:`将块稀疏注意力应用于符合条件的模型注意力层，减少长序列的计算量。序列越长，速度提升越明显，因为短序列通常使用稠密注意力更快。在 start/end_percent 范围外、dense_blocks 以及低于 min_tokens 时，模型会使用稠密模型注意力后端。请使用“模型注意力后端”节点选择该回退后端。`,display_name:`模型稀疏注意力`,inputs:{dense_blocks:{name:`dense_blocks`,tooltip:`始终以稠密方式运行的 Transformer 块，例如“0, 1, 47-49”。`},end_percent:{name:`end_percent`,tooltip:`稀疏注意力结束的百分比位置。在此位置之后，注意力恢复为稠密。`},extra_tokens:{name:`extra_tokens`,tooltip:`除所选块外，每个查询块额外关注的高分 token。数值越高越接近稠密注意力，注意力耗时也越多；建议使用 256，设为 0 可禁用。VSA 会忽略此项。`},min_tokens:{name:`min_tokens`,tooltip:`短于此长度的序列保持使用稠密注意力。`},model:{name:`model`,tooltip:`要修补的模型。`},selection:{name:`selection`,tooltip:`用于选择进行完整词元级注意力的键块的方法。sol-attn：稀疏化在线注意力，对每个注意力头和查询块使用免训练的自适应阈值。sla：稀疏线性注意力，保留得分最高的键块中的固定百分比；仅可用于针对该模式训练的模型权重。vsa：视频稀疏注意力 (FastVideo)，使用 3D 视频立方体分块和学习得到的粗注意力分支；需要 FastH3 模型权重。`},selection_tau:{name:`tau`},sink_conditioning:{name:`sink_conditioning`,tooltip:`仅适用于 MiniMax-H3。exact_kv：每个查询都会精确关注打包的文本/音频/参考行（约占 3% 成本）。exact_kv_and_rows：此外会以稠密方式运行目标音频查询行（保持生成的音频完整）。`},start_percent:{name:`start_percent`,tooltip:`稀疏注意力开始的百分比位置。在此位置之前，注意力保持稠密。`},verbose:{name:`verbose`,tooltip:`记录每种注意力形状是否使用了稀疏注意力，或其保持稠密的原因。`}},outputs:{0:{name:`模型`,tooltip:`已应用块稀疏注意力的模型。`}}},Mbs={description:`使用 Bria 将纯文本描述的对象插入图像。Bria 会以约 100 万像素重新渲染整个画面，因此结果不会与输入图像像素对齐。`,display_name:`Bria 添加对象`,inputs:{control_after_generate:{name:`生成后控制`},image:{name:`图像`},instruction:{name:`指令`,tooltip:`要添加的内容及位置，例如“在桌上放置一个装有鲜花的红色花瓶”。`},moderation:{name:`内容审核`,tooltip:`内容审核设置`},seed:{name:`种子`,tooltip:`Bria 不使用此处的种子，每次调用都会重新构想编辑结果，因此重复运行可能不同。该值永远不会被发送：它只会更改此节点的缓存键，以便其他方面相同的工作流再次运行编辑，而不是返回缓存结果。`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`编辑后图像的结构化描述，用于后续通过 Bria FIBO Image Edit 进行编辑。`}}},Nbs={description:`使用 Bria 从图像中移除纯文本指定的对象。Bria 会以约 100 万像素重新渲染整个画面，因此结果不会与输入图像像素对齐。`,display_name:`Bria 按文本擦除`,inputs:{image:{name:`图像`},moderation:{name:`内容审核`,tooltip:`内容审核设置`},object_name:{name:`object_name`,tooltip:`要移除的对象名称，例如“台灯”。可同时指定多个对象，例如“手机和铅笔”。即使指定了图中不存在的内容，仍会返回重新渲染的图像并计费。`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`编辑后图像的结构化描述，用于后续通过 Bria FIBO Image Edit 进行编辑。`}}},Pbs={description:`使用 Bria 移除图像前景，并在其位置生成背景。Bria 识别为前景的所有内容都会被移除，不仅限于人物。未修改的像素会被保留，但输出会以接近 100 万像素的标准尺寸重新渲染。`,display_name:`Bria 擦除前景`,inputs:{image:{name:`图像`},moderation:{name:`内容审核`,tooltip:`内容审核设置`}},outputs:{0:{tooltip:null}}},Fbs={description:`使用 Bria 从图像中移除由蒙版勾勒出的对象或区域。`,display_name:`Bria 擦除`,inputs:{image:{name:`image`},mask:{name:`mask`,tooltip:`白色区域将被擦除，黑色区域将被保留。发送前会将蒙版二值化，因此部分涂绘的区域会被视为白色。必须与图像具有相同的宽高比。`},mask_type:{name:`mask_type`,tooltip:`手绘或画笔蒙版使用手动，SAM 等分割模型生成的蒙版使用自动。`},moderation:{name:`moderation`,tooltip:`审核设置`}},outputs:{0:{tooltip:null}}},Ibs={description:`使用 Bria 通过生成内容将图像扩展至其边界之外。`,display_name:`Bria 扩展图像`,inputs:{control_after_generate:{name:`control after generate`},expand_mode:{name:`expand_mode`,tooltip:`扩展后图像的目标形状：预设宽高比、自定义比例，或在画布上手动放置原始图像。只有手动模式可生成高度超过宽度两倍的画布。`},image:{name:`image`},moderation:{name:`moderation`,tooltip:`审核设置`},negative_prompt:{name:`negative_prompt`},prompt:{name:`prompt`,tooltip:`扩展场景的可选描述；留空时，Bria 会根据图像生成描述。`},seed:{name:`seed`}},outputs:{0:{tooltip:null},1:{name:`prompt`,tooltip:`用于扩展的提示词；当提示词输入为空时由 Bria 自动生成。`}}},Lbs={description:`使用 Bria 在图像的蒙版区域内生成对象或场景。`,display_name:`Bria 生成式填充`,inputs:{control_after_generate:{name:`生成后控制`},image:{name:`image`},mask:{name:`mask`,tooltip:`白色区域将填充生成内容，黑色区域将被保留。发送前会将蒙版二值化，因此部分涂绘的区域会被视为白色。必须与图像具有相同的宽高比。`},moderation:{name:`内容审核`,tooltip:`内容审核设置`},negative_prompt:{name:`negative_prompt`},prompt:{name:`prompt`,tooltip:`对要在蒙版区域内生成内容的描述。`},refine_prompt:{name:`refine_prompt`,tooltip:`自动调整提示词以获得更好的结果；禁用后将完全按原样使用提示词。`},seed:{name:`seed`}},outputs:{0:{tooltip:null}}},Rbs={description:`使用 Bria 最新模型编辑图像`,display_name:`Bria FIBO 图像编辑`,inputs:{control_after_generate:{name:`control after generate`},guidance_scale:{name:`guidance_scale`,tooltip:`数值越高，图像越贴合 prompt。`},image:{name:`image`},mask:{name:`mask`,tooltip:`如未指定，编辑将应用于整个图像。`},model:{name:`model`},moderation:{name:`moderation`,tooltip:`内容审核设置`},negative_prompt:{name:`negative_prompt`},prompt:{name:`prompt`,tooltip:`编辑图像的指令`},seed:{name:`seed`},steps:{name:`steps`},structured_prompt:{name:`structured_prompt`,tooltip:`包含结构化编辑提示的 JSON 字符串。使用此项可实现更精确、可编程的控制，替代常规 prompt。`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:null}}},zbs={description:`使用 Bria 将图像放大 2 倍或 4 倍，同时保留原始内容。`,display_name:`Bria 提高分辨率`,inputs:{auto_downscale:{name:`auto_downscale`,tooltip:`当输出超出限制时，自动降低倍数；如果仍不足，则缩小输入图像。`},desired_increase:{name:`desired_increase`,tooltip:`分辨率倍数。输出的每条边必须在 8192 像素以内。`},image:{name:`图像`},moderation:{name:`内容审核`,tooltip:`内容审核设置`}},outputs:{0:{tooltip:null}}},Bbs={description:`使用 Bria 更改图像的光照氛围和方向。Bria 会以约 100 万像素重新渲染整个画面，因此结果不会与输入图像像素对齐。`,display_name:`Bria 重塑光照`,inputs:{image:{name:`图像`},light_direction:{name:`light_direction`,tooltip:`光线的来源方向。正午、主体聚光灯和强烈影棚灯光等硬光氛围受此项影响最大。`},light_type:{name:`light_type`,tooltip:`要应用的光照氛围。`},moderation:{name:`内容审核`,tooltip:`内容审核设置`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`编辑后图像的结构化描述，用于后续通过 Bria FIBO Image Edit 进行编辑。`}}},Vbs={description:`使用 Bria RMBG 2.0 移除图像的背景。`,display_name:`Bria 移除图像背景`,inputs:{control_after_generate:{name:`生成后控制`},image:{name:`图像`},moderation:{name:`内容审核`,tooltip:`内容审核设置`},seed:{name:`种子`,tooltip:`种子控制节点是否重新运行；无论种子如何，结果都是非确定性的。`}},outputs:{0:{tooltip:null}}},Hbs={description:`使用 Bria 移除视频的背景。`,display_name:`Bria 移除视频背景`,inputs:{background_color:{name:`背景颜色`,tooltip:`输出视频的背景颜色。`},control_after_generate:{name:`生成后控制`},seed:{name:`种子`,tooltip:`种子控制节点是否重新运行；无论种子如何，结果都是非确定性的。`},video:{name:`视频`}},outputs:{0:{tooltip:null}}},Ubs={description:`使用 Bria 替换图像背景，可通过提示词描述或由参考图像引导。主体的像素会被保留，背景会围绕主体生成。`,display_name:`Bria 替换图像背景`,inputs:{background:{name:`背景`,tooltip:`使用提示词描述新背景，或使用参考图像进行引导。`},background_mode:{name:`模式`},background_prompt:{name:`提示词`},background_refine_prompt:{name:`优化提示词`},control_after_generate:{name:`生成后控制`},image:{name:`图像`},moderation:{name:`内容审核`,tooltip:`内容审核设置`},original_quality:{name:`原始质量`,tooltip:`返回与输入完全相同的像素尺寸，而不是将结果缩放至约 100 万像素。大尺寸输入将返回大图像。`},seed:{name:`种子`,tooltip:`相同的种子通常会返回相同的背景；自动提示词优化仍可能使其产生变化。`}},outputs:{0:{tooltip:null},1:{name:`优化后的提示词`,tooltip:`Bria 生成的提示词；使用参考图像路径时为空。`}}},Wbs={description:`使用 Bria 将图像中的对象替换为由纯文本描述的另一对象。Bria 会以约 100 万像素重新渲染整个画面，因此结果不会与输入在像素级对齐。`,display_name:`Bria 替换对象`,inputs:{control_after_generate:{name:`生成后控制`},image:{name:`图像`},instruction:{name:`指令`,tooltip:`要用什么替换什么，例如“将红苹果替换为绿梨”。`},moderation:{name:`内容审核`,tooltip:`内容审核设置`},seed:{name:`种子`,tooltip:`Bria 在此不使用种子，并会在每次调用时重新构想编辑内容，因此重复运行的结果可能不同。该值永远不会被发送：它只会更改此节点的缓存键，以便原本相同的工作流再次执行编辑，而不是返回缓存结果。`}},outputs:{0:{tooltip:null},1:{name:`结构化提示词`,tooltip:`已编辑图像的结构化描述，用于通过 Bria FIBO Image Edit 进行后续编辑。`}}},Gbs={description:`使用 Bria 将图像转换至另一季节。整个场景会被重新渲染，因此景物可能发生超出季节本身的变化。Bria 会以约 100 万像素重新渲染整个画面，因此结果不会与输入在像素级对齐。`,display_name:`Bria 季节转换`,inputs:{image:{name:`图像`},moderation:{name:`内容审核`,tooltip:`内容审核设置`},season:{name:`季节`,tooltip:`要应用的季节。`}},outputs:{0:{tooltip:null},1:{name:`结构化提示词`,tooltip:`已编辑图像的结构化描述，用于通过 Bria FIBO Image Edit 进行后续编辑。`}}},Kbs={description:`使用 Bria 修复老旧或损坏的照片：去除颗粒、划痕和模糊，并中和与年代相关的色偏。装裱卡纸和影楼边框可能会被裁掉，人脸会被重新绘制。Bria 会以约 100 万像素重新渲染整个画面，因此结果不会与输入在像素级对齐。若要放大，请改用 Bria Increase Resolution。`,display_name:`Bria 修复照片`,inputs:{image:{name:`图像`},moderation:{name:`内容审核`,tooltip:`内容审核设置`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`编辑后图像的结构