_freq:{name:`高頻截止`,tooltip:`高頻架濾波器截止頻率`},high_gain_dB:{name:`高頻增益（dB）`,tooltip:`高頻（高音）增益`},low_freq:{name:`低頻截止`,tooltip:`低頻架濾波器截止頻率`},low_gain_dB:{name:`低頻增益（dB）`,tooltip:`低頻（低音）增益`},mid_freq:{name:`中頻中心頻率`,tooltip:`中頻中心頻率`},mid_gain_dB:{name:`中頻增益（dB）`,tooltip:`中頻增益`},mid_q:{name:`中頻Q值`,tooltip:`中頻Q值（頻寬）`}},outputs:{0:{tooltip:null}}},mGs={description:`透過疊加波形來合併兩個音軌。`,display_name:`音訊合併`,inputs:{audio1:{name:`audio1`},audio2:{name:`audio2`},merge_method:{name:`merge_method`,tooltip:`用於合併音訊波形的方法。`}},outputs:{0:{tooltip:null}}},hGs={description:`將高面數網格的環境遮蔽貼圖烘焙至低面數網格的 UV 配置（白色＝無遮蔽，深色＝縫隙）。請提供已展開 UV 的 low_poly，以及其減面來源的 high_poly。輸出供「將紋理套用至網格」的 occlusion 輸入使用的灰階影像（封裝至 ORM 貼圖 / occlusionTexture）。`,display_name:`烘焙環境遮蔽`,inputs:{bias:{name:`bias`,tooltip:`光線起點離開表面的偏移量，以邊界方塊對角線的比例表示。若平坦表面也出現深色斑點／孔洞，請提高。`},high_poly:{name:`high_poly`},low_poly:{name:`low_poly`},max_distance:{name:`max_distance`,tooltip:`光線長度，以邊界方塊對角線的比例表示。較小＝較緊密、較局部的遮蔽。`},resolution:{name:`resolution`},samples:{name:`samples`,tooltip:`每個紋素的光線數。越多＝越平滑、越慢。有雜訊時請提高。`},strength:{name:`strength`,tooltip:`調整遮蔽強度。>1 變暗，<1 變亮。`}},outputs:{0:{name:`occlusion`,tooltip:null}}},gGs={description:`將高面數網格的切線空間法線貼圖（glTF/OpenGL +Y）烘焙至低面數網格的 UV 配置，擷取減面期間遺失的細節。請提供已展開 UV 的 low_poly，以及其減面來源的 high_poly。輸出供「將紋理套用至網格」的 normal_map 輸入使用的影像。`,display_name:`從網格烘焙法線貼圖`,inputs:{cage_distance:{name:`cage_distance`,tooltip:`表面搜尋範圍，以邊界方塊對角線的比例表示。大幅減面後出現錯誤或缺失區塊時請提高；若跨越間隙擷取到表面則降低。`},high_poly:{name:`high_poly`},ignore_backfaces:{name:`ignore_backfaces`,tooltip:`略過背向紋素的高面數表面，避免縫隙或封閉空間擷取到對側牆面。僅在 high_poly 的面繞序不一致時停用。`},low_poly:{name:`low_poly`},resolution:{name:`resolution`}},outputs:{0:{name:`normal_map`,tooltip:null}}},_Gs={description:`在網格既有的 UV 配置上烘焙 PBR 紋理（對稀疏體素體積進行三線性取樣）。不會展開 UV——請在上游連接 UV 展開節點。輸出 base_color 與 metallic/roughness 灰階 IMAGE（若無 PBR 則為黑色）；將其提供給 ApplyTextureToMesh（相同網格）以供 SaveGLB 使用。`,display_name:`從體素烘焙紋理`,inputs:{mesh:{name:`mesh`},reference_mesh:{name:`參考網格`,tooltip:`可選的高密度、簡化前網格；會在取樣前將每個紋素反向投影至其實際表面，消除粗略網格上的稜面化烘焙效果。`},texture_size:{name:`texture_size`,tooltip:`方形 UV 圖集解析度。`},voxel_colors:{name:`voxel_colors`}},outputs:{0:{name:`基礎顏色`,tooltip:null},1:{name:`金屬度`,tooltip:null},2:{name:`粗糙度`,tooltip:null}}},vGs={display_name:`基礎引導器`,inputs:{conditioning:{name:`條件設定`},model:{name:`model`}},outputs:{0:{tooltip:null}}},yGs={display_name:`BasicScheduler`,inputs:{denoise:{name:`去雜訊強度`},model:{name:`model`},scheduler:{name:`scheduler`},steps:{name:`步驟數`}},outputs:{0:{tooltip:null}}},bGs={display_name:`批次影像`,inputs:{images:{name:`影像`}},outputs:{0:{tooltip:null}}},xGs={display_name:`批次 latent`,inputs:{latents:{name:`latent`}},outputs:{0:{tooltip:null}}},SGs={display_name:`批次遮罩`,inputs:{masks:{name:`遮罩`}},outputs:{0:{tooltip:null}}},CGs={description:`使用 Beeble SwitchX 編輯單張圖像。可切換場景中的任何元素（背景、光線、服裝），同時保留原始主體像素。請提供參考圖像及／或文字提示以描述新外觀。最大約 2.77MP。`,display_name:`Beeble SwitchX 圖像編輯`,inputs:{alpha_mode:{name:`alpha 模式`,tooltip:`控制 SwitchX 如何決定保留或重建內容。「auto」自動分離主要主體。「fill」重建整個畫面並保留幾何結構。「select」將首幀關鍵影格套用至整個 clip。「custom」使用您提供的每幀 alpha 遮罩。`},control_after_generate:{name:`生成後控制`},image:{name:`圖像`},max_resolution:{name:`最大解析度`,tooltip:`輸出圖像的最大解析度。`},prompt:{name:`提示詞`,tooltip:`期望輸出內容的文字描述（最多 2000 字元）。「提示詞」或「參考圖像」至少需填寫一項。`},reference_image:{name:`參考圖像`,tooltip:`結果將採用此參考圖像的外觀（背景、光線、服裝）。「參考圖像」或「提示詞」至少需填寫一項。`},seed:{name:`種子`,tooltip:`種子控制此節點是否重新執行；無論種子為何，結果皆為非確定性。`}},outputs:{0:{name:`圖像`,tooltip:null},1:{name:`alpha`,tooltip:`Beeble 使用的 alpha 遮罩。「fill」模式下為空，無獨立遮罩。`}}},wGs={description:`使用 Beeble SwitchX 編輯影片。可切換場景中的任何元素（背景、光線、服裝），同時保留原始主體像素與動作。請提供參考圖像及／或文字提示以描述新外觀。最多 240 幀，每幀最大約 2.77MP。`,display_name:`Beeble SwitchX 影片編輯`,inputs:{alpha_mode:{name:`alpha 模式`,tooltip:`控制 SwitchX 如何決定保留或重建內容。「auto」自動分離主要主體。「fill」重建整個畫面並保留幾何結構。「select」將首幀關鍵影格套用至整個 clip。「custom」使用您提供的每幀 alpha 遮罩。`},control_after_generate:{name:`生成後控制`},max_resolution:{name:`最大解析度`,tooltip:`輸出影片的最大解析度。`},prompt:{name:`提示詞`,tooltip:`期望輸出內容的文字描述（最多 2000 字元）。「提示詞」或「參考圖像」至少需填寫一項。`},reference_image:{name:`參考圖像`,tooltip:`結果將採用此參考圖像的外觀（背景、光線、服裝）。「參考圖像」或「提示詞」至少需填寫一項。`},seed:{name:`種子`,tooltip:`種子控制此節點是否重新執行；無論種子為何，結果皆為非確定性。`},video:{name:`影片`}},outputs:{0:{name:`影片`,tooltip:null},1:{name:`alpha`,tooltip:`Beeble 使用的 alpha 遮罩。「fill」模式下為空，無獨立遮罩。`}}},TGs={description:`Bernini 內文影片/圖像條件設定節點。可用於以下任務：t2v（文字轉影片）、v2v（影片轉影片）、rv2v（參考引導影片編輯）、r2v（參考轉影片）、ads2v（將圖像/影片插入影片）。作為內文 token 注入的參考圖像（r2v、rv2v）會以其原生長寬比獨立編碼（長邊最大值為 ref_max_size）。`,display_name:`Bernini Conditioning`,inputs:{batch_size:{name:`批次大小`},height:{name:`高度`},length:{name:`長度`},negative:{name:`negative`},positive:{name:`positive`},ref_max_size:{name:`參考最大尺寸`,tooltip:`reference_video 與 reference_images 長邊的最大尺寸。會保持長寬比縮放並對齊至 16px。`},reference_images:{name:`參考圖像`},reference_video:{name:`參考影片`,tooltip:`要插入來源影片的影片（ads2v）。`},source_video:{name:`來源影片`,tooltip:`要編輯或重製風格的來源影片（v2v、rv2v）。會調整為指定寬高並裁剪至指定長度。`},vae:{name:`vae`},width:{name:`寬度`}},outputs:{0:{name:`positive`,tooltip:null},1:{name:`negative`,tooltip:null},2:{name:`latent`,tooltip:null}}},EGs={display_name:`BetaSamplingScheduler`,inputs:{alpha:{name:`alpha`},beta:{name:`beta`},model:{name:`model`},steps:{name:`步驟數`}},outputs:{0:{tooltip:null}}},DGs={description:`對符合條件的模型注意力層套用區塊稀疏注意力，以減少長序列的運算量。序列越長，速度提升越明顯，因為短序列通常使用密集注意力更快。在 start/end_percent 範圍外、使用 dense_blocks 時，以及 token 數低於 min_tokens 時，模型會使用密集模型注意力後端。請使用「模型注意力後端」節點選擇該備援後端。`,display_name:`模型區塊稀疏注意力`,inputs:{dense_blocks:{name:`dense_blocks`,tooltip:`一律以密集運算執行的 Transformer 區塊，例如「0, 1, 47-49」。`},end_percent:{name:`end_percent`,tooltip:`稀疏注意力結束的百分比位置。在此位置之後，注意力恢復為密集。`},extra_tokens:{name:`extra_tokens`,tooltip:`每個查詢區塊除了所選區塊外，還會關注額外得分最高的 token。數值越高，注意力運算越接近密集運算；建議為 256，設為 0 可停用。VSA 會忽略此設定。`},min_tokens:{name:`min_tokens`,tooltip:`短於此長度的序列會維持使用密集運算。`},model:{name:`model`,tooltip:`要修補的模型。`},selection:{name:`selection`,tooltip:`用於選擇進行完整 token 層級注意力之鍵區塊的方法。sol-attn：Sparsifying Online Attention 會針對每個注意力頭與查詢區塊使用免訓練的自適應閾值。sla：Sparse-Linear Attention 會保留固定百分比的最高分鍵區塊；僅適用於以此模式訓練的模型權重。vsa：Video Sparse Attention (FastVideo) 使用 3D 視訊立方體分塊與學習式粗略注意力分支；需要 FastH3 模型權重。`},selection_tau:{name:`tau`},sink_conditioning:{name:`sink_conditioning`,tooltip:`僅適用於 MiniMax-H3。exact_kv：每個查詢會精確關注已封裝的文字／音訊／參考列（約 3% 成本）。exact_kv_and_rows：另外以密集運算執行目標音訊查詢列（維持生成的音訊完整）。`},start_percent:{name:`start_percent`,tooltip:`稀疏注意力開始的百分比位置。在此位置之前，注意力維持密集。`},verbose:{name:`verbose`,tooltip:`記錄每種注意力形狀是否使用稀疏注意力，或維持密集的原因。`}},outputs:{0:{name:`模型`,tooltip:`已套用區塊稀疏注意力的模型。`}}},OGs={description:`使用 Bria 將以純文字描述的物件插入影像中。Bria 會以約 100 萬像素重新渲染整個畫面，因此結果不會與輸入影像的像素對齊。`,display_name:`Bria 新增物件`,inputs:{control_after_generate:{name:`生成後控制`},image:{name:`影像`},instruction:{name:`指示`,tooltip:`要新增的內容與位置，例如「在桌上放置一個插著花的紅色花瓶」。`},moderation:{name:`內容審核`,tooltip:`內容審核設定`},seed:{name:`種子`,tooltip:`Bria 在此不使用種子，且每次呼叫時都會重新構想編輯結果，因此重複執行的結果可能不同。此值永遠不會傳送：它只會變更此節點的快取鍵，讓原本相同的工作流程再次執行編輯，而非傳回快取的結果。`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`已編輯影像的結構化描述，供後續使用 Bria FIBO Image Edit 進行編輯。`}}},kGs={description:`使用 Bria 從影像中移除以純文字指定的物件。Bria 會以約 100 萬像素重新渲染整個畫面，因此結果不會與輸入影像的像素對齊。`,display_name:`Bria 依文字移除`,inputs:{image:{name:`影像`},moderation:{name:`內容審核`,tooltip:`內容審核設定`},object_name:{name:`物件名稱`,tooltip:`要移除的物件名稱，例如「檯燈」。可同時指定多個物件，例如「手機和鉛筆」。即使指定的物件不在圖片中，仍會傳回重新渲染的影像並計費。`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`已編輯影像的結構化描述，供後續使用 Bria FIBO Image Edit 進行編輯。`}}},AGs={description:`使用 Bria 移除影像前景，並在原處生成背景。Bria 判定為前景的所有內容都會被移除，不僅限於人物。未變更的像素會保留，但輸出會以接近 100 萬像素的標準尺寸重新渲染。`,display_name:`Bria 移除前景`,inputs:{image:{name:`影像`},moderation:{name:`內容審核`,tooltip:`內容審核設定`}},outputs:{0:{tooltip:null}}},jGs={description:`使用 Bria 從影像中移除由遮罩標示的物件或區域。`,display_name:`Bria 擦除`,inputs:{image:{name:`影像`},mask:{name:`遮罩`,tooltip:`白色區域會被擦除，黑色區域會保留。遮罩會在傳送前二值化，因此部分塗繪的區域會視為白色。必須與影像具有相同長寬比。`},mask_type:{name:`遮罩類型`,tooltip:`手繪或筆刷遮罩請使用手動；由 SAM 等分割模型產生的遮罩請使用自動。`},moderation:{name:`內容審核`,tooltip:`內容審核設定`}},outputs:{0:{tooltip:null}}},MGs={description:`使用 Bria 以生成內容將影像擴展至原有邊界之外。`,display_name:`Bria 擴展影像`,inputs:{control_after_generate:{name:`生成後控制`},expand_mode:{name:`擴展模式`,tooltip:`擴展後影像的目標形狀：預設長寬比、自訂比例，或在畫布上手動放置原始影像。只有手動模式可產生縱向比例超過 1:2 的畫布。`},image:{name:`影像`},moderation:{name:`內容審核`,tooltip:`內容審核設定`},negative_prompt:{name:`負面提示詞`},prompt:{name:`提示詞`,tooltip:`擴展場景的可選描述；留空時，Bria 會根據影像生成描述。`},seed:{name:`種子`}},outputs:{0:{tooltip:null},1:{name:`提示詞`,tooltip:`用於擴展的提示詞；提示詞輸入留空時由 Bria 自動生成。`}}},NGs={description:`使用 Bria 在影像的遮罩區域內生成物件或場景。`,display_name:`Bria 生成式填充`,inputs:{control_after_generate:{name:`生成後控制`},image:{name:`影像`},mask:{name:`遮罩`,tooltip:`白色區域會填入生成內容，黑色區域會保留。遮罩會在傳送前二值化，因此部分塗繪的區域會視為白色。必須與影像具有相同長寬比。`},moderation:{name:`內容審核`,tooltip:`內容審核設定`},negative_prompt:{name:`負面提示詞`},prompt:{name:`提示詞`,tooltip:`描述要在遮罩區域內生成的內容。`},refine_prompt:{name:`最佳化提示詞`,tooltip:`自動調整提示詞以獲得更佳結果；停用後會完全依照原提示詞。`},seed:{name:`種子`}},outputs:{0:{tooltip:null}}},PGs={description:`使用 Bria 最新模型編輯圖像`,display_name:`Bria FIBO 圖像編輯`,inputs:{control_after_generate:{name:`生成後控制`},guidance_scale:{name:`指引強度`,tooltip:`數值越高，圖像越貼合提示詞。`},image:{name:`圖像`},mask:{name:`遮罩`,tooltip:`若未設定，編輯將套用至整張圖像。`},model:{name:`model`},moderation:{name:`審核`,tooltip:`審核設定`},negative_prompt:{name:`負面提示詞`},prompt:{name:`提示詞`,tooltip:`編輯圖像的指令`},seed:{name:`種子`},steps:{name:`步數`},structured_prompt:{name:`結構化提示詞`,tooltip:`包含結構化編輯提示的 JSON 格式字串。若需精確、程式化控制，請使用此項取代一般提示詞。`}},outputs:{0:{tooltip:null},1:{name:`結構化提示詞`,tooltip:null}}},FGs={description:`使用 Bria 將圖像放大 2 倍或 4 倍，同時保留原始內容。`,display_name:`Bria 解析度提升`,inputs:{auto_downscale:{name:`auto_downscale`,tooltip:`當輸出超過限制時，自動降低倍率；若仍不足，則縮小輸入圖像。`},desired_increase:{name:`desired_increase`,tooltip:`解析度倍率。輸出影像的每一邊皆須在 8192 像素以內。`},image:{name:`圖像`},moderation:{name:`內容審核`,tooltip:`內容審核設定`}},outputs:{0:{tooltip:null}}},IGs={description:`使用 Bria 變更影像的光照氛圍與方向。Bria 會以約 100 萬像素重新渲染整個畫面，因此結果不會與輸入影像的像素對齊。`,display_name:`Bria 重新打光`,inputs:{image:{name:`影像`},light_direction:{name:`光線方向`,tooltip:`光線來源方向。正午、主體聚光燈及強烈棚燈等硬光氛圍對此設定的反應最明顯。`},light_type:{name:`光線類型`,tooltip:`要套用的光照氛圍。`},moderation:{name:`內容審核`,tooltip:`內容審核設定`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`已編輯影像的結構化描述，供後續使用 Bria FIBO Image Edit 進行編輯。`}}},LGs={description:`使用 Bria RMBG 2.0 移除影像的背景。`,display_name:`Bria 移除影像背景`,inputs:{control_after_generate:{name:`產生後控制`},image:{name:`影像`},moderation:{name:`審核`,tooltip:`審核設定`},seed:{name:`種子`,tooltip:`種子控制此節點是否重新執行；無論種子為何，結果皆為非決定性。`}},outputs:{0:{tooltip:null}}},RGs={description:`使用 Bria 移除影片的背景。`,display_name:`Bria 移除影片背景`,inputs:{background_color:{name:`背景顏色`,tooltip:`輸出影片的背景顏色。`},control_after_generate:{name:`產生後控制`},seed:{name:`種子`,tooltip:`種子控制此節點是否重新執行；無論種子為何，結果皆為非決定性。`},video:{name:`影片`}},outputs:{0:{tooltip:null}}},zGs={description:`使用 Bria 替換影像背景，可透過提示詞描述或由參考影像引導。主體的像素會保留，背景則會在其周圍生成。`,display_name:`Bria 替換影像背景`,inputs:{background:{name:`背景`,tooltip:`使用提示詞描述新背景，或以參考圖片引導。`},background_mode:{name:`模式`},background_prompt:{name:`提示詞`},background_refine_prompt:{name:`refine_prompt`},control_after_generate:{name:`生成後控制`},image:{name:`影像`},moderation:{name:`內容審核`,tooltip:`內容審核設定`},original_quality:{name:`original_quality`,tooltip:`傳回輸入內容的確切像素尺寸，而非將結果縮放至約 100 萬像素。輸入較大時，傳回的圖片也會較大。`},seed:{name:`種子`,tooltip:`相同種子通常會產生相同背景；自動提示詞精修仍可能造成差異。`}},outputs:{0:{tooltip:null},1:{name:`refined_prompt`,tooltip:`由 Bria 產生的提示詞；使用參考圖片流程時為空白。`}}},BGs={description:`使用 Bria 將圖片中的物件替換為以純文字描述的另一個物件。Bria 會以約 100 萬像素重新繪製整個畫面，因此結果不會與輸入內容像素對齊。`,display_name:`Bria 替換物件`,inputs:{control_after_generate:{name:`生成後控制`},image:{name:`圖片`},instruction:{name:`指令`,tooltip:`要將什麼替換成什麼，例如「將紅蘋果替換為綠梨」。`},moderation:{name:`內容審核`,tooltip:`內容審核設定`},seed:{name:`種子`,tooltip:`Bria 在此不接受種子，且每次呼叫都會重新構想編輯內容，因此重複執行可能不同。此值絕不會傳送：它只會變更此節點的快取金鑰，讓其他方面相同的工作流程再次執行編輯，而非傳回快取結果。`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`已編輯圖片的結構化描述，可用於後續以 Bria FIBO Image Edit 進行編輯。`}}},VGs={description:`使用 Bria 將圖片轉換為另一個季節。整個場景會重新繪製，因此景物的變化可能不僅限於季節本身。Bria 會以約 100 萬像素重新繪製整個畫面，因此結果不會與輸入內容像素對齊。`,display_name:`Bria 變換季節`,inputs:{image:{name:`圖片`},moderation:{name:`內容審核`,tooltip:`內容審核設定`},season:{name:`季節`,tooltip:`要套用的季節。`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`已編輯圖片的結構化描述，可用於後續以 Bria FIBO Image Edit 進行編輯。`}}},HGs={description:`使用 Bria 修復老舊或受損的照片：可去除顆粒、刮痕與模糊，並中和因年代造成的色偏。相片裱卡與攝影棚邊框可能會被裁切移除，且人臉會重新繪製。Bria 會以約 100 萬像素重新繪製整個畫面，因此結果不會與輸入內容像素對齊。若要放大，請改用 Bria Increase Resolution。`,display_name:`Bria 修復照片`,inputs:{image:{name:`圖片`},moderation:{name:`內容審核`,tooltip:`內容審核設定`}},outputs:{0:{tooltip:null},1:{name:`structured_prompt`,tooltip:`已編輯影像的結構化描述，供後續使用 Bria FIBO Image Edit 進行編輯。`}}},UGs={description:`使用 Bria 移除影片背景，並返回去背後的影格及 alpha 遮罩。可將兩者連接到合成節點，或傳送到『儲存 WEBM』以輸出透明影片。`,display_name:`Bria 移除影片背景（透明）`,inputs:{control_after_generate:{name:`生成後控制`},seed:{name:`種子`,tooltip:`種子控制此節點是否重新執行；無論種子為何，結果皆為非確定性。`},video:{name:`影片`}},outputs:{0:{name:`影像`,tooltip:null},1:{name:`遮罩`,tooltip:null}}},WGs={description:`使用 Bria 從影片中移除每個影格 mask 所覆蓋的內容，並填補空缺。mask 中應移除的部分必須為白色，其餘部分為黑色。Bria 最多接受長度 5.1 秒、每秒 20 至 30 個影格且像素尺寸為偶數的片段；預設會保留音訊。回傳的片段可能比輸入短幾個影格。`,display_name:`Bria 影片移除器`,inputs:{mask:{name:`mask`,tooltip:`影片中每個影格各一個 mask，要移除的物件所在處為白色。請提供 mask 或 mask 影片其中之一，不可同時提供。`},mask_video:{name:`mask_video`,tooltip:`已編碼的 mask 影片，尺寸和影格數須與影片相同。請提供 mask 或 mask 影片其中之一，不可同時提供。`},preserve_audio:{name:`preserve_audio`,tooltip:`保留輸入的音訊軌。`},video:{name:`video`,tooltip:`要移除內容的片段。`}},outputs:{0:{tooltip:null}}},GGs={description:`使用 Bria 將影片背景替換為純色色鍵（chroma-key）幕。`,display_name:`Bria Video 綠幕`,inputs:{control_after_generate:{name:`control after generate`},green_shade:{name:`green_shade`,tooltip:`套用於前景後方的純色色鍵色調：broadcast_green (#00B140)、chroma_green (#00FF00) 或 blue_screen (#0000FF)。`},seed:{name:`seed`,tooltip:`Seed 控制此節點是否重新執行；無論 seed 為何，結果皆為非確定性。`},video:{name:`video`}},outputs:{0:{tooltip:null}}},KGs={description:`使用 Bria 將影片的背景替換為提供的圖片或影片。輸出會保留前景的解析度與幀率；若背景的長寬比不同，將會被拉伸以符合，因此建議匹配長寬比以避免變形。`,display_name:`Bria 影片更換背景`,inputs:{background_image:{name:`背景圖片`,tooltip:`要合成於前景後方的背景圖片。請僅提供背景圖片或背景影片其中之一。`},background_video:{name:`背景影片`,tooltip:`要合成於前景後方的背景影片。請僅提供背景圖片或背景影片其中之一。`},control_after_generate:{name:`產生後控制`},seed:{name:`種子`,tooltip:`種子控制此節點是否重新執行；無論種子為何，結果皆為非確定性。`},video:{name:`影片`,tooltip:`要更換背景的前景影片。`}},outputs:{0:{tooltip:null}}},qGs={description:`為 Ideogram 4 模型建立 JSON 格式的提示詞。`,display_name:`建立 JSON 提示（Ideogram）`,inputs:{aesthetics:{name:`美學`,tooltip:`必填，美學關鍵詞（例如：情緒化、電影感、去飽和）。`},background:{name:`背景`,tooltip:`必填，圖像背景或環境的描述。`},color_palette:{name:`色板`,tooltip:`主導圖像色彩的十六進位色碼，最多 16 組。`},element:{name:`元素`,tooltip:`來自節點 Create Bounding Boxes 的提示元素。`},high_level_description:{name:`高階描述`,tooltip:`可選的圖像描述，一至兩句話。強烈建議填寫。`},lighting:{name:`光線`,tooltip:`必填，光線描述（例如：黃金時刻、邊緣光、戲劇性陰影）。`},medium:{name:`媒材`,tooltip:`必填，媒材類型（例如：攝影、插畫、3d_render、繪畫、平面設計）。當 style = photo 時，請設為攝影。`},style:{name:`風格`}},outputs:{0:{name:`提示詞`,tooltip:null}}},JGs={description:`從姿勢資料建立動畫 GLB，或儲存 BVH 動作捕捉檔案。`,display_name:`建立 3D 動畫檔案`,inputs:{camera_translation:{name:`camera_translation`,tooltip:`將 pred_cam_t 烘焙至根節點的平移。'off' = 綁定位置；'centered' = 相對於影格 0 的差值；'absolute' = 原始值（Z 為相機深度，通常以公尺為單位）。`},format:{name:`格式`,tooltip:`輸出格式，兩者皆會傳送至「儲存 3D 模型」以寫入磁碟。'glb' = 動畫 GLB（網格／骨骼／openpose／scail）。'bvh' = BVH 動作捕捉片段（單一骨架；需要模型）。`},format_bone_smooth_window:{name:`bone_smooth_window`},format_mesh_style:{name:`mesh_style`},format_mesh_style_bone_vis:{name:`bone_vis`},format_mesh_style_shader:{name:`shader`},fps:{name:`fps`,tooltip:`動畫影格率。`},pose_data:{name:`pose_data`,tooltip:`3D 姿勢資料。`},sam3d_body_model:{name:`sam3d_body_model`},track_index:{name:`track_index`,tooltip:`-1 = 所有軌道；≥0 = 單一軌道。`}},outputs:{0:{name:`model_3d`,tooltip:null}}},YGs={description:`輸出 Seedance 2.5 草稿的 1080p 最終影片。最終影片會保留草稿的場景與動作，並重複使用其提示詞、參考資料、時長、長寬比與音訊設定。`,display_name:`ByteDance Seedance 2.5 草稿轉最終影片`,inputs:{draft_task_id:{name:`draft_task_id`,tooltip:`使用 Seedance 2.5 Draft 模型執行之 Seedance 2.5 節點輸出的 draft_task_id，或貼上的草稿任務 ID。將該節點的種子控制設為固定；否則下次執行會產生新的草稿，而非重複使用您審閱過的草稿。草稿建立後可在 7 天內輸出。`},watermark:{name:`浮水印`,tooltip:`是否在影片中加入浮水印。`}},outputs:{0:{tooltip:null}}},XGs={description:`使用 Seedance 2.0，從首幀圖像與可選的末幀圖像產生影片。`,display_name:`ByteDance Seedance 2.0 首末幀轉影片`,inputs:{control_after_generate:{name:`產生後控制`},first_frame:{name:`首幀